insert into annew values
(1, 1, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The Nurse Anaesthetist programme in Nigeria is regulated and its graduates licensed by the:', '["Nursing and Midwifery Council of Nigeria", "Medical and Dental Council of Nigeria", "Nigerian Society of Anaesthetists", "Federal Ministry of Health only"]'::jsonb, 0, 'NMCN sets the curriculum, accredits schools and registers Nurse Anaesthetists. The programme runs for 18 months (three semesters).', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 2, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The main reason for training Nurse Anaesthetists in Nigeria is that:', '["Anaesthesia no longer needs medical knowledge", "Nurses are cheaper to train than all other staff", "Surgeons prefer not to work with physicians", "Physician anaesthetists are too few and poorly distributed"]'::jsonb, 3, 'The curriculum states that physician anaesthetists are inadequate in number and distribution to meet the demand at primary, secondary and tertiary levels.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 3, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Within the scope of practice, a Nurse Anaesthetist faced with a complication beyond their competence should:', '["Continue alone without telling anyone, so that blame is avoided", "Hand the patient over to the surgeon and leave the theatre", "Stop all monitoring until a doctor arrives in the theatre", "Keep the patient safe and consult the physician or senior anaesthetist"]'::jsonb, 3, 'The competencies include recognising complications and taking action in consultation with the Physician Anaesthetist or Senior Nurse Anaesthetist.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 4, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The first phase of the nursing process, in which the anaesthetic nurse collects a patient''s data, is:', '["Evaluation", "Implementation", "Assessment", "Planning"]'::jsonb, 2, 'Assessment builds the client''s database (subjective and objective data, from primary and secondary sources) before nursing diagnoses are made.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 5, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Information from the patient''s old anaesthetic chart is an example of:', '["A nursing diagnosis", "Secondary source data", "Subjective data", "Primary source data"]'::jsonb, 1, 'Primary data come directly from the patient. Records, relatives and other staff are secondary sources.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 6, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'NANDA-I, NIC and NOC are examples of:', '["Drug classification systems", "Anaesthetic machine checklists", "Pain assessment scales", "Standardised nursing languages"]'::jsonb, 3, 'NANDA-I gives nursing diagnoses, NIC gives nursing interventions and NOC gives nursing outcomes. They support documentation, research and education.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 7, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'NOC (Nursing Outcomes Classification) is used to:', '["List the nursing interventions to perform", "Describe and measure patient outcomes of nursing care", "Classify medical diagnoses for billing", "Grade the patient''s anaesthetic risk"]'::jsonb, 1, 'NOC outcomes have measurable indicators, so evaluation in the nursing process becomes objective.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 8, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Which nursing diagnosis is correctly written for a patient after general anaesthesia?', '["Give oxygen and suction secretions every hour as needed", "Post-operative patient after general anaesthesia for laparotomy", "Pneumonia related to aspiration of gastric contents", "Ineffective airway clearance related to secretions and residual sedation"]'::jsonb, 3, 'A nursing diagnosis has a problem statement (NANDA label) and related factors. Interventions and medical diagnoses are not nursing diagnoses.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 9, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'In the nursing process, setting priorities and choosing interventions happens during:', '["Planning", "Diagnosis", "Assessment", "Evaluation"]'::jsonb, 0, 'Planning includes setting priorities, writing goals and outcome criteria, selecting interventions and writing the care plan.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 10, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Reflective practice in nursing anaesthesia means:', '["Copying the routine of the senior anaesthetist without question", "Writing reports only when a complication occurs", "Thinking critically about one''s own practice to learn and improve", "Repeating procedures until they become automatic"]'::jsonb, 2, 'Reflection (e.g. Gibbs'' cycle) links experience to learning and supports professional development.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 11, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Maslow''s hierarchy is applied in anaesthesia by giving first priority to:', '["The patient''s privacy and dignity", "Psychological reassurance of relatives", "Airway, breathing and circulation", "Self-esteem and independence"]'::jsonb, 2, 'Physiological needs form the base of the hierarchy. Safety, belonging, esteem and self-actualisation follow once these are met.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 12, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Under Orem''s model, an anaesthetised and paralysed patient needs a nursing system that is:', '["Supportive-educative", "Wholly compensatory", "Partly compensatory", "Self-care only"]'::jsonb, 1, 'The patient cannot perform any self-care actions, so the nurse anaesthetist performs them all.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 13, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Erikson''s stage that is most relevant when preparing a 4-year-old for anaesthesia is:', '["Identity versus role confusion", "Trust versus mistrust", "Initiative versus guilt", "Integrity versus despair"]'::jsonb, 2, 'Pre-school children fear bodily harm and may see illness as punishment. Simple explanations, play and parental presence help.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 14, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Quality assurance in nursing anaesthesia is best described as:', '["Buying the most expensive equipment on the market", "Inspecting staff to find those who should be punished", "Setting standards, measuring practice and improving care", "Writing policies that are filed away and never used"]'::jsonb, 2, 'QA uses standards, audit and feedback. Nursing audit is one of its main tools.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 15, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A nursing audit that reviews completed patient records after discharge is called:', '["Peer appraisal", "Retrospective audit", "Prospective audit", "Concurrent audit"]'::jsonb, 1, 'Concurrent audit is done while the patient is still receiving care; retrospective audit uses records after discharge.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 16, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Before induction, the anaesthetic trolley set by the nurse must always include:', '["Plaster of Paris bandages, padding and a bowl of water", "Suction, airways, laryngoscopes, tubes, bougie and emergency drugs", "A sterile dressing pack, gauze swabs and suture material", "Only the induction drug, a syringe and a cannula for the case"]'::jsonb, 1, 'Equipment for airway rescue and emergency drugs must be checked and ready before every anaesthetic.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 17, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The best time to obtain a baseline set of vital signs for the anaesthetic record is:', '["At the end of surgery", "Before premedication and induction", "In the recovery room only", "After intubation is completed"]'::jsonb, 1, 'Baseline values allow later changes (e.g. hypotension after induction) to be judged correctly.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 18, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Problem-solving in anaesthesia is most effective when the nurse:', '["Identifies the problem, considers options, acts and evaluates", "Acts on the first idea without assessing the patient at all", "Repeats the same action again until the problem disappears", "Waits for the surgeon to decide on every problem that arises"]'::jsonb, 0, 'This systematic approach mirrors the nursing process and supports safe decisions in emergencies.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 19, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The ''health-illness continuum'' concept suggests that health is:', '["Simply the absence of any disease or physical infirmity", "A fixed state that does not change with age or illness", "A dynamic state that moves between wellness and illness", "Determined completely by the genes inherited from parents"]'::jsonb, 2, 'Patients may move along the continuum before, during and after surgery and anaesthesia.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 20, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Recording an anaesthetic chart accurately is important mainly because it:', '["Replaces the need for verbal handover", "Is a legal record and guides care and audit", "Is used only by the anaesthetist who wrote it", "Is required only for billing the patient"]'::jsonb, 1, 'The chart records drugs, doses, times, vital signs, fluids and events, and supports continuity, research and medico-legal defence.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 21, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'When checking vital signs during anaesthesia, the nurse anaesthetist relies on monitoring but also:', '["Observes the patient directly: colour, chest movement and pulse", "Leaves the room once monitors are attached", "Records values only every 30 minutes", "Turns off alarms so they do not disturb the surgeon"]'::jsonb, 0, 'Monitors can fail or give false values; clinical observation remains essential.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 22, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Interpersonal communication with the surgical team during anaesthesia should be:', '["Clear, timely and closed-loop", "Through the circulating nurse only", "Avoided to prevent distraction", "Limited to the end of the operation"]'::jsonb, 0, 'Closed-loop communication (instruction, read-back, confirmation) reduces errors, especially in crises.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 23, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Sterilisation of a reusable laryngoscope blade after use is best achieved by:', '["Wiping with a dry swab and returning it to the drawer", "Cleaning, then sterilisation or high-level disinfection", "Soaking in normal saline overnight in the sluice room", "Rinsing under the tap with water only, then air drying"]'::jsonb, 1, 'Laryngoscope blades contact mucous membranes (semi-critical items), so they need at least high-level disinfection after thorough cleaning.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 24, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The nurse anaesthetist sets up a trolley for a spinal anaesthetic. The correct technique is:', '["Clean technique with non-sterile gloves", "Opening the spinal pack early and leaving it uncovered", "Full aseptic technique with sterile gloves, drapes and skin prep", "No skin preparation if the skin looks clean"]'::jsonb, 2, 'Infection in the subarachnoid space (meningitis) is serious, so strict asepsis is required.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 25, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Critical thinking in nursing anaesthesia involves:', '["Relying on memory alone for drug doses and drug calculations", "Accepting every instruction without any thought or question", "Criticising colleagues openly in front of patients and relatives", "Questioning, analysing evidence and reasoning before acting"]'::jsonb, 3, 'Critical thinking leads to sound clinical judgement and safe decision-making.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 26, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The functional approach to nursing care means:', '["Each nurse performs specific tasks for many patients", "A team led by a nurse cares for a group", "One nurse gives total care to one patient", "The patient cares for themselves"]'::jsonb, 0, 'It is task-oriented and efficient but can fragment care. Team nursing and primary nursing are alternatives.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 27, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'System theory views a patient as:', '["A whole of interrelated parts interacting with the environment", "Separate organs that can each be treated quite independently", "A machine that only needs to be repaired when it breaks", "A closed system that is not affected by its surroundings"]'::jsonb, 0, 'A change in one part (e.g. hypoxia) affects the whole system; feedback loops maintain balance.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 28, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Expected outcomes written in a care plan should be:', '["Identical for every patient on the theatre list", "Nurse-centred, broad and general in wording", "Patient-centred, measurable and time-limited", "Written without any time frame for review"]'::jsonb, 2, 'Example: ''Patient maintains SpO₂ at or above 95% on room air within 2 hours of extubation.''', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 29, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A key responsibility of the nurse anaesthetist before elective surgery is to:', '["Assess the patient and identify anaesthetic risks", "Choose the surgical incision with the surgeon", "Order the surgical instruments for the case", "Obtain consent for the operation itself"]'::jsonb, 0, 'Pre-anaesthetic assessment includes history, examination, investigations, airway assessment and ASA grading.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 30, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Evaluation in the nursing process may result in:', '["Continuing, modifying or ending the care plan", "A new medical diagnosis made by the nurse", "Stopping all further nursing documentation", "Discharge of the patient without any review"]'::jsonb, 0, 'Evaluation compares outcomes with goals and decides whether the plan is working.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 31, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Which is an independent function of the nurse anaesthetist?', '["Deciding whether surgery is indicated at all", "Monitoring the patient and keeping the anaesthetic record", "Changing the operation that the surgeon is performing", "Prescribing chemotherapy for the patient''s cancer"]'::jsonb, 1, 'Practice spans dependent and independent functions; monitoring and record-keeping are core independent responsibilities.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 32, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Universal precautions when handling an anaesthetised patient''s secretions mean that:', '["Precautions apply only during surgery itself", "Every patient''s body fluids are treated as potentially infectious", "Only known HIV patients need gloves during suctioning", "Gloves are not needed for oral suction"]'::jsonb, 1, 'Gloves, eye protection and safe disposal protect staff during suction, intubation and extubation.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 33, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Patient-family teaching before anaesthesia is mainly aimed at:', '["Explaining the surgeon''s fees and the hospital charges", "Persuading the patient to accept the operation offered", "Reducing anxiety and improving cooperation and recovery", "Avoiding any questions from the patient''s family members"]'::jsonb, 2, 'Explaining fasting, what to expect on waking and pain relief improves outcomes.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 34, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The concept of ''team nursing'' in the anaesthesia department means:', '["Patients choose which nurse cares for them", "Each nurse does one task for all the patients", "Only the senior nurse cares for every patient", "A nurse-led team cares for a group of patients"]'::jsonb, 3, 'Team nursing combines skills and supervision; the leader assigns and coordinates care.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 35, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Documentation of an adverse event during anaesthesia should be:', '["Written to protect the team from blame", "Delayed until the end of the week", "Kept as a personal note only", "Factual, timely and objective"]'::jsonb, 3, 'Accurate incident reports support learning and legal protection.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 36, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The narrowest part of the airway in an adult is at the level of the:', '["Vocal cords (glottis)", "Carina", "Nasopharynx", "Cricoid cartilage"]'::jsonb, 0, 'In adults the glottis is the narrowest part; in young children the cricoid ring has traditionally been described as the narrowest part.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 37, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The trachea divides into the right and left main bronchi at the carina, at about the level of:', '["C6 (cricoid)", "L1", "T10", "T4–T5 (sternal angle)"]'::jsonb, 3, 'The carina is at the level of the sternal angle. An endotracheal tube tip should lie about 2–4 cm above it.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 38, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'An endotracheal tube that is too long most often enters the:', '["Right upper lobe bronchus", "Left main bronchus", "Oesophagus", "Right main bronchus"]'::jsonb, 3, 'The right main bronchus is shorter, wider and more vertical, so endobronchial intubation is usually right-sided, causing left lung collapse.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 39, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The muscle mainly responsible for quiet inspiration is the:', '["Rectus abdominis", "Sternocleidomastoid", "Internal intercostals", "Diaphragm"]'::jsonb, 3, 'The diaphragm is supplied by the phrenic nerve (C3, C4, C5). Accessory muscles are used during increased effort.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 40, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The phrenic nerve arises from:', '["C1 and C2", "L1 and L2", "C3, C4 and C5", "T1 and T2"]'::jsonb, 2, '''C3, 4 and 5 keep the diaphragm alive.'' A high spinal or cervical cord injury above C5 can stop diaphragmatic breathing.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 41, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The cricothyroid membrane, used for emergency airway access, lies between the:', '["Hyoid bone and thyroid cartilage", "Epiglottis and vocal cords", "Cricoid cartilage and first tracheal ring", "Thyroid cartilage and cricoid cartilage"]'::jsonb, 3, 'It is palpable in the midline of the neck and is relatively avascular, making it the site for cricothyroidotomy.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 42, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The normal tidal volume of an adult is approximately:', '["6–8 mL/kg (about 500 mL)", "30 mL/kg (about 2 L)", "2–3 mL/kg (about 150 mL)", "15–20 mL/kg (about 1.2 L)"]'::jsonb, 0, 'Lung-protective ventilation uses about 6–8 mL/kg of predicted body weight.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 43, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Anatomical dead space in an adult is approximately:', '["150 mL (about 2 mL/kg)", "500 mL (about 7 mL/kg)", "50 mL (about 0.5 mL/kg)", "1000 mL (about 15 mL/kg)"]'::jsonb, 0, 'Dead space is the conducting airway volume that does not take part in gas exchange. Breathing circuits and masks can add to it.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 44, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Gas exchange in the lungs occurs by:', '["Diffusion across the alveolar–capillary membrane", "Osmosis of gas through the walls of the bronchi", "Filtration of gas under the pressure of breathing", "Active transport by the alveolar lining cells"]'::jsonb, 0, 'Gases move from high to low partial pressure. Thickened membranes or reduced surface area impair diffusion.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 45, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Most oxygen in arterial blood is carried:', '["Bound to albumin", "Bound to haemoglobin", "As bicarbonate", "Dissolved in plasma"]'::jsonb, 1, 'About 98% is bound to haemoglobin. Each gram of Hb carries about 1.34 mL of oxygen when fully saturated.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 46, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Most carbon dioxide is transported in blood as:', '["Dissolved CO₂", "Carbonic acid", "Bicarbonate ions", "Carbaminohaemoglobin"]'::jsonb, 2, 'About 70% is carried as bicarbonate, formed in red cells by carbonic anhydrase; the rest is dissolved or bound to proteins.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 47, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Central cyanosis becomes visible when deoxygenated haemoglobin exceeds about:', '["5 g/dL", "10 g/dL", "1 g/dL", "15 g/dL"]'::jsonb, 0, 'Cyanosis is a late sign of hypoxia and may be absent in severe anaemia; pulse oximetry detects hypoxaemia earlier.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 48, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Hypoxia caused by carbon monoxide poisoning is mainly of which type?', '["Hypoxic (hypoxaemic) hypoxia", "Anaemic hypoxia", "Stagnant hypoxia", "Histotoxic hypoxia"]'::jsonb, 1, 'CO binds Hb much more tightly than O₂, reducing carrying capacity although PaO₂ may be normal. Pulse oximetry can read falsely normal.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 49, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Cyanide poisoning causes which type of hypoxia?', '["Hypoxaemic hypoxia", "Histotoxic hypoxia", "Stagnant hypoxia", "Anaemic hypoxia"]'::jsonb, 1, 'Cyanide blocks cytochrome oxidase so cells cannot use oxygen. It can occur with sodium nitroprusside infusion and smoke inhalation.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 50, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The main chemical stimulus for breathing in a healthy person is:', '["A rise in blood glucose", "A fall in body temperature", "A fall in arterial PaO₂", "A rise in arterial PaCO₂"]'::jsonb, 3, 'Central chemoreceptors respond to CO₂ (via CSF pH). Patients with chronic CO₂ retention may depend more on hypoxic drive.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 51, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The peripheral chemoreceptors that sense low PaO₂ are located in the:', '["Alveolar walls", "Hypothalamus", "Carotid and aortic bodies", "Medulla oblongata"]'::jsonb, 2, 'They respond mainly to hypoxaemia and send impulses via the glossopharyngeal and vagus nerves.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 52, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Functional residual capacity (FRC) is reduced under general anaesthesia, which leads to:', '["Less shunt through the lungs and better oxygenation", "Atelectasis and faster desaturation during apnoea", "A higher oxygen reserve during apnoea at induction", "No change in oxygenation or in the lung volumes"]'::jsonb, 1, 'FRC is the oxygen store during apnoea. It falls further with obesity, pregnancy and the supine position.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 53, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Compliance of the lungs is defined as:', '["The rate of breathing per minute", "Resistance to gas flow in the airways", "Change in volume per unit change in pressure", "The amount of oxygen absorbed per minute"]'::jsonb, 2, 'Low compliance (stiff lungs) occurs in ARDS, pulmonary oedema and fibrosis; higher pressures are needed to deliver a breath.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 54, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The functional unit of the kidney is the:', '["Nephron", "Ureter", "Glomerulus only", "Renal pelvis"]'::jsonb, 0, 'Each kidney has about one million nephrons, each with a glomerulus and a tubule.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 55, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Normal glomerular filtration rate (GFR) in an adult is about:', '["500 mL/min", "1000 mL/min", "25 mL/min", "125 mL/min"]'::jsonb, 3, 'GFR falls with age and renal disease. Drugs excreted by the kidney (e.g. some muscle relaxants) need dose adjustment.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 56, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Antidiuretic hormone (ADH) acts on the kidney to:', '["Reduce glomerular filtration in the kidney", "Increase potassium reabsorption in the tubule", "Increase sodium excretion in the urine", "Increase water reabsorption in the collecting ducts"]'::jsonb, 3, 'ADH is released from the posterior pituitary in response to high osmolality and hypovolaemia; surgery and pain increase it.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 57, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Aldosterone causes the kidney to:', '["Excrete sodium and retain potassium", "Retain calcium and excrete phosphate", "Retain sodium and excrete potassium", "Excrete water without sodium"]'::jsonb, 2, 'It is produced by the adrenal cortex in response to the renin-angiotensin system and high potassium.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 58, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Renin is released from the juxtaglomerular apparatus when:', '["Renal perfusion pressure falls", "Blood glucose falls", "Blood pressure rises", "Plasma sodium rises"]'::jsonb, 0, 'Renin converts angiotensinogen to angiotensin I, leading to angiotensin II (vasoconstriction) and aldosterone release.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 59, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Most filtered sodium and water are reabsorbed in the:', '["Collecting duct", "Proximal convoluted tubule", "Loop of Henle", "Distal convoluted tubule"]'::jsonb, 1, 'About 65% is reabsorbed in the proximal tubule. Loop diuretics act on the thick ascending limb of the loop of Henle.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 60, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Drugs that depend heavily on the kidney for elimination may accumulate after anaesthesia in patients with:', '["Mild anaemia", "Renal failure", "Previous appendicectomy", "Hypertension controlled by drugs"]'::jsonb, 1, 'Examples include morphine metabolites, pancuronium and gentamicin. Doses are reduced and effects monitored.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 61, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The minimum acceptable hourly urine output for a 60 kg adult under anaesthesia is about:', '["100 mL", "30 mL", "5 mL", "300 mL"]'::jsonb, 1, '0.5 mL/kg/hour × 60 kg = 30 mL/hour. Lower outputs suggest hypovolaemia or renal hypoperfusion.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 62, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The oxyhaemoglobin dissociation curve shifts to the left in:', '["Raised 2,3-DPG", "High PaCO₂ and exercise", "Fever and acidosis", "Hypothermia and alkalosis"]'::jsonb, 3, 'A left shift increases Hb''s affinity for oxygen, so less oxygen is released to tissues.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 63, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The P50 of normal adult haemoglobin (PaO₂ at 50% saturation) is about:', '["8 kPa (60 mmHg)", "13 kPa (100 mmHg)", "1 kPa (7 mmHg)", "3.5 kPa (27 mmHg)"]'::jsonb, 3, 'A higher P50 indicates a right shift (easier oxygen release); a lower P50 indicates a left shift.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 64, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The epiglottis is attached to the:', '["First tracheal ring", "Cricoid cartilage", "Thyroid cartilage", "Hyoid bone only"]'::jsonb, 2, 'During laryngoscopy, a curved (Macintosh) blade tip goes into the vallecula, lifting the epiglottis indirectly.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 65, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The vocal cords are mainly supplied by the:', '["Glossopharyngeal nerve", "Hypoglossal nerve", "Recurrent laryngeal nerve", "Superior laryngeal nerve only"]'::jsonb, 2, 'The recurrent laryngeal nerve supplies all intrinsic laryngeal muscles except cricothyroid (external branch of the superior laryngeal nerve).', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 66, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Hypoxic pulmonary vasoconstriction refers to:', '["Systemic arteries constrict throughout the body in hypoxia", "Bronchi narrow in response to a low oxygen level", "Pulmonary vessels constrict in poorly ventilated lung", "Pulmonary vessels dilate wherever oxygen is low"]'::jsonb, 2, 'It diverts blood to better-ventilated areas, improving V/Q matching. Volatile agents can blunt it.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 67, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'A right-to-left shunt causes hypoxaemia that:', '["Responds poorly to increased inspired oxygen", "Is caused only by hypoventilation", "Responds fully to increased inspired oxygen", "Is always corrected by hyperventilation"]'::jsonb, 0, 'Shunted blood bypasses ventilated alveoli, so extra oxygen cannot reach it. Atelectasis and pneumonia are common causes.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 68, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The pleural space normally contains:', '["Air at atmospheric pressure", "Blood at venous pressure", "No fluid or air of any kind", "A thin film of fluid at negative pressure"]'::jsonb, 3, 'Negative intrapleural pressure keeps the lungs expanded. Air (pneumothorax) or blood breaks this seal.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 69, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The right lung differs from the left lung in that it has:', '["A cardiac notch", "Two lobes", "A lingula", "Three lobes"]'::jsonb, 3, 'The left lung has two lobes, a cardiac notch and the lingula.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 70, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The kidneys receive about what proportion of the cardiac output at rest?', '["20–25%", "50%", "75%", "5%"]'::jsonb, 0, 'This high flow makes the kidneys vulnerable to hypotension and hypovolaemia during anaesthesia.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 71, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Boyle''s law states that at constant temperature:', '["Pressure × volume is constant", "Gas dissolves in proportion to pressure", "Volume is proportional to temperature", "Pressure is proportional to temperature"]'::jsonb, 0, 'As a cylinder empties at constant temperature, pressure falls in proportion to the gas remaining (for gases stored as gas, such as oxygen).', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 72, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Charles'' law states that at constant pressure, the volume of a gas is:', '["Inversely proportional to its pressure", "Proportional to its solubility", "Directly proportional to its absolute temperature", "Independent of temperature"]'::jsonb, 2, 'Warming a gas expands it; cooling causes contraction.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 73, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Henry''s law states that the amount of gas dissolved in a liquid is:', '["Proportional to the volume of the liquid only", "Independent of both temperature and pressure", "Inversely proportional to the pressure of that gas", "Proportional to the partial pressure of that gas"]'::jsonb, 3, 'This explains why giving more oxygen raises dissolved oxygen in plasma, and why volatile agents dissolve in blood.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 74, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Dalton''s law states that in a mixture of gases:', '["The heaviest gas exerts all the pressure", "Each gas exerts its partial pressure as if alone", "Gases do not mix at body temperature", "The total pressure equals the lightest gas pressure"]'::jsonb, 1, 'Total pressure equals the sum of partial pressures. For example, in air at 101 kPa, oxygen exerts about 21 kPa.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 75, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'A full nitrous oxide cylinder''s pressure gauge does not fall until the cylinder is about three-quarters empty because:', '["It is stored as a liquid in equilibrium with its vapour", "The cylinder is warmed by room air, keeping pressure up", "Nitrous oxide expands to fill the cylinder as it is used", "The gauge is calibrated for oxygen and so reads wrongly"]'::jsonb, 0, 'Pressure stays at the saturated vapour pressure while liquid remains. The contents are judged by weighing the cylinder.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 76, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Flow through a tube is laminar when it is:', '["Turbulent, with eddies at high flows", "Dependent mainly on gas density", "Smooth, and flow is proportional to pressure", "Only seen at very high flow rates"]'::jsonb, 2, 'In laminar flow (Hagen-Poiseuille), flow depends on viscosity and the fourth power of the radius.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 77, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Halving the radius of an endotracheal tube in laminar flow increases resistance by about:', '["2 times", "8 times", "16 times", "4 times"]'::jsonb, 2, 'Resistance is inversely proportional to radius to the fourth power, so small tubes greatly increase the work of breathing.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 78, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Heliox (helium-oxygen) improves flow through a narrowed airway because helium:', '["Has low density, reducing turbulence", "Increases oxygen carrying capacity", "Dilates the airway smooth muscle", "Has high viscosity, improving laminar flow"]'::jsonb, 0, 'Turbulent flow depends on density. Helium''s low density makes flow more laminar through tight obstructions.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 79, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Saturated vapour pressure of a volatile agent depends mainly on:', '["The size of the vaporiser", "The fresh gas flow rate", "Temperature", "Atmospheric pressure"]'::jsonb, 2, 'SVP rises with temperature. Modern vaporisers are temperature-compensated to keep output constant.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 80, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'As a volatile agent vaporises, the liquid cools because of:', '["Loss of latent heat of vaporisation", "Expansion of the carrier gas", "Compression in the vaporiser chamber", "Gain of specific heat from the room"]'::jsonb, 0, 'Cooling reduces SVP and output; temperature compensation (e.g. bimetallic strip) corrects this.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 81, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Temperature compensation in a plenum vaporiser is commonly provided by a:', '["An electric heater in the fresh gas line", "A bimetallic strip or expanding element", "A pressure gauge mounted at the outlet", "A glass thermometer inside the chamber"]'::jsonb, 1, 'As temperature falls, more carrier gas is diverted through the vaporising chamber to maintain output.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 82, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'The critical temperature of a gas is the temperature above which it:', '["Becomes flammable when it is mixed with room air", "Dissolves completely in water and in plasma", "Boils at normal atmospheric pressure at sea level", "Cannot be liquefied however much pressure is applied"]'::jsonb, 3, 'Oxygen''s critical temperature is about −119 °C, so it is a gas in cylinders. Nitrous oxide (36.5 °C) can be stored as a liquid.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 83, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'The main source of ignition for theatre fires is:', '["Diathermy and lasers", "Blood pressure cuffs", "Cold surgical instruments", "Fluorescent lights"]'::jsonb, 0, 'The fire triangle is fuel (drapes, alcohol prep), oxidiser (oxygen, nitrous oxide) and ignition (diathermy, laser).', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 84, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'To reduce airway fire risk during laser surgery of the larynx, the anaesthetist should:', '["Use a standard PVC tube without protection", "Use 100% oxygen throughout the procedure", "Use the lowest safe FiO₂ and avoid nitrous oxide", "Use nitrous oxide to deepen anaesthesia"]'::jsonb, 2, 'Both oxygen and nitrous oxide support combustion. Laser-resistant tubes with saline-filled cuffs are used.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 85, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Static electricity in theatre is reduced by:', '["Keeping humidity very low", "Antistatic flooring and controlled humidity", "Wearing wool clothing", "Using rubber-soled insulated shoes only"]'::jsonb, 1, 'Humidity of about 50% and conductive floors help dissipate static charge.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 86, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'The Venturi principle is used in:', '["Self-inflating resuscitation bags", "Non-rebreather masks with a reservoir", "Nasal cannulae at low oxygen flows", "Fixed-performance (Venturi) oxygen masks"]'::jsonb, 3, 'Gas flowing through a constriction speeds up and its pressure falls, entraining air in a fixed ratio to give a set FiO₂.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 87, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'A Bourdon gauge on a gas cylinder measures:', '["Concentration", "Pressure", "Flow rate", "Temperature"]'::jsonb, 1, 'A curved tube straightens as pressure rises, moving a pointer. Rotameters measure flow.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 88, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'A rotameter (flowmeter) bobbin should be read at its:', '["Middle", "Top", "Bottom", "Side"]'::jsonb, 1, 'Ball floats are read at the centre. Rotameters are calibrated for a specific gas.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 89, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Osmosis is the movement of:', '["Gas moving from an area of high pressure to an area of low pressure", "Ions moving against their gradient using energy from ATP", "Solute moving across a membrane towards higher solute concentration", "Water moving across a membrane towards higher solute concentration"]'::jsonb, 3, 'Mannitol works osmotically. Plasma osmolality is normally about 285–295 mOsm/kg.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 90, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'A solution with the same osmolality as plasma is described as:', '["Isotonic", "Hypotonic", "Colloid", "Hypertonic"]'::jsonb, 0, '0.9% saline and Hartmann''s solution are approximately isotonic.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 91, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Giving large volumes of 5% dextrose alone after surgery risks:', '["Metabolic alkalosis", "Hyponatraemia", "Hyperkalaemia", "Hypernatraemia"]'::jsonb, 1, 'Once glucose is metabolised, free water remains. ADH release after surgery makes this worse.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 92, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Normal plasma bicarbonate is about:', '["135–145 mmol/L", "22–26 mmol/L", "5–10 mmol/L", "35–45 mmol/L"]'::jsonb, 1, 'Bicarbonate falls in metabolic acidosis and rises in metabolic alkalosis.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 93, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Arterial blood gas pH 7.25, PaCO₂ 8.5 kPa (64 mmHg), HCO₃⁻ 26 mmol/L indicates:', '["Metabolic acidosis", "Metabolic alkalosis", "Acute respiratory acidosis", "Respiratory alkalosis"]'::jsonb, 2, 'High CO₂ with low pH and normal bicarbonate (no time to compensate) is acute respiratory acidosis, e.g. hypoventilation from opioids.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 94, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'A patient with prolonged vomiting from pyloric obstruction usually develops:', '["Respiratory acidosis", "Lactic acidosis", "Hyperchloraemic metabolic acidosis", "Hypochloraemic metabolic alkalosis"]'::jsonb, 3, 'Loss of gastric acid (HCl) causes alkalosis; potassium is also lost.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 95, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'The anion gap is calculated as:', '["HCO₃⁻ − Cl⁻", "Na⁺ + K⁺ + Cl⁻", "Cl⁻ − Na⁺", "Na⁺ − (Cl⁻ + HCO₃⁻)"]'::jsonb, 3, 'Normal is about 8–12 mmol/L. A raised gap suggests lactic acidosis, ketoacidosis, renal failure or poisoning.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 96, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'On an erect chest X-ray, air under the diaphragm suggests:', '["Pulmonary oedema", "Normal post-feeding gas", "Pleural effusion", "A perforated hollow viscus"]'::jsonb, 3, 'Pneumoperitoneum indicates perforation (e.g. peptic ulcer) unless after recent laparotomy or laparoscopy.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 97, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Multiple air-fluid levels on an erect abdominal X-ray suggest:', '["Perforated ulcer", "Intestinal obstruction", "Renal stones", "Normal bowel"]'::jsonb, 1, 'Patients with obstruction have a full stomach risk and need rapid sequence induction.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 98, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'On a chest X-ray, an endotracheal tube tip is ideally:', '["In the right main bronchus", "At the vocal cords", "About 2–4 cm above the carina", "Below the carina"]'::jsonb, 2, 'Too low risks endobronchial intubation; too high risks accidental extubation.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 99, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Intravenous urography (IVU) mainly shows:', '["Kidneys, ureters and bladder, using contrast", "Bones of the spine and pelvis, without contrast", "Heart chambers and valves, using sound waves", "Cerebral vessels, using a catheter in the groin"]'::jsonb, 0, 'Contrast risks include allergy and nephropathy; renal function is checked before.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 100, 'Anaesthesia Nursing Mock — Day 1 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'The role of the nurse anaesthetist with X-rays includes:', '["Formal radiology reporting for all films", "Taking X-rays without any radiographer", "Simple interpretation such as tube position", "Deciding radiation doses for each film"]'::jsonb, 2, 'Recognising important findings allows quick action and informing the doctor.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(2, 1, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Pharmacokinetics describes:', '["What a drug does to the body", "How drugs are manufactured", "What the body does to a drug", "How drugs are priced and sold"]'::jsonb, 2, 'Pharmacokinetics covers absorption, distribution, metabolism and excretion. Pharmacodynamics describes drug effects and mechanisms.', 'NAP 413 · Applied Pharmacology I'),
(2, 2, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'The bioavailability of a drug given intravenously is:', '["About 75%", "Variable, usually under 30%", "100%", "About 50%"]'::jsonb, 2, 'IV drugs reach the systemic circulation completely. Oral drugs lose some to incomplete absorption and first-pass metabolism.', 'NAP 413 · Applied Pharmacology I'),
(2, 3, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'First-pass metabolism refers to drug breakdown:', '["In the gut wall and liver before reaching the systemic circulation", "In muscle after intramuscular injection", "In the kidney after reaching the systemic circulation", "In the lungs after intravenous injection"]'::jsonb, 0, 'Drugs with high first-pass metabolism (e.g. oral morphine, GTN) need higher oral doses or other routes.', 'NAP 413 · Applied Pharmacology I'),
(2, 4, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'The half-life of a drug is the time taken for:', '["The full effect of the drug to appear", "Half the dose to be absorbed", "The plasma concentration to fall by half", "The drug to be fully excreted"]'::jsonb, 2, 'About 4–5 half-lives are needed to reach steady state or to eliminate most of a drug.', 'NAP 413 · Applied Pharmacology I'),
(2, 5, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Volume of distribution is large for a drug that:', '["Stays mainly in the plasma, tightly bound to albumin", "Is excreted unchanged by the kidney within minutes", "Is highly water-soluble and ionised in the blood", "Is lipid-soluble and widely distributed into tissues"]'::jsonb, 3, 'Fentanyl and propofol have large volumes of distribution; neuromuscular blockers have small ones.', 'NAP 413 · Applied Pharmacology I'),
(2, 6, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A drug that binds to a receptor and produces a full response is a:', '["Partial agonist", "Inverse agonist", "Full agonist", "Competitive antagonist"]'::jsonb, 2, 'Morphine is a full mu-opioid agonist; buprenorphine is a partial agonist; naloxone is an antagonist.', 'NAP 413 · Applied Pharmacology I'),
(2, 7, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A competitive antagonist''s effect can be overcome by:', '["Reducing the dose of the agonist", "Waiting for the receptor to be destroyed", "Giving a second antagonist", "Increasing the dose of the agonist"]'::jsonb, 3, 'Competitive antagonists bind reversibly to the same receptor. Non-competitive antagonism cannot be overcome this way.', 'NAP 413 · Applied Pharmacology I'),
(2, 8, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'The therapeutic index of a drug is the ratio of:', '["Toxic dose to effective dose", "Peak level to trough level", "Effective dose to lethal dose", "Oral dose to IV dose"]'::jsonb, 0, 'A low therapeutic index (e.g. digoxin) means toxicity is close to the effective dose.', 'NAP 413 · Applied Pharmacology I'),
(2, 9, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Most drugs are metabolised in the liver by:', '["Renal tubular enzymes", "Red cell carbonic anhydrase", "Plasma cholinesterase", "Cytochrome P450 enzymes"]'::jsonb, 3, 'Enzyme inducers (e.g. rifampicin, carbamazepine) and inhibitors (e.g. erythromycin) change the effect of other drugs.', 'NAP 413 · Applied Pharmacology I'),
(2, 10, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Enzyme induction by phenytoin or rifampicin tends to:', '["Reduce the effect of drugs broken down by the liver", "Increase the effect of all the other drugs given", "Have no effect at all on any other drug given", "Reduce the renal excretion of most other drugs"]'::jsonb, 0, 'Induction speeds metabolism; for example, it may reduce the effect of warfarin and some anaesthetic drugs.', 'NAP 413 · Applied Pharmacology I'),
(2, 11, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A drug highly bound to plasma albumin may cause toxicity in a patient with:', '["Mild hypertension", "Low serum albumin", "Normal renal function", "High serum albumin"]'::jsonb, 1, 'Less binding leaves more free (active) drug. Examples include phenytoin and warfarin.', 'NAP 413 · Applied Pharmacology I'),
(2, 12, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Zero-order kinetics means that:', '["A constant fraction is eliminated per unit time", "A constant amount of drug is eliminated per unit time", "Elimination depends only on renal function", "The drug is never eliminated"]'::jsonb, 1, 'Alcohol, phenytoin and high-dose aspirin show zero-order (saturable) kinetics, so levels can rise sharply.', 'NAP 413 · Applied Pharmacology I'),
(2, 13, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'The ''rights'' of medication administration include right patient, drug, dose, route, time and:', '["Diagnosis", "Doctor''s signature only", "Hospital ward", "Documentation"]'::jsonb, 3, 'Right reason and right response are often added. Errors are prevented by careful checking.', 'NAP 413 · Applied Pharmacology I'),
(2, 14, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Drugs of addiction (controlled drugs) in theatre must be:', '["Kept on the open anaesthetic trolley for quick access in theatre", "Locked, counted and recorded in a register with two signatures", "Given in emergencies without any documentation at all", "Recorded only at the end of the month by the pharmacist"]'::jsonb, 1, 'Opioids such as morphine, pethidine and fentanyl are controlled drugs; wastage is witnessed and recorded.', 'NAP 413 · Applied Pharmacology I'),
(2, 15, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A syringe of drug drawn up for anaesthesia should be:', '["Labelled at once with drug name and concentration", "Left unlabelled if it will be used within one hour", "Identified by the colour of the syringe plunger", "Labelled only after the drug has been given"]'::jsonb, 0, 'Unlabelled syringes are a common cause of drug errors. Standard colour-coded labels are recommended.', 'NAP 413 · Applied Pharmacology I'),
(2, 16, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'The concentration of a 1% solution is:', '["100 mg/mL", "10 mg/mL", "1 mg/mL", "0.1 mg/mL"]'::jsonb, 1, '1% = 1 g per 100 mL = 1000 mg/100 mL = 10 mg/mL. So 2% lidocaine is 20 mg/mL.', 'NAP 413 · Applied Pharmacology I'),
(2, 17, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Adrenaline 1:1000 contains:', '["0.1 mg/mL", "1 mg/mL", "0.01 mg/mL", "10 mg/mL"]'::jsonb, 1, '1:1000 = 1 g in 1000 mL = 1 mg/mL. 1:10 000 = 0.1 mg/mL; 1:200 000 = 5 micrograms/mL.', 'NAP 413 · Applied Pharmacology I'),
(2, 18, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'How many mL of 1% propofol are needed to give 150 mg?', '["15 mL", "150 mL", "10 mL", "1.5 mL"]'::jsonb, 0, '1% propofol = 10 mg/mL. 150 ÷ 10 = 15 mL.', 'NAP 413 · Applied Pharmacology I'),
(2, 19, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'An infusion of 500 mL is to run over 4 hours with a giving set of 20 drops/mL. The drip rate is about:', '["84 drops/min", "125 drops/min", "21 drops/min", "42 drops/min"]'::jsonb, 3, '(500 × 20) ÷ (4 × 60) = 10 000 ÷ 240 ≈ 42 drops per minute.', 'NAP 413 · Applied Pharmacology I'),
(2, 20, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'An adverse drug reaction that is unpredictable and not dose-related is called:', '["Type A (augmented, dose-related)", "Type B (idiosyncratic or allergic)", "Type D (delayed, after many years)", "Type C (chronic, long-term use)"]'::jsonb, 1, 'Type A reactions are predictable extensions of the drug''s action; type B include anaphylaxis and malignant hyperthermia.', 'NAP 413 · Applied Pharmacology I'),
(2, 21, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Tolerance to a drug means:', '["A lower dose now gives a stronger effect", "The drug has begun to cause an allergy", "The patient is unable to stop the drug", "A higher dose is needed for the same effect"]'::jsonb, 3, 'Patients on long-term opioids are tolerant and may need more analgesia after surgery.', 'NAP 413 · Applied Pharmacology I'),
(2, 22, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Two drugs given together that produce a greater effect than the sum of each alone show:', '["Antagonism", "Synergism", "Tolerance", "Tachyphylaxis"]'::jsonb, 1, 'Opioids and benzodiazepines act synergistically on breathing, increasing the risk of respiratory depression.', 'NAP 413 · Applied Pharmacology I'),
(2, 23, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Tachyphylaxis is:', '["A drug interaction with food in the stomach", "A slow increase in effect with each dose", "A rapidly falling response to repeated doses", "An allergic reaction to the very first dose"]'::jsonb, 2, 'Ephedrine shows tachyphylaxis because it releases noradrenaline stores that become depleted.', 'NAP 413 · Applied Pharmacology I'),
(2, 24, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A drug given by the sublingual route avoids:', '["Any risk of side effects", "All absorption into the blood", "The need for the drug to dissolve", "First-pass liver metabolism"]'::jsonb, 3, 'Glyceryl trinitrate is given sublingually for rapid absorption into the systemic circulation.', 'NAP 413 · Applied Pharmacology I'),
(2, 25, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'The most dangerous drug error in theatre with high-alert drugs is commonly due to:', '["Look-alike and sound-alike ampoules", "Using colour-coded labels", "Checking drugs with a colleague", "Reading the label twice"]'::jsonb, 0, 'Examples: confusing potassium chloride with saline, or adrenaline with other ampoules. Separate storage and checking reduce risk.', 'NAP 413 · Applied Pharmacology I'),
(2, 26, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'The elderly are more sensitive to many anaesthetic drugs because of:', '["Reduced organ function, body water and protein binding", "Faster liver metabolism of most anaesthetic drugs", "Increased muscle mass and a larger blood volume", "Higher cardiac output and faster drug distribution"]'::jsonb, 0, 'Doses of induction agents, opioids and benzodiazepines are reduced in the elderly.', 'NAP 413 · Applied Pharmacology I'),
(2, 27, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Drugs cross the placenta easily if they are:', '["Highly protein-bound and positively charged", "Lipid-soluble, unionised and of low molecular weight", "Highly ionised and highly water-soluble in plasma", "Large molecules such as heparin and insulin"]'::jsonb, 1, 'Opioids and induction agents cross the placenta; heparin and neuromuscular blockers (ionised) do not significantly.', 'NAP 413 · Applied Pharmacology I'),
(2, 28, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'An ionised drug is:', '["Unaffected by pH", "Always more potent", "Less able to cross lipid membranes", "More able to cross lipid membranes"]'::jsonb, 2, 'Local anaesthetics work poorly in infected (acidic) tissue because more drug is ionised and cannot enter nerves.', 'NAP 413 · Applied Pharmacology I'),
(2, 29, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'The loading dose of a drug is given to:', '["Replace the maintenance dose", "Reduce side effects at the start", "Reach therapeutic levels quickly", "Test for allergy"]'::jsonb, 2, 'It is often used for drugs with long half-lives, such as amiodarone and phenytoin.', 'NAP 413 · Applied Pharmacology I'),
(2, 30, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A drug''s potency refers to:', '["The maximum effect the drug can produce", "How quickly the drug acts", "The dose needed to produce a given effect", "How long the drug lasts"]'::jsonb, 2, 'Fentanyl is about 100 times more potent than morphine, but both can produce similar maximum analgesia (efficacy).', 'NAP 413 · Applied Pharmacology I'),
(2, 31, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Before giving an antibiotic in theatre, the nurse anaesthetist must check:', '["Only the time of the last meal", "Allergy history and the prescription", "Only the patient''s weight", "The surgeon''s preference only"]'::jsonb, 1, 'Penicillin and cephalosporin allergy can cause anaphylaxis under anaesthesia.', 'NAP 413 · Applied Pharmacology I'),
(2, 32, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Drug storage in theatre requires that:', '["Kept after expiry so they are available for emergencies", "Kept together in a warm cupboard near the steriliser", "Stored at the right temperature and checked for expiry", "Left on the trolley even when they need refrigeration"]'::jsonb, 2, 'Suxamethonium and some others need refrigeration. Stock is rotated (first expiry, first out).', 'NAP 413 · Applied Pharmacology I'),
(2, 33, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Pharmacodynamics includes the study of:', '["Drug storage conditions in the pharmacy", "Drug–receptor interactions and effects", "Drug excretion by the kidneys in urine", "Drug absorption from the small intestine"]'::jsonb, 1, 'It covers mechanism of action, dose-response relationships, potency and efficacy.', 'NAP 413 · Applied Pharmacology I'),
(2, 34, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A patient with liver failure is likely to show prolonged effects from:', '["Inhalational nitrous oxide", "Drugs metabolised mainly by the liver", "IV normal saline", "Drugs excreted unchanged by the kidney"]'::jsonb, 1, 'Benzodiazepines, many opioids and some muscle relaxants accumulate in liver failure.', 'NAP 413 · Applied Pharmacology I'),
(2, 35, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'When an IV drug is extravasated into the tissues, the nurse should:', '["Remove the cannula at once and take no further action", "Continue injecting the drug more slowly into the vein", "Massage the swollen area firmly to disperse the drug", "Stop injecting, leave the cannula, follow the protocol"]'::jsonb, 3, 'Some drugs (e.g. thiopentone, calcium, vasopressors) cause tissue necrosis. Early action limits damage.', 'NAP 413 · Applied Pharmacology I'),
(2, 36, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'The pre-anaesthetic visit is done mainly to:', '["Prepare the surgical instruments for the case", "Collect payment for the anaesthetic before surgery", "Assess the patient, plan anaesthesia, reduce anxiety", "Mark the operation site with the surgical team"]'::jsonb, 2, 'It includes history, examination, investigations, airway assessment, ASA grading, consent for anaesthesia and premedication.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 37, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Which history is most important to elicit before anaesthesia?', '["Favourite foods, drinks and the time of the last meal", "Educational qualifications and the patient''s occupation", "Number of siblings and the size of the family home", "Previous anaesthetics, family reactions, allergies, drugs"]'::jsonb, 3, 'Family history of prolonged paralysis or high fever under anaesthesia suggests suxamethonium apnoea or malignant hyperthermia.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 38, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient with a thyromental distance of less than 6 cm is likely to have:', '["Difficult venous access", "A difficult laryngoscopy", "Low risk of aspiration", "An easy laryngoscopy"]'::jsonb, 1, 'Other predictors include limited mouth opening, high Mallampati class, reduced neck extension and receding mandible.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 39, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient with a full stomach needing emergency surgery should receive:', '["Inhalational induction with a face mask", "Deep sedation without airway protection", "Rapid sequence induction with cricoid pressure", "A laryngeal mask without intubation"]'::jsonb, 2, 'RSI includes pre-oxygenation, a predetermined induction dose, rapid-onset relaxant and early cuffed tube placement.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 40, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Premedication with an antacid such as sodium citrate before caesarean section is given to:', '["Speed up gastric emptying until the stomach is empty", "Raise gastric pH, reducing harm if aspiration occurs", "Sedate the mother and relieve her anxiety before surgery", "Prevent nausea and vomiting after the operation"]'::jsonb, 1, 'Aspiration of acidic gastric content causes Mendelson''s syndrome. H2 blockers and metoclopramide are also used.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 41, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Which patient is classified ASA III?', '["A healthy adult listed for an inguinal hernia repair", "A moribund patient after major trauma, for laparotomy", "A diabetic on insulin with angina limiting activity", "A smoker with no other disease, for a knee arthroscopy"]'::jsonb, 2, 'ASA III is severe systemic disease with functional limitation. ASA V is moribund, not expected to survive without surgery.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 42, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'The letter ''E'' after an ASA grade (e.g. ASA II E) means:', '["Elderly patient", "Emergency surgery", "Epidural anaesthesia", "Elective surgery"]'::jsonb, 1, 'Emergency cases carry a higher risk at any ASA grade.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 43, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Recommended minimum monitoring during general anaesthesia includes:', '["ECG, NIBP, SpO₂, capnography, and gas and agent analysis", "Pulse by palpation only, with the BP every 15 minutes", "Urine output only, measured hourly from a catheter", "Core temperature only, measured with a nasal probe"]'::jsonb, 0, 'Monitoring standards also require the continuous presence of a trained anaesthetist.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 44, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'The most useful single monitor for detecting oesophageal intubation is:', '["ECG", "Blood pressure", "Capnography", "Pulse oximetry"]'::jsonb, 2, 'SpO₂ falls only later. A sustained CO₂ waveform confirms tracheal placement.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 45, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Signs that a patient is ready for extubation include:', '["Persistent residual block with weak, jerky limb movements", "SpO₂ of 85% on 100% oxygen with slow, shallow breathing", "Deep anaesthesia, with no airway reflexes and no movement", "Regular breathing, reversed block, obeying commands, reflexes"]'::jsonb, 3, 'Extubation is done either awake (most cases) or deep in selected patients, with suction and oxygen ready.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 46, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Immediately after extubation, the nurse anaesthetist should:', '["Leave the patient to the porter", "Remove all monitors at once", "Sit the patient upright without monitoring", "Give oxygen and watch airway patency and breathing"]'::jsonb, 3, 'Laryngospasm, obstruction and hypoventilation are common immediately after extubation.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 47, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Recovery room equipment that must be at every bedspace includes:', '["Oxygen, suction, monitoring and airway equipment", "Only a blood pressure cuff and a stethoscope", "A drip stand and a giving set only", "A writing desk and the patient''s notes"]'::jsonb, 0, 'Each bay needs oxygen, suction, pulse oximetry, BP monitoring and access to resuscitation equipment and drugs.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 48, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'The recovery room chart should record:', '["Only the patient''s home address and next of kin", "Vital signs, consciousness, pain, fluids, drugs and events", "Only the surgeon''s operation notes and instructions", "Only the time of arrival and the time of discharge"]'::jsonb, 1, 'Accurate charts allow trends to be seen and support safe discharge decisions.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 49, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Oxygen therapy after general anaesthesia is given mainly because of:', '["Excess red blood cells after the IV fluids", "Diffusion hypoxia, hypoventilation and atelectasis", "Hyperventilation from pain after the operation", "High blood pressure from the endotracheal tube"]'::jsonb, 1, 'Diffusion hypoxia after nitrous oxide occurs as N₂O floods into alveoli and dilutes oxygen.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 50, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Diffusion hypoxia is most likely at the end of anaesthesia with:', '["Sevoflurane alone", "Nitrous oxide", "Propofol infusion", "Ketamine"]'::jsonb, 1, 'Giving 100% oxygen for a few minutes at the end of anaesthesia prevents it.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 51, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient in recovery has stridor after extubation. The first step is:', '["Lay the patient flat and observe for an hour", "Give an oral sedative to calm the patient", "Remove the oxygen mask to reduce distress", "Call for help, give 100% oxygen, jaw thrust"]'::jsonb, 3, 'Stridor suggests upper airway obstruction (laryngospasm, oedema, haematoma). CPAP, adrenaline nebuliser or reintubation may be needed.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 52, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A post-operative patient''s sedation score is ''difficult to rouse'' with a respiratory rate of 8. The nurse should:', '["Give a sedative to keep the patient comfortable", "Stop opioids, support breathing, prepare naloxone", "Give another opioid dose for the patient''s pain", "Leave the patient to sleep off the anaesthetic"]'::jsonb, 1, 'Increasing sedation is an early sign of opioid toxicity; naloxone reverses it.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 53, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Malignant hyperthermia, if suspected under anaesthesia, is managed first by:', '["Stop triggers, 100% oxygen, call for help, dantrolene", "Increase the volatile agent to deepen the anaesthesia", "Give more suxamethonium to overcome the rigidity", "Warm the patient with blankets and warmed fluids"]'::jsonb, 0, 'Cooling, treating hyperkalaemia and acidosis, and monitoring urine output follow.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 54, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Anaphylaxis under anaesthesia commonly presents with:', '["Hypertension and bradycardia only", "Polyuria and hypoglycaemia", "Hyperthermia and rigidity", "Hypotension, bronchospasm and rash"]'::jsonb, 3, 'Common triggers are neuromuscular blockers, antibiotics, latex and chlorhexidine. Treat with adrenaline, fluids and oxygen.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 55, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'When positioning an anaesthetised patient, the arm should not be abducted beyond 90° to avoid:', '["Ulnar fracture", "Brachial plexus injury", "Shoulder dislocation only", "Radial artery spasm"]'::jsonb, 1, 'Overstretching stretches the plexus. The ulnar nerve at the elbow is also protected with padding.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 56, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Eye care during general anaesthesia includes:', '["Leaving the eyes open for observation", "Closing and taping the eyelids", "Using no protection in short cases", "Applying pressure pads on the eyes"]'::jsonb, 1, 'Corneal abrasion is the most common eye injury; pressure on the eye can cause blindness, especially when prone.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 57, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'The difficult airway trolley should be:', '["Checked only after it has been used in a case", "Locked away in a distant store for safety", "Checked regularly and kept where all staff know", "Used only by the consultant anaesthetist"]'::jsonb, 2, 'It includes bougies, videolaryngoscope, supraglottic devices, front-of-neck access kit and different blades and tubes.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 58, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'In the post-anaesthesia care unit, a patient''s temperature of 35 °C should be treated with:', '["Active warming, e.g. forced-air warming", "Removing the blankets to stop sweating", "No action until the temperature is 34 °C", "Giving cold IV fluids to reduce shivering"]'::jsonb, 0, 'Hypothermia increases bleeding, infection, cardiac events and delays recovery.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 59, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Signs of hypovolaemia in the recovery room include:', '["Slow breathing, pinpoint pupils and drowsiness", "Bradycardia, hypertension and a full bounding pulse", "Warm flushed skin, polyuria and a normal pulse", "Tachycardia, hypotension, cool peripheries, oliguria"]'::jsonb, 3, 'Look for bleeding (wound, drains) and give fluids; inform the surgeon.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 60, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Intermittent positive pressure ventilation (IPPV) under anaesthesia is needed when:', '["The patient is paralysed or cannot breathe adequately", "The operation is very short and needs no relaxant", "The patient breathes well spontaneously on a mask", "Only local anaesthesia is used without sedation"]'::jsonb, 0, 'Paralysis abolishes spontaneous breathing, so ventilation by bag or ventilator is required.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 61, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Before the first case of the day, the nurse anaesthetist checks the oxygen failure alarm by:', '["Opening the nitrous oxide flowmeter only and watching the bobbin", "Turning off the monitor and listening for any alarm sounds", "Disconnecting the oxygen and confirming the alarm and cut-off", "Checking the cylinder colour only and the pipeline labels"]'::jsonb, 2, 'The oxygen failure warning device alerts staff and cuts off nitrous oxide to prevent hypoxic mixtures.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 62, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A hypoxic guard (anti-hypoxic device) on an anaesthetic machine prevents:', '["A mixture with less than about 25% oxygen", "Use of volatile agents with oxygen", "Use of medical air from the pipeline", "Any mixture with more than 50% oxygen"]'::jsonb, 0, 'It mechanically links oxygen and nitrous oxide flows so a hypoxic mixture cannot be set.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 63, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'The emergency oxygen flush on an anaesthetic machine delivers:', '["A mixture of oxygen and nitrous oxide", "Air at low flow", "High-flow pure oxygen bypassing the vaporiser", "Oxygen through the vaporiser"]'::jsonb, 2, 'It gives about 35–75 L/min of oxygen. Overuse with a closed system may cause barotrauma or awareness.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 64, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Records of drugs given during anaesthesia should include:', '["Drug, dose, route and time", "Only the drug name", "Only the total dose for the day", "Only the batch number"]'::jsonb, 0, 'Accurate timing helps calculate repeat doses and explains later events.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 65, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Before inducing anaesthesia, the nurse anaesthetist confirms the patient''s identity by:', '["Reading the name on the theatre list on the wall", "Checking the ID band against notes and asking the patient", "Checking the bed number written on the trolley", "Asking the porter who brought the patient to theatre"]'::jsonb, 1, 'Active identification is part of the WHO Sign In before induction.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 66, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Before shifting an anaesthetised patient to the recovery room, the nurse anaesthetist should ensure:', '["The patient remains deeply paralysed for the journey", "All IV lines and monitoring have been removed", "The patient is sitting fully upright on the trolley", "A secure airway, adequate breathing and oxygen for transfer"]'::jsonb, 3, 'Transfer is a high-risk period; portable oxygen and monitoring are used if needed.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 67, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Post-operative nausea and vomiting is reduced by:', '["Long fasting before surgery to empty the stomach", "Using nitrous oxide freely in high-risk patients", "Large doses of opioid to keep the patient asleep", "Antiemetics, hydration and opioid-sparing analgesia"]'::jsonb, 3, 'Multimodal prevention is used for high-risk patients.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 68, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'The best pain relief strategy after major surgery is usually:', '["Analgesia given only when the patient starts crying", "A single large dose of opioid at the end of surgery", "No analgesia at all, to avoid any drug side effects", "Multimodal analgesia with different drugs and techniques"]'::jsonb, 3, 'Paracetamol, NSAIDs, opioids and regional blocks together improve analgesia with fewer side effects.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 69, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient may be discharged from recovery to the ward when:', '["The patient is still deeply sedated", "Bleeding from the wound is increasing", "ABC are stable and pain is controlled", "The oxygen saturation is falling"]'::jsonb, 2, 'Scoring systems such as the Aldrete score support discharge decisions.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 70, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Hand-over from the nurse anaesthetist to the recovery nurse should include:', '["Patient, procedure, anaesthetic, drugs, fluids, concerns", "Only the surgeon''s name and the theatre number", "Only the time the operation started and ended", "Only the patient''s name and hospital number"]'::jsonb, 0, 'Structured handover (e.g. SBAR) reduces omissions.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 71, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'A carrier is a person who:', '["Harbours a pathogen without symptoms and can spread it", "Is immune and cannot spread infection", "Has recovered and cannot be infected again", "Has full symptoms of an infection"]'::jsonb, 0, 'Examples include MRSA nasal carriers and typhoid carriers; they can transmit infection to patients.', 'GSM 410 · Applied Microbiology'),
(2, 72, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The chain of infection consists of:', '["Bacteria, viruses, fungi and parasites as the four agents", "Cleaning, disinfection and sterilisation of the equipment", "Agent, reservoir, exit, transmission, entry, susceptible host", "Agent, host and environment, with no other links in the chain"]'::jsonb, 2, 'Breaking any link prevents infection. Hand hygiene breaks the transmission link.', 'GSM 410 · Applied Microbiology'),
(2, 73, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The cardinal signs of inflammation are:', '["Cough, purulent sputum and breathlessness", "Fever, weight loss and drenching night sweats", "Pallor, coldness, shrinkage and numbness", "Redness, heat, swelling, pain, loss of function"]'::jsonb, 3, 'Rubor, calor, tumor, dolor and functio laesa result from vasodilation and increased permeability.', 'GSM 410 · Applied Microbiology'),
(2, 74, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Gram-positive bacteria stain purple because they:', '["Have a thick peptidoglycan cell wall that retains crystal violet", "Produce spores that absorb the stain", "Have no cell wall at all", "Have an outer lipid membrane that takes up safranin"]'::jsonb, 0, 'Gram-negative bacteria have a thin wall and outer membrane, and stain pink with the counterstain.', 'GSM 410 · Applied Microbiology'),
(2, 75, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Staphylococcus aureus appears on Gram stain as:', '["Gram-negative diplococci", "Gram-positive cocci in clusters", "Gram-negative rods", "Gram-positive cocci in chains"]'::jsonb, 1, 'Streptococci form chains. Neisseria are Gram-negative diplococci.', 'GSM 410 · Applied Microbiology'),
(2, 76, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Pseudomonas aeruginosa is important in anaesthesia because it:', '["It contaminates moist equipment such as humidifiers", "It causes infection only in children under five", "It is always sensitive to every common antibiotic", "It lives only on dry metal surfaces and instruments"]'::jsonb, 0, 'It is a Gram-negative rod that thrives in water and can cause ventilator-associated pneumonia.', 'GSM 410 · Applied Microbiology'),
(2, 77, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Ventilator-associated pneumonia is reduced by:', '["Frequent open suctioning without gloves or eye protection", "Lying the patient flat on the back for most of the day", "Head-up position, oral care, sedation holds, closed suction", "Changing the ventilator circuit every hour of the day"]'::jsonb, 2, 'Bundles also include subglottic suction and early weaning.', 'GSM 410 · Applied Microbiology'),
(2, 78, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Hepatitis B virus is transmitted mainly through:', '["Airborne droplets", "Faecal-oral route", "Blood and body fluids", "Insect bites"]'::jsonb, 2, 'Health workers should be vaccinated. The risk from a needlestick from an HBeAg-positive source can be about 30% in non-immune staff.', 'GSM 410 · Applied Microbiology'),
(2, 79, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Specimens for blood culture should be collected:', '["From the IV cannula that is already in use", "After several doses of antibiotics have been given", "Without any skin preparation, to save time", "Before antibiotics, using aseptic technique"]'::jsonb, 3, 'Skin contamination gives false positives; at least two sets from separate sites are often taken.', 'GSM 410 · Applied Microbiology'),
(2, 80, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'A sputum specimen for microscopy is best collected:', '["After eating a meal", "From saliva at any time", "Early in the morning after a deep cough", "After mouthwash with antiseptic"]'::jsonb, 2, 'Early-morning specimens contain secretions collected overnight and give better yields, e.g. for AFB.', 'GSM 410 · Applied Microbiology'),
(2, 81, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Swab specimens should be sent to the laboratory:', '["After 2–3 days at room temperature in the ward", "Unlabelled, to protect the patient''s confidentiality", "In formalin, so that organisms do not overgrow", "Promptly, labelled, with a form, in transport medium"]'::jsonb, 3, 'Delays allow overgrowth or death of organisms, giving false results.', 'GSM 410 · Applied Microbiology'),
(2, 82, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Culture media are incubated in the laboratory usually at:', '["4 °C", "100 °C", "60 °C", "37 °C"]'::jsonb, 3, 'Body temperature suits most human pathogens. Plates are examined for colonies after 18–48 hours.', 'GSM 410 · Applied Microbiology'),
(2, 83, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Serological tests detect:', '["Antibodies or antigens in serum", "Drug levels in the blood", "Spores in the theatre environment", "Bacteria growing on agar plates"]'::jsonb, 0, 'Examples include Widal (typhoid), HBsAg and HIV antibody tests.', 'GSM 410 · Applied Microbiology'),
(2, 84, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The most effective method of sterilising heat-stable instruments is:', '["Ultraviolet light in a closed cabinet", "Boiling in water for 10 minutes", "Soaking in 70% alcohol overnight", "Steam under pressure (autoclave)"]'::jsonb, 3, 'Typical cycles are 134 °C for 3 minutes or 121 °C for 15 minutes. Boiling does not kill all spores.', 'GSM 410 · Applied Microbiology'),
(2, 85, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Glutaraldehyde 2% is used for:', '["High-level disinfection of endoscopes and similar items", "Sterilising surgical gloves for reuse in theatre", "Skin preparation of the patient before an incision", "Cleaning the theatre floor between surgical cases"]'::jsonb, 0, 'It is toxic and irritant; it needs ventilation and PPE. Prolonged contact can achieve sterilisation.', 'GSM 410 · Applied Microbiology'),
(2, 86, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Decontamination means:', '["Removing or inactivating organisms so items are safe to handle", "Washing hands with soap and water before patient contact", "Giving antibiotics to patients before contaminated surgery", "Killing every organism, including bacterial spores, on an item"]'::jsonb, 0, 'It includes cleaning, disinfection and sterilisation, chosen according to the item''s risk.', 'GSM 410 · Applied Microbiology'),
(2, 87, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Spaulding classification grades a laryngoscope blade as a:', '["Critical item", "Non-critical item", "Semi-critical item", "Disposable item only"]'::jsonb, 2, 'Semi-critical items touch mucous membranes and need high-level disinfection. Critical items enter sterile tissue and need sterilisation.', 'GSM 410 · Applied Microbiology'),
(2, 88, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The Central Sterile Services Department (CSSD) workflow should move in one direction from:', '["Dirty area to clean area to sterile storage", "Any direction depending on workload", "Sterile storage to dirty area", "Clean area to dirty area"]'::jsonb, 0, 'One-way flow prevents recontamination of processed items.', 'GSM 410 · Applied Microbiology'),
(2, 89, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Sterile packs should be stored:', '["On the floor in the theatre corridor", "Under the sink in the sluice room", "Near the windows in direct sunlight", "In a clean, dry area off the floor"]'::jsonb, 3, 'Damp or torn packs are considered unsterile. Event-related sterility depends on handling and storage.', 'GSM 410 · Applied Microbiology'),
(2, 90, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Infected waste such as blood-soaked swabs should be disposed of in:', '["The sink, flushed away with plenty of running water", "Open bins left in the corridor for collection", "Colour-coded clinical waste bags for incineration", "General household waste bags for the municipal bin"]'::jsonb, 2, 'Waste segregation protects staff and the public; sharps go in puncture-proof containers.', 'GSM 410 · Applied Microbiology'),
(2, 91, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The hospital infection control committee is responsible for:', '["Buying all the anaesthetic drugs and the theatre supplies", "Deciding the surgical lists and the order of the cases", "Policies, surveillance and training on infection prevention", "Recruiting and disciplining all the nurses in the hospital"]'::jsonb, 2, 'The infection control team includes a microbiologist and infection control nurses.', 'GSM 410 · Applied Microbiology'),
(2, 92, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Hand hygiene with alcohol rub is NOT adequate when:', '["Before a clean or aseptic procedure", "Hands are visibly soiled or after C. difficile", "Before touching a patient in the ward", "After touching the patient''s surroundings"]'::jsonb, 1, 'Soap and water are needed to remove dirt and spores; alcohol does not kill spores.', 'GSM 410 · Applied Microbiology'),
(2, 93, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'An endotracheal tube marked ''single use'' should be:', '["Reused for the same patient next week", "Discarded after one use", "Reprocessed and used again", "Washed and kept for emergencies"]'::jsonb, 1, 'Reprocessing single-use items may cause infection, damage and legal liability.', 'GSM 410 · Applied Microbiology'),
(2, 94, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Bacterial filters in the breathing circuit are used to:', '["Increase dead space on purpose", "Absorb carbon dioxide from expired gas", "Reduce cross-infection between patients", "Warm the inspired gases to 37 °C"]'::jsonb, 2, 'Heat and moisture exchanging filters (HMEF) also humidify inspired gas.', 'GSM 410 · Applied Microbiology'),
(2, 95, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Tuberculosis is spread mainly by:', '["Airborne droplet nuclei", "Mosquito bites", "Contact with intact skin", "Contaminated food only"]'::jsonb, 0, 'Staff caring for patients with open TB need respiratory protection, and equipment should be filtered.', 'GSM 410 · Applied Microbiology'),
(2, 96, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Lassa fever, endemic in parts of Nigeria, is transmitted mainly via:', '["Contact with rodent urine or faeces and infected fluids", "Drinking contaminated water only, never by contact", "Airborne spread over long distances between towns", "Bites from infected Anopheles mosquitoes at night"]'::jsonb, 0, 'It is a viral haemorrhagic fever. Strict barrier nursing is needed; ribavirin is used for treatment.', 'GSM 410 · Applied Microbiology'),
(2, 97, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Body response to infection that can progress to organ dysfunction is called:', '["Anaphylaxis", "Sepsis", "Autoimmunity", "Allergy"]'::jsonb, 1, 'Sepsis can lead to septic shock with hypotension needing vasopressors.', 'GSM 410 · Applied Microbiology'),
(2, 98, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Universal precautions require eye protection for the anaesthetist during:', '["Writing up the anaesthetic chart", "Taking the patient''s blood pressure", "Talking to the patient before induction", "Intubation, extubation and suctioning"]'::jsonb, 3, 'Splashes of secretions can transmit infection through the conjunctiva.', 'GSM 410 · Applied Microbiology'),
(2, 99, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'A disinfectant differs from an antiseptic in that a disinfectant is used:', '["On living skin and tissues", "Only on wounds", "Only inside the body", "On inanimate objects and surfaces"]'::jsonb, 3, 'Antiseptics (e.g. chlorhexidine, povidone-iodine) are used on skin; disinfectants on equipment and surfaces.', 'GSM 410 · Applied Microbiology'),
(2, 100, 'Anaesthesia Nursing Mock — Day 1 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The best indicator that a steam sterilisation cycle killed spores is:', '["A biological indicator", "The time on the clock", "The pack feeling warm", "Indicator tape colour change"]'::jsonb, 0, 'Biological indicators contain resistant spores; chemical indicators only show exposure to the process.', 'GSM 410 · Applied Microbiology'),
(3, 1, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Socialisation is the process by which a person:', '["Learns the norms, values and roles of society", "Develops natural immunity to common diseases", "Inherits physical traits from both parents", "Becomes cut off and isolated from other people"]'::jsonb, 0, 'Primary socialisation occurs in the family; secondary socialisation occurs in school, work and the profession.', 'GSB 410 · Applied Behavioural Science'),
(3, 2, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Health-seeking behaviour refers to:', '["Actions taken to identify and treat perceived illness", "The behaviour of health workers while they are at work", "Refusing all medical treatment offered by hospitals", "Habits that always cause disease, such as smoking"]'::jsonb, 0, 'It is shaped by culture, cost, access, beliefs and previous experience.', 'GSB 410 · Applied Behavioural Science'),
(3, 3, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'A patient refuses blood transfusion before surgery because of religious beliefs. This shows the influence of:', '["Personality on wound healing", "Religion on health service utilisation", "Social class on drug metabolism", "Genetics on blood group"]'::jsonb, 1, 'Nurses respect such beliefs, provide information and document the informed refusal.', 'GSB 410 · Applied Behavioural Science'),
(3, 4, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'The ''sick role'' described by Parsons includes the right to:', '["Be blamed for the illness", "Refuse to seek any medical help", "Be exempted from normal social duties", "Remain ill as long as one wishes"]'::jsonb, 2, 'The sick person is also obliged to want to get well and to seek competent help.', 'GSB 410 · Applied Behavioural Science'),
(3, 5, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Some patients prefer traditional healers before coming to hospital. In anaesthetic emergencies this may lead to:', '["Faster recovery after surgery and fewer infections", "Lower anaesthetic risk because of herbal preparation", "No effect at all on the outcome of the operation", "Late presentation with more complicated conditions"]'::jsonb, 3, 'Collaboration and health education encourage early referral to hospital.', 'GSB 410 · Applied Behavioural Science'),
(3, 6, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Preoperative anxiety is best reduced by:', '["Avoiding any discussion until after surgery", "Separating the patient from relatives early", "Telling the patient there are no risks at all", "Explanation, listening and honest reassurance"]'::jsonb, 3, 'Anxiety increases pain, anaesthetic requirements and post-operative complications.', 'GSB 410 · Applied Behavioural Science'),
(3, 7, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Fear of ''not waking up'' from anaesthesia is best addressed by:', '["Giving a sedative without any explanation", "Promising the patient there is no risk at all", "Honest explanation of monitoring and safety", "Dismissing the fear as foolish and childish"]'::jsonb, 2, 'Honest reassurance builds trust and respects autonomy.', 'GSB 410 · Applied Behavioural Science'),
(3, 8, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'A defence mechanism in which a patient attributes their own feelings to others is:', '["Sublimation", "Projection", "Rationalisation", "Denial"]'::jsonb, 1, 'Defence mechanisms protect against anxiety and are common in stressful illness.', 'GSB 410 · Applied Behavioural Science'),
(3, 9, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Behaviour modification is based on the principle that:', '["Behaviour can be changed by reinforcement", "Punishment is the only method of change", "Behaviour is not affected by environment", "Behaviour is fixed at birth"]'::jsonb, 0, 'Positive reinforcement (praise, rewards) increases desired behaviour, e.g. in children before anaesthesia.', 'GSB 410 · Applied Behavioural Science'),
(3, 10, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Counselling a patient facing amputation should aim to:', '["Help the patient express feelings and choose", "Make all the decisions on the patient''s behalf", "Avoid discussing the operation and its effects", "Convince the patient to refuse the surgery"]'::jsonb, 0, 'Counselling is non-judgemental and supports coping with loss and body image change.', 'GSB 410 · Applied Behavioural Science'),
(3, 11, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Kubler-Ross''s first stage of grief is commonly:', '["Denial", "Acceptance", "Depression", "Bargaining"]'::jsonb, 0, 'The stages are denial, anger, bargaining, depression and acceptance; they do not always occur in order.', 'GSB 410 · Applied Behavioural Science'),
(3, 12, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Nurse-family relationship in theatre is important because relatives:', '["Need information and support during the surgery", "Have no role at all in the patient''s recovery", "Decide which anaesthetic technique is used", "Should be kept away from all information"]'::jsonb, 0, 'Within confidentiality limits, updating relatives reduces their anxiety.', 'GSB 410 · Applied Behavioural Science'),
(3, 13, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Motivation that comes from within a person, such as pride in good work, is called:', '["Extrinsic motivation", "Negative motivation", "Intrinsic motivation", "Social motivation"]'::jsonb, 2, 'Extrinsic motivation comes from outside rewards such as pay or praise.', 'GSB 410 · Applied Behavioural Science'),
(3, 14, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Instinct is best described as:', '["A behaviour learned from parents", "An inborn, unlearned pattern of behaviour", "A skill learned through training", "A response to medication"]'::jsonb, 1, 'Examples include the sucking reflex in newborns.', 'GSB 410 · Applied Behavioural Science'),
(3, 15, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Communication that uses gestures, facial expression and touch is:', '["Non-verbal communication", "Verbal communication", "Written communication", "Formal communication"]'::jsonb, 0, 'Non-verbal cues are especially important with anxious, intubated or hearing-impaired patients.', 'GSB 410 · Applied Behavioural Science'),
(3, 16, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Crisis intervention aims to:', '["Prescribe sedatives only, without any support", "Help the person cope now and restore functioning", "Provide long-term psychotherapy over many years", "Avoid all contact with the person until they calm"]'::jsonb, 1, 'A crisis is short-term; prompt support prevents long-term problems.', 'GSB 410 · Applied Behavioural Science'),
(3, 17, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Interdisciplinary relationships in the anaesthetic team are improved by:', '["Working independently without talking to others", "Mutual respect, clear roles and open communication", "Competition between the professions in theatre", "Strict hierarchy, with no questions from juniors"]'::jsonb, 1, 'Good teamwork improves safety and reduces errors.', 'GSB 410 · Applied Behavioural Science'),
(3, 18, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Social classification such as income and education affects health because it influences:', '["Blood group and genotype of the person", "Access to care, nutrition and health behaviour", "The half-life of drugs in the body", "The potency of anaesthetic agents"]'::jsonb, 1, 'Lower socio-economic status is linked to later presentation and poorer outcomes.', 'GSB 410 · Applied Behavioural Science'),
(3, 19, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'A child who becomes bedwetting again after admission for surgery shows:', '["Projection", "Sublimation", "Displacement", "Regression"]'::jsonb, 3, 'Regression to an earlier stage is common in stressed children.', 'GSB 410 · Applied Behavioural Science'),
(3, 20, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Psychotherapy is:', '["Physical exercise therapy supervised by a physiotherapist", "Treating mental illness using drugs only, without any talking", "Surgical treatment of mental illness, such as leucotomy", "Treating emotional problems by talking in a therapeutic relationship"]'::jsonb, 3, 'Types include cognitive behavioural therapy and supportive counselling.', 'GSB 410 · Applied Behavioural Science'),
(3, 21, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'The first step in the research process is usually:', '["Analysing the results statistically", "Identifying the research problem", "Collecting data from the participants", "Writing the final research report"]'::jsonb, 1, 'A clear, researchable problem guides the literature review, objectives and design.', 'GSR 410 · Research Methodology & Statistics'),
(3, 22, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A literature review is done mainly to:', '["Find what is already known and identify gaps", "Analyse statistical results", "Copy previous studies exactly", "Collect primary data from patients"]'::jsonb, 0, 'It also helps build the theoretical framework and refine the research question.', 'GSR 410 · Research Methodology & Statistics'),
(3, 23, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A variable that the researcher manipulates to observe its effect is the:', '["Dependent variable", "Confounding variable", "Extraneous variable", "Independent variable"]'::jsonb, 3, 'The dependent variable is the outcome measured, e.g. post-operative pain score.', 'GSR 410 · Research Methodology & Statistics'),
(3, 24, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A study observing patients at one point in time to measure prevalence is a:', '["Cohort study", "Case-control study", "Cross-sectional study", "Randomised controlled trial"]'::jsonb, 2, 'Cross-sectional studies are quick and cheap but cannot establish cause and effect.', 'GSR 410 · Research Methodology & Statistics'),
(3, 25, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A study that follows a group of smokers and non-smokers forward to compare post-operative chest infections is a:', '["Prospective cohort study", "Cross-sectional study", "Case-control study", "Qualitative study"]'::jsonb, 0, 'Cohort studies start with exposure and follow participants to measure outcomes.', 'GSR 410 · Research Methodology & Statistics'),
(3, 26, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Comparing patients who developed post-dural puncture headache with those who did not, looking back at needle type, is a:', '["Cohort study", "Randomised controlled trial", "Case-control study", "Descriptive survey"]'::jsonb, 2, 'Case-control studies start with the outcome and look back at exposures.', 'GSR 410 · Research Methodology & Statistics'),
(3, 27, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Random sampling is preferred because it:', '["Reduces selection bias and aids generalisation", "Requires no list of the population at all", "Guarantees that results will be significant", "Is always the cheapest and fastest method"]'::jsonb, 0, 'Every member of the population has an equal chance of selection.', 'GSR 410 · Research Methodology & Statistics'),
(3, 28, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A pilot study is done to:', '["Publish some results quickly before the main study", "Avoid the need to obtain ethical approval", "Replace the main study when funds are limited", "Test whether methods and tools work before the main study"]'::jsonb, 3, 'It identifies problems with instruments, recruitment and procedures.', 'GSR 410 · Research Methodology & Statistics'),
(3, 29, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A hypothesis is:', '["The final conclusion reached at the end of a study", "A testable prediction of a relationship between variables", "A list of the research objectives for the study", "A summary of the literature that has been reviewed"]'::jsonb, 1, 'Example: ''Pre-warming reduces post-operative hypothermia in adults having laparotomy.''', 'GSR 410 · Research Methodology & Statistics'),
(3, 30, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'The range of a set of data is:', '["The average of all the values in the set", "The middle value when values are ordered", "The highest value minus the lowest value", "The value that occurs most frequently"]'::jsonb, 2, 'Range is a simple measure of dispersion; standard deviation is more informative.', 'GSR 410 · Research Methodology & Statistics'),
(3, 31, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Nominal data are:', '["Ranked categories such as pain mild/moderate/severe", "Continuous measurements such as weight", "Measurements with equal intervals and true zero", "Categories without order, such as blood group"]'::jsonb, 3, 'Ordinal data have order; interval and ratio data are numerical.', 'GSR 410 · Research Methodology & Statistics'),
(3, 32, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A pain score rated as none, mild, moderate or severe is:', '["Interval data", "Nominal data", "Ordinal data", "Ratio data"]'::jsonb, 2, 'Order exists but the intervals are not necessarily equal.', 'GSR 410 · Research Methodology & Statistics'),
(3, 33, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Standard deviation measures:', '["The middle value of the ordered data", "The value that occurs most often", "The total sum of all the values", "How widely values spread around the mean"]'::jsonb, 3, 'About 95% of normally distributed values lie within 2 standard deviations of the mean.', 'GSR 410 · Research Methodology & Statistics'),
(3, 34, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A study result with p = 0.20 means:', '["The difference is highly significant at the 5% level", "There is a 20% chance that the treatment works", "The difference is not significant at the 5% level", "The treatment has been proven to work definitely"]'::jsonb, 2, 'Using p < 0.05 as the threshold, p = 0.20 does not reject the null hypothesis.', 'GSR 410 · Research Methodology & Statistics'),
(3, 35, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Descriptive statistics are used to:', '["Test hypotheses about a population", "Predict future events with certainty", "Summarise and describe data", "Replace data collection"]'::jsonb, 2, 'Inferential statistics are used to draw conclusions about a population from a sample.', 'GSR 410 · Research Methodology & Statistics'),
(3, 36, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'The t-test compares:', '["Correlation between variables", "Proportions in categories", "Medians of three groups", "Means of two groups"]'::jsonb, 3, 'Chi-square compares categorical proportions; ANOVA compares means of three or more groups.', 'GSR 410 · Research Methodology & Statistics'),
(3, 37, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Correlation coefficient (r) of −0.8 indicates:', '["A strong negative relationship", "A weak positive relationship", "A perfect positive relationship", "No relationship"]'::jsonb, 0, 'r ranges from −1 to +1; values near ±1 show strong relationships. Correlation does not prove causation.', 'GSR 410 · Research Methodology & Statistics'),
(3, 38, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Informed consent for research participants must include:', '["Purpose, procedures, risks, benefits and right to withdraw", "A written promise of guaranteed benefit to the participant", "Only the researcher''s name and the institution''s address", "Permission from the hospital only, not the participant"]'::jsonb, 0, 'Ethical approval from a research ethics committee is also needed.', 'GSR 410 · Research Methodology & Statistics'),
(3, 39, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Anonymity in research means:', '["The researcher knows identities but keeps them secret", "The study has no participants", "Participants publish their names", "Participants cannot be identified even by the researcher"]'::jsonb, 3, 'Confidentiality means identities are known to the researcher but protected.', 'GSR 410 · Research Methodology & Statistics'),
(3, 40, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A questionnaire is valid if it:', '["Measures what it is supposed to measure", "Gives the same result every time", "Uses only closed questions", "Is short and easy to complete"]'::jsonb, 0, 'Reliability is consistency; validity is accuracy.', 'GSR 410 · Research Methodology & Statistics'),
(3, 41, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'The ''methodology'' chapter of a research project describes:', '["The list of references used in the project", "Previous studies on the topic and their gaps", "Design, setting, sample, instruments and analysis", "Findings of the study and what they mean"]'::jsonb, 2, 'It allows others to judge and repeat the study.', 'GSR 410 · Research Methodology & Statistics'),
(3, 42, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'In a research report, the ''discussion'' section:', '["Gives the title, abstract and keywords of the report", "Introduces the topic and states the research problem", "Lists all the raw data collected in the study", "Interprets findings and compares them with other work"]'::jsonb, 3, 'It also states limitations and implications for practice.', 'GSR 410 · Research Methodology & Statistics'),
(3, 43, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A research proposal is written:', '["Instead of doing a literature review", "After the results have been published", "Before the study, to plan it and seek approval", "Only for qualitative studies, not surveys"]'::jsonb, 2, 'It includes background, objectives, methods, ethics, timeline and budget.', 'GSR 410 · Research Methodology & Statistics'),
(3, 44, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Critiquing a research report means:', '["Rejecting it because of minor spelling errors", "Copying its conclusions into your own work", "Summarising its title and abstract only", "Judging its strengths, weaknesses and usefulness"]'::jsonb, 3, 'Critique considers design, sampling, validity, ethics and applicability.', 'GSR 410 · Research Methodology & Statistics'),
(3, 45, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Utilisation of research findings in practice means:', '["Publishing results in a journal only", "Keeping findings within the research team", "Applying valid evidence to improve patient care", "Repeating the study without change"]'::jsonb, 2, 'Evidence-based practice links research to clinical decisions.', 'GSR 410 · Research Methodology & Statistics'),
(3, 46, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'The doctrine of res ipsa loquitur means:', '["The thing speaks for itself", "Let the buyer beware", "The patient decides", "First, do no harm"]'::jsonb, 0, 'It applies when an injury would not normally occur without negligence, e.g. a swab retained in the abdomen.', 'GSE 410 · Ethico-Legal Issues'),
(3, 47, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'In a negligence case, the plaintiff is:', '["The lawyer for the defence", "The person who brings the claim", "The judge", "The person being sued"]'::jsonb, 1, 'The defendant is the person or institution against whom the claim is made.', 'GSE 410 · Ethico-Legal Issues'),
(3, 48, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Malpractice refers to:', '["Negligence by a qualified professional", "Charging patients very high fees", "Refusing to treat a paying patient", "Any mistake made by any person"]'::jsonb, 0, 'It involves a failure to meet the standard of care expected of a competent professional.', 'GSE 410 · Ethico-Legal Issues'),
(3, 49, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Liability means:', '["A hospital policy on theatre practice", "Legal responsibility for one''s actions", "A written contract of employment", "A licence to practise as a nurse"]'::jsonb, 1, 'Nurse anaesthetists are personally liable for their practice; employers may be vicariously liable.', 'GSE 410 · Ethico-Legal Issues'),
(3, 50, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Licensure for Nurse Anaesthetists in Nigeria is granted by:', '["The Nursing and Midwifery Council of Nigeria", "The hospital management board", "The State Ministry of Health only", "The Nigerian Medical Association"]'::jsonb, 0, 'Practising without a valid licence is illegal.', 'GSE 410 · Ethico-Legal Issues'),
(3, 51, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Battery in anaesthesia would occur if:', '["The patient consents freely after explanation", "The patient is informed of risks", "An emergency life-saving action is taken", "A procedure is done without the patient''s valid consent"]'::jsonb, 3, 'Assault is the threat; battery is unlawful touching. Valid consent is the defence.', 'GSE 410 · Ethico-Legal Issues'),
(3, 52, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Damages in law refers to:', '["Money awarded to compensate for harm", "Destruction of records", "Physical injury to equipment", "Punishment by imprisonment"]'::jsonb, 0, 'Damages compensate the plaintiff for loss caused by negligence.', 'GSE 410 · Ethico-Legal Issues'),
(3, 53, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'The Patient''s Bill of Rights includes the right to:', '["Free treatment in every hospital", "Information, consent, privacy and respectful care", "Choose the anaesthetic drugs personally", "Demand any treatment requested"]'::jsonb, 1, 'Rights must be balanced with the professional judgement of health workers.', 'GSE 410 · Ethico-Legal Issues'),
(3, 54, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Principle of autonomy means:', '["Respecting a competent patient''s right to decide", "Treating all patients exactly the same way", "Doing what is best whatever the patient wishes", "Keeping information secret from the patient"]'::jsonb, 0, 'It underlies informed consent and the right to refuse treatment.', 'GSE 410 · Ethico-Legal Issues'),
(3, 55, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Principle of justice in health care means:', '["Avoiding harm to the patient at all costs", "Telling patients the truth about their illness", "Fair distribution of resources and treatment", "Doing good for each individual patient"]'::jsonb, 2, 'Resources such as theatre time and ICU beds should be allocated fairly.', 'GSE 410 · Ethico-Legal Issues'),
(3, 56, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A Nurse Anaesthetist who notices a colleague under the influence of alcohol before a case should:', '["Report to the supervisor to protect patients", "Discuss it only with friends after the shift", "Allow the colleague to continue with the list", "Ignore it to avoid conflict with the colleague"]'::jsonb, 0, 'Patient safety takes priority; the duty to report unsafe practice is professional and ethical.', 'GSE 410 · Ethico-Legal Issues'),
(3, 57, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'When police request blood alcohol samples from an injured unconscious patient, the nurse should:', '["Give the samples to the police without any authority", "Follow policy and the law, protecting the patient''s rights", "Destroy the samples to protect the patient from charges", "Refuse every police request, whatever the law says"]'::jsonb, 1, 'Evidence handling must follow legal procedures and chain-of-custody rules.', 'GSE 410 · Ethico-Legal Issues'),
(3, 58, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Handling evidence properly, such as bullets removed during surgery, involves:', '["Handing them to the patient''s relatives", "Keeping them in the theatre as souvenirs", "Labelling, sealing and recording the chain of custody", "Throwing them away with the clinical waste"]'::jsonb, 2, 'Proper handling ensures evidence is admissible in court.', 'GSE 410 · Ethico-Legal Issues'),
(3, 59, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'The Good Samaritan principle protects a nurse who:', '["Acts carelessly beyond their competence at a scene", "Gives reasonable help in good faith outside work", "Charges fees for the help given at the roadside", "Refuses to help at the scene of an accident"]'::jsonb, 1, 'Help must be within competence and given without gross negligence.', 'GSE 410 · Ethico-Legal Issues'),
(3, 60, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A patient refuses an anaesthetic procedure against medical advice. The nurse should:', '["Force the procedure while the patient is restrained", "Sedate the patient secretly and do the procedure", "Explain risks, document refusal, inform the doctor", "Ignore the refusal and continue as planned"]'::jsonb, 2, 'Refusal by a competent adult must be respected and documented.', 'GSE 410 · Ethico-Legal Issues'),
(3, 61, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Telephone advice to patients by nurses should be:', '["Avoided in all circumstances by nurses", "Given by any staff member who answers", "Accurate, within competence and documented", "Given freely without any record kept"]'::jsonb, 2, 'Poor telephone advice can lead to liability.', 'GSE 410 · Ethico-Legal Issues'),
(3, 62, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Which case is usually notifiable/reportable to authorities?', '["Gunshot wounds and suspected criminal injuries", "Elective inguinal hernia repair in adults", "Simple fractures from playing football", "Routine appendicectomy for appendicitis"]'::jsonb, 0, 'Assault, poisoning, suspected abuse and certain infectious diseases are reportable.', 'GSE 410 · Ethico-Legal Issues'),
(3, 63, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Care of the deceased in theatre includes:', '["Releasing the body without documentation", "Respectful handling, identification and documentation", "Leaving the body unattended", "Removing tubes in coroner''s cases without instruction"]'::jsonb, 1, 'In coroner''s cases, lines and tubes may need to remain in place.', 'GSE 410 · Ethico-Legal Issues'),
(3, 64, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Confidentiality of anaesthetic records means they:', '["Can be shared with anyone who asks politely", "Can be posted on social media for teaching", "Are the property of the nurse who wrote them", "Are shared only with those who need them or by law"]'::jsonb, 3, 'Breaches can lead to disciplinary action.', 'GSE 410 · Ethico-Legal Issues'),
(3, 65, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'The Code of Professional Conduct for nurses in Nigeria is issued by:', '["Each hospital separately", "The Nursing and Midwifery Council of Nigeria", "The International Council of Nurses only", "The World Health Organization"]'::jsonb, 1, 'The ICN Code of Ethics also guides nurses internationally.', 'GSE 410 · Ethico-Legal Issues'),
(3, 66, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A legal pitfall in emergency anaesthesia is:', '["Checking all equipment before it is used", "Calling for senior help early in a crisis", "Poor documentation of decisions and events", "Obtaining consent whenever it is possible"]'::jsonb, 2, 'In emergencies, careful documentation of time, findings and actions protects patient and staff.', 'GSE 410 · Ethico-Legal Issues'),
(3, 67, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'For a mentally disturbed patient needing urgent surgery who cannot consent, the team should:', '["Act in their best interests within the law, and document", "Refuse to treat the patient because consent is impossible", "Obtain consent from any hospital worker, such as a cleaner", "Wait indefinitely until the patient''s mental state recovers"]'::jsonb, 0, 'Capacity assessment and legal procedures guide treatment.', 'GSE 410 · Ethico-Legal Issues'),
(3, 68, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A patient who attempted suicide by poisoning needs care that includes:', '["Discharge as soon as the patient is fully awake", "Treatment, protection from self-harm and reporting", "Punishment for the attempt once the patient recovers", "No psychiatric referral if the poison was minor"]'::jsonb, 1, 'Psychiatric review and safe environment are essential.', 'GSE 410 · Ethico-Legal Issues'),
(3, 69, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Report writing after an incident should be:', '["Delayed for several weeks", "Factual, clear, dated and signed", "Written by someone who was not present", "Emotional and blaming others"]'::jsonb, 1, 'Accurate reports support learning and legal processes.', 'GSE 410 · Ethico-Legal Issues'),
(3, 70, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Ethical dilemma means:', '["An error in drug administration that harmed a patient", "A clinical emergency that needs immediate treatment", "Conflicting moral principles with no clear right answer", "A legal case that has already been decided by a court"]'::jsonb, 2, 'Ethical frameworks help nurses reason through dilemmas.', 'GSE 410 · Ethico-Legal Issues'),
(3, 71, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'A computer that processes continuous physical quantities such as temperature is a:', '["Hybrid computer", "Analogue computer", "Microcomputer", "Digital computer"]'::jsonb, 1, 'Digital computers process discrete data; hybrid computers combine both (e.g. some ICU monitors).', 'GSC 410 · ICT & Nursing Informatics'),
(3, 72, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'The Arithmetic Logic Unit (ALU) of a computer:', '["Displays the output on the computer screen", "Performs calculations and logical comparisons", "Controls the printer and other output devices", "Stores data permanently when power is off"]'::jsonb, 1, 'The ALU and the control unit form the CPU.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 73, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'Read Only Memory (ROM) differs from RAM in that ROM:', '["Is lost when the computer is switched off", "Keeps its contents when power is off", "Can be changed easily by the user", "Is used for temporary working data"]'::jsonb, 1, 'RAM is volatile working memory; ROM holds start-up instructions.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 74, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'Which is an input device?', '["Optical mark reader", "Plotter", "Visual display unit", "Printer"]'::jsonb, 0, 'Input devices include keyboard, mouse, scanner and document readers.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 75, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'System software includes:', '["The operating system", "A word processor", "A hospital billing program", "A spreadsheet"]'::jsonb, 0, 'Application software is designed for specific user tasks.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 76, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'A file arranged so records can be reached directly by key without reading others is:', '["Physical file", "Sequential file", "Batch file", "Random (direct) access file"]'::jsonb, 3, 'Sequential files must be read in order; index sequential files use an index for faster access.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 77, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'Batch processing means:', '["Processing each transaction immediately", "Processing only one record per day", "Collecting data and processing it together later", "Processing data on several computers at once"]'::jsonb, 2, 'Real-time (online) processing handles each transaction as it occurs.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 78, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'A Hospital Information System (HIS) is used to:', '["Replace all clinical staff in the hospital wards", "Perform surgery automatically without a surgeon", "Store X-ray images only, with no other records", "Manage clinical, administrative and financial data"]'::jsonb, 3, 'Electronic records improve access, legibility and continuity of care.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 79, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'Nursing informatics combines:', '["Accounting and statistics only", "Medicine and pharmacy sciences only", "Nursing, computer and information science", "Nursing and engineering science only"]'::jsonb, 2, 'It supports documentation, decision-making and research.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 80, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'Electronic access to client data should be protected by:', '["Leaving computers logged in", "Sharing one password among staff", "Passwords, access levels and audit trails", "Writing passwords on the monitor"]'::jsonb, 2, 'Confidentiality laws apply to electronic records as well as paper.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 81, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'Data standardisation in nursing informatics means:', '["Recording data in each nurse''s personal style", "Using only paper records in all hospital units", "Deleting old data to save computer storage", "Common terms and codes so data can be shared"]'::jsonb, 3, 'Standardised nursing languages such as NANDA, NIC and NOC support this.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 82, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'A computer generation based on integrated circuits is the:', '["Fifth generation", "Third generation", "First generation", "Second generation"]'::jsonb, 1, 'First used vacuum tubes; second, transistors; third, integrated circuits; fourth, microprocessors.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 83, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'A secondary (auxiliary) storage device is:', '["A hard disk", "The keyboard", "The CPU", "The monitor"]'::jsonb, 0, 'Secondary storage holds data permanently; examples include hard disks and flash drives.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 84, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'An advantage of electronic data processing over manual processing is:', '["It never needs electricity to work", "It can never be hacked or lost", "Speed, accuracy and easy retrieval", "It requires no training for users"]'::jsonb, 2, 'Backups and security are still needed.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 85, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'A computer-based patient record should be backed up:', '["Never, because computers do not fail", "Only once a year", "On a personal phone", "Regularly, to a secure separate location"]'::jsonb, 3, 'Backups protect against hardware failure, theft and malware.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 86, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'Use of English & Communication', 'Choose the correctly spelt word:', '["Hemorrage", "Haemorrghe", "Haemorrhage", "Haemorhage"]'::jsonb, 2, 'British spelling ''haemorrhage'' is standard in Nigerian nursing.', 'Use of English & Communication'),
(3, 87, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'Use of English & Communication', 'Choose the correct sentence:', '["The anaesthetist, together with the nurses, are in theatre.", "The anaesthetist, together with the nurses, be in theatre.", "The anaesthetist together with the nurses were in theatre.", "The anaesthetist, together with the nurses, is in theatre."]'::jsonb, 3, 'The subject is ''the anaesthetist'' (singular); phrases beginning ''together with'' do not change it.', 'Use of English & Communication'),
(3, 88, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'Use of English & Communication', 'The prefix ''brady-'' means:', '["Absent", "Difficult", "Fast", "Slow"]'::jsonb, 3, 'Bradycardia is a slow heart rate; tachycardia is fast.', 'Use of English & Communication'),
(3, 89, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'Use of English & Communication', 'Choose the word opposite in meaning to ''conscious'':', '["Alert", "Unconscious", "Awake", "Oriented"]'::jsonb, 1, 'Antonyms are words with opposite meanings.', 'Use of English & Communication'),
(3, 90, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'Use of English & Communication', 'Which is the best way to communicate a critical result to a doctor?', '["A long story that gives no key facts at all", "A structured message such as SBAR, with read-back", "A short text message sent without confirmation", "A vague message left with the porter on duty"]'::jsonb, 1, 'SBAR: Situation, Background, Assessment, Recommendation.', 'Use of English & Communication'),
(3, 91, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'Use of English & Communication', 'The plural of ''diagnosis'' is:', '["Diagnosi", "Diagnosises", "Diagnosis", "Diagnoses"]'::jsonb, 3, 'Greek-origin words ending in -is form plurals with -es: analysis/analyses.', 'Use of English & Communication'),
(3, 92, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'Use of English & Communication', 'Choose the correct preposition: ''The patient complained ___ chest pain.''', '["for", "at", "with", "of"]'::jsonb, 3, '''Complain of'' is used for symptoms; ''complain about'' for grievances.', 'Use of English & Communication'),
(3, 93, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'Use of English & Communication', 'A good report should be:', '["Full of slang", "Clear, concise, accurate and objective", "Long, emotional and vague", "Written only from memory weeks later"]'::jsonb, 1, 'Clear writing prevents misunderstanding and supports legal accuracy.', 'Use of English & Communication'),
(3, 94, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'Entrepreneurship', 'An entrepreneur is a person who:', '["Avoids all risks and never invests any money", "Works only for a monthly salary from an employer", "Works only in government service until retirement", "Identifies opportunities and takes risks in business"]'::jsonb, 3, 'Nurse anaesthetists may start training, consultancy or equipment services.', 'Entrepreneurship'),
(3, 95, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'Entrepreneurship', 'Working capital is:', '["Money needed to run daily operations", "The cost of land and buildings", "Long-term loans only", "Profit shared with owners"]'::jsonb, 0, 'Running out of working capital is a common reason small businesses fail.', 'Entrepreneurship'),
(3, 96, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'Entrepreneurship', 'A feasibility study is done to:', '["Register the company with the authorities", "Pay staff salaries at the end of each month", "Assess whether an idea is practical and profitable", "Advertise the business to possible customers"]'::jsonb, 2, 'It considers market, technical, financial and legal aspects.', 'Entrepreneurship'),
(3, 97, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'Entrepreneurship', 'Profit is calculated as:', '["Fixed costs only", "Total revenue minus total costs", "Total costs minus revenue", "Revenue plus costs"]'::jsonb, 1, 'Positive profit means revenue exceeds costs.', 'Entrepreneurship'),
(3, 98, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'Entrepreneurship', 'Marketing a new health service involves:', '["Charging the highest price that is possible", "Keeping the new service secret from competitors", "Ignoring all feedback from customers and patients", "Identifying customer needs and promoting the service"]'::jsonb, 3, 'The 4 Ps: product, price, place and promotion.', 'Entrepreneurship'),
(3, 99, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'Entrepreneurship', 'A limited liability company means:', '["The business is not allowed to make a profit", "The business can have only one single owner", "Owners are not liable beyond their investment", "The owner pays all business debts personally"]'::jsonb, 2, 'It is registered with the Corporate Affairs Commission in Nigeria.', 'Entrepreneurship'),
(3, 100, 'Anaesthesia Nursing Mock — Day 1 Night (Nov 2026)', 'Entrepreneurship', 'Risk-taking in entrepreneurship should be:', '["Avoided completely in every case", "Left entirely to chance and luck", "Random and without any plan", "Calculated and based on information"]'::jsonb, 3, 'Good planning reduces the chance of business failure.', 'Entrepreneurship'),
(4, 1, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'In Nigeria, an oxygen cylinder is identified by:', '["A black body with a white shoulder", "A blue body with a blue shoulder", "A grey body with a black shoulder", "A french-blue body with a white shoulder"]'::jsonb, 0, 'International colours: oxygen white shoulder, nitrous oxide blue, medical air black-and-white shoulder, CO₂ grey.', 'NAP 423 · General Anaesthesia I'),
(4, 2, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A full size E oxygen cylinder has a pressure of about:', '["1000 kPa (10 bar, about 145 psi)", "13 700 kPa (137 bar, about 2000 psi)", "4400 kPa (44 bar, about 640 psi)", "400 kPa (4 bar, about 60 psi)"]'::jsonb, 1, 'Oxygen is stored as a compressed gas. Nitrous oxide cylinders read about 44 bar while liquid remains.', 'NAP 423 · General Anaesthesia I'),
(4, 3, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Hospital pipeline gases are delivered to the anaesthetic machine at about:', '["400 kPa (4 bar)", "137 bar", "40 kPa", "44 bar"]'::jsonb, 0, 'Pipelines connect via non-interchangeable Schrader probes and colour-coded hoses.', 'NAP 423 · General Anaesthesia I'),
(4, 4, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The pressure regulator (reducing valve) on an anaesthetic machine:', '["Reduces cylinder pressure to a steady working pressure", "Adds volatile agent vapour to the gas flow", "Measures the oxygen concentration delivered", "Converts liquid oxygen into gaseous oxygen"]'::jsonb, 0, 'It protects downstream components and allows stable flowmeter function as cylinder pressure falls.', 'NAP 423 · General Anaesthesia I'),
(4, 5, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The high-pressure system of an anaesthetic machine includes:', '["The breathing circuit and the reservoir bag", "Flowmeters, vaporisers and the back bar", "The common gas outlet and the APL valve", "Cylinders, yokes and gauges up to the regulator"]'::jsonb, 3, 'Intermediate pressure is pipeline pressure; low pressure is after the flowmeters.', 'NAP 423 · General Anaesthesia I'),
(4, 6, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'In a flowmeter bank, oxygen should be placed:', '["In the middle of the flowmeter bank", "First, furthest from the gas outlet", "Separately, after the vaporisers", "Last, nearest the common gas outlet"]'::jsonb, 3, 'If a flowmeter tube cracks, placing oxygen last reduces the risk of delivering a hypoxic mixture.', 'NAP 423 · General Anaesthesia I'),
(4, 7, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Vaporisers on the back bar should be:', '["Placed within the patient''s breathing circuit", "Agent-specific, correctly filled and interlocked", "All switched on together to deepen anaesthesia", "Filled with any volatile agent that is available"]'::jsonb, 1, 'Interlocks prevent more than one vaporiser being turned on. Keyed fillers prevent wrong filling.', 'NAP 423 · General Anaesthesia I'),
(4, 8, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The Epstein Macintosh Oxford (EMO) vaporiser is used in a:', '["Draw-over system", "Closed circle system", "Pressurised plenum system", "Mapleson D system with high flows"]'::jsonb, 0, 'Draw-over vaporisers have low resistance; the patient''s breathing (or a self-inflating bag) draws air through them. Useful where compressed gases are scarce.', 'NAP 423 · General Anaesthesia I'),
(4, 9, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A draw-over anaesthetic system is especially useful when:', '["Patients are always ventilated by machine", "High-flow oxygen supply is plentiful", "Compressed gases and electricity are unreliable", "Only intravenous anaesthesia is used"]'::jsonb, 2, 'It uses room air as the carrier gas, with oxygen added if available.', 'NAP 423 · General Anaesthesia I'),
(4, 10, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The Mapleson A (Magill) circuit is most efficient for:', '["Controlled ventilation", "Paediatric controlled ventilation", "Spontaneous breathing", "Circle system use"]'::jsonb, 2, 'Fresh gas flow equal to minute ventilation prevents rebreathing during spontaneous breathing. It is inefficient for IPPV.', 'NAP 423 · General Anaesthesia I'),
(4, 11, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Ayre''s T-piece (Mapleson E/F with Jackson-Rees modification) is commonly used for:', '["Long-term ICU ventilation", "Adults with COPD", "Children under about 20 kg", "Draw-over anaesthesia only"]'::jsonb, 2, 'It has low resistance and dead space. The open-ended bag allows assessment of breathing and gentle IPPV.', 'NAP 423 · General Anaesthesia I'),
(4, 12, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The Bain circuit is a coaxial version of the:', '["Mapleson A circuit", "Mapleson D circuit", "Circle system", "Mapleson C circuit"]'::jsonb, 1, 'Fresh gas flows through the inner tube. A disconnected or kinked inner tube causes rebreathing.', 'NAP 423 · General Anaesthesia I'),
(4, 13, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The main advantage of a circle system with soda lime is:', '["No resistance at all to the patient''s breathing", "Low fresh gas flows, less waste, warmer moist gas", "No need for gas or agent monitoring", "No need for oxygen in the fresh gas"]'::jsonb, 1, 'Exhaled gas is rebreathed after CO₂ absorption. Inspired concentrations must be monitored at low flows.', 'NAP 423 · General Anaesthesia I'),
(4, 14, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Exhausted soda lime in a circle system leads to:', '["Rebreathing with a rising inspired CO₂", "A lower end-tidal CO₂ on the capnograph", "Excess humidity and very cold inspired gas", "Hypoxia only, without any change in CO₂"]'::jsonb, 0, 'Indicator colour change and inspired CO₂ on capnography show exhaustion.', 'NAP 423 · General Anaesthesia I'),
(4, 15, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Soda lime consists mainly of:', '["Magnesium sulphate with silica as a hardener", "Mostly calcium hydroxide, with some sodium hydroxide", "Sodium chloride crystals mixed with distilled water", "Calcium carbonate granules on their own"]'::jsonb, 1, 'The reaction with CO₂ produces heat, water and calcium carbonate.', 'NAP 423 · General Anaesthesia I'),
(4, 16, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The adjustable pressure-limiting (APL) valve:', '["Absorbs carbon dioxide from the expired gas", "Lets excess gas out and limits circuit pressure", "Delivers the volatile agent into the circuit", "Measures the oxygen concentration in the circuit"]'::jsonb, 1, 'It must be partially closed to give manual IPPV and opened for spontaneous breathing.', 'NAP 423 · General Anaesthesia I'),
(4, 17, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A reservoir bag in a breathing circuit:', '["Filters bacteria and viruses from the inspired gas", "Stores gas, allows hand ventilation, shows breathing", "Measures the airway pressure during each breath", "Absorbs carbon dioxide from the breathing circuit"]'::jsonb, 1, 'Adult bags are usually 2 L. They distend to limit pressure at around 40–60 cmH₂O.', 'NAP 423 · General Anaesthesia I'),
(4, 18, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A size 4 or 5 laryngeal mask airway is usually chosen for:', '["Infants under 10 kg", "Neonates", "Children of 10–20 kg", "Adults"]'::jsonb, 3, 'LMA size depends on weight; size 1 is for neonates.', 'NAP 423 · General Anaesthesia I'),
(4, 19, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The usual endotracheal tube size (internal diameter) for an adult woman is:', '["7.0–7.5 mm", "4.0–4.5 mm", "5.5–6.0 mm", "9.5–10 mm"]'::jsonb, 0, 'Adult men usually take 8.0–8.5 mm. For children over 1 year: age/4 + 4 (uncuffed).', 'NAP 423 · General Anaesthesia I'),
(4, 20, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The formula for uncuffed ETT size (ID, mm) in a child over one year is:', '["Age/2 + 12", "Age/4 + 8", "Age/4 + 4", "Age + 4"]'::jsonb, 2, 'For cuffed tubes, use age/4 + 3.5. Length (oral) is about age/2 + 12 cm.', 'NAP 423 · General Anaesthesia I'),
(4, 21, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A Macintosh laryngoscope blade is:', '["Curved, with its tip placed in the vallecula", "Used only for nasal intubation", "Designed for neonates only", "Straight, lifting the epiglottis directly"]'::jsonb, 0, 'Straight (Miller) blades lift the epiglottis directly and are often used in infants.', 'NAP 423 · General Anaesthesia I'),
(4, 22, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The cuff of an endotracheal tube should be inflated to a pressure of about:', '["5–10 cmH₂O", "80–100 cmH₂O", "20–30 cmH₂O", "50–60 cmH₂O"]'::jsonb, 2, 'Higher pressures reduce tracheal mucosal blood flow, causing ischaemia; lower pressures risk aspiration.', 'NAP 423 · General Anaesthesia I'),
(4, 23, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A Guedel (oropharyngeal) airway is sized by measuring from:', '["The chin to the sternal notch", "The nose to the ear lobe", "The lips to the chin", "The incisors to the angle of the jaw"]'::jsonb, 3, 'A nasopharyngeal airway is sized from the nostril to the tragus of the ear.', 'NAP 423 · General Anaesthesia I'),
(4, 24, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A nasopharyngeal airway should be avoided in a patient with:', '["Clenched teeth after a seizure", "Suspected basal skull fracture", "An intact gag reflex on waking", "Obesity with a short, thick neck"]'::jsonb, 1, 'It may pass through a fracture into the cranial cavity. It is also avoided in coagulopathy.', 'NAP 423 · General Anaesthesia I'),
(4, 25, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Guedel''s classification describes stages of anaesthesia with:', '["Spinal anaesthesia", "Ketamine dissociation", "Ether anaesthesia", "Propofol infusion"]'::jsonb, 2, 'Stage 1 analgesia, stage 2 excitement, stage 3 surgical anaesthesia (planes 1–4), stage 4 overdose.', 'NAP 423 · General Anaesthesia I'),
(4, 26, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'In Guedel''s stage 2 (excitement), the patient may show:', '["Full consciousness with analgesia but no amnesia", "Complete apnoea with widely dilated, fixed pupils", "Calm, regular breathing with no airway reflexes", "Irregular breathing, struggling, vomiting, laryngospasm"]'::jsonb, 3, 'Stimulation should be avoided during this stage. Modern IV induction passes through it quickly.', 'NAP 423 · General Anaesthesia I'),
(4, 27, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Stage 4 of Guedel''s classification indicates:', '["Light surgical anaesthesia", "Medullary paralysis from overdose", "Analgesia without loss of consciousness", "Emergence from anaesthesia"]'::jsonb, 1, 'It causes respiratory arrest and cardiovascular collapse; the agent must be stopped and resuscitation started.', 'NAP 423 · General Anaesthesia I'),
(4, 28, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Balanced anaesthesia refers to:', '["Giving equal doses of every drug that is available", "Using a single volatile agent at a deep level", "Combining drugs for hypnosis, analgesia and relaxation", "Using only local anaesthetic for every operation"]'::jsonb, 2, 'Lower doses of each agent reduce side effects; the ''triad'' is narcosis, analgesia and relaxation.', 'NAP 423 · General Anaesthesia I'),
(4, 29, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'PEEP (positive end expiratory pressure) during IPPV mainly helps to:', '["Reduce the FiO₂ needed to 21% in every case", "Keep alveoli open and improve oxygenation", "Reduce intrathoracic pressure during expiration", "Increase venous return to the right heart"]'::jsonb, 1, 'Excess PEEP can reduce venous return and blood pressure.', 'NAP 423 · General Anaesthesia I'),
(4, 30, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'CPAP (continuous positive airway pressure) is applied to a patient who is:', '["Ventilated by a bag only", "Fully paralysed", "Apnoeic after induction", "Breathing spontaneously"]'::jsonb, 3, 'CPAP helps treat laryngospasm and improves oxygenation in atelectasis.', 'NAP 423 · General Anaesthesia I'),
(4, 31, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Muscle relaxants are given during general anaesthesia to:', '["Facilitate intubation and surgical access", "Produce unconsciousness at induction", "Provide analgesia during surgery", "Reduce nausea after the operation"]'::jsonb, 0, 'They have no anaesthetic or analgesic effect, so adequate anaesthesia must be maintained to prevent awareness.', 'NAP 423 · General Anaesthesia I'),
(4, 32, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A peripheral nerve stimulator ''train-of-four'' measures:', '["Degree of neuromuscular blockade", "Depth of anaesthesia (hypnosis)", "Arterial oxygen saturation", "Mean arterial blood pressure"]'::jsonb, 0, 'A TOF ratio above 0.9 indicates adequate recovery for extubation.', 'NAP 423 · General Anaesthesia I'),
(4, 33, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Before use, a laryngoscope should be checked for:', '["The batch number on the packaging", "The weight of the handle and blade", "The colour of the handle only", "A bright, steady light and a secure blade fit"]'::jsonb, 3, 'Spare blades, handles and batteries must be available.', 'NAP 423 · General Anaesthesia I'),
(4, 34, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Anaesthetic machines should be maintained by:', '["Regular technician servicing and daily user checks", "Users opening the machine and changing internal parts", "Cleaning by pouring water inside the machine body", "Repairs only after the machine has failed in a case"]'::jsonb, 0, 'Records of servicing must be kept.', 'NAP 423 · General Anaesthesia I'),
(4, 35, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Breathing circuits that are reused should be:', '["Cleaned and decontaminated between patients or filtered", "Washed in the scrub sink", "Stored wet", "Used for all patients in a day without cleaning"]'::jsonb, 0, 'Bacterial filters reduce contamination; policy guides change frequency.', 'NAP 423 · General Anaesthesia I'),
(4, 36, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A leak test of the breathing system is done by:', '["Occluding the patient end, closing the APL and pressurising", "Listening to the patient''s chest after intubation", "Measuring the pressure in the oxygen cylinder", "Turning off all the gases and watching the bag"]'::jsonb, 0, 'The pressure should be maintained, indicating no leak.', 'NAP 423 · General Anaesthesia I'),
(4, 37, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Scavenging systems in theatre remove:', '["Carbon dioxide from the patient", "Oxygen from the cylinders", "Waste anaesthetic gases", "Blood from the field"]'::jsonb, 2, 'Active scavenging uses suction; it reduces staff exposure.', 'NAP 423 · General Anaesthesia I'),
(4, 38, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Intermittent flow machines differ from continuous flow machines in that gas flows only:', '["When the patient inspires", "At expiration", "When the bag is squeezed", "Continuously at a set rate"]'::jsonb, 0, 'Demand-valve machines (e.g. for Entonox) deliver gas on inspiration.', 'NAP 423 · General Anaesthesia I'),
(4, 39, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The common gas outlet of the anaesthetic machine:', '["Removes waste gases from the theatre", "Delivers fresh gas to the breathing system", "Measures expired carbon dioxide levels", "Connects the machine to the oxygen pipeline"]'::jsonb, 1, 'It is a standard 22 mm male/15 mm female taper connection.', 'NAP 423 · General Anaesthesia I'),
(4, 40, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A self-inflating bag (e.g. Ambu) differs from an anaesthetic reservoir bag because it:', '["Needs a high gas flow before it will inflate", "Re-inflates itself and works without gas flow", "Cannot deliver any added oxygen to the patient", "Cannot be used for cardiopulmonary resuscitation"]'::jsonb, 1, 'It can be used with room air; an oxygen reservoir increases FiO₂.', 'NAP 423 · General Anaesthesia I'),
(4, 41, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Thiopentone is unsuitable for a patient with:', '["Epilepsy", "Acute intermittent porphyria", "Simple fracture", "Raised intracranial pressure"]'::jsonb, 1, 'Barbiturates can precipitate a porphyric crisis. Thiopentone is otherwise useful for neuro-anaesthesia and status epilepticus.', 'NAP 421 · Applied Pharmacology II'),
(4, 42, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Intra-arterial injection of thiopentone causes:', '["Immediate sleep with no other local effects", "Only mild redness at the injection site", "Severe pain, blanching and possible gangrene", "Hypertension and tachycardia without pain"]'::jsonb, 2, 'Crystals form in the artery. Leave the cannula in place, give saline, heparin and analgesia, and consider vasodilators.', 'NAP 421 · Applied Pharmacology II'),
(4, 43, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'The usual adult induction dose of propofol is:', '["0.1–0.2 mg/kg", "10 mg/kg", "5–7 mg/kg", "1.5–2.5 mg/kg"]'::jsonb, 3, 'Reduce in the elderly and shocked. Thiopentone is 3–5 mg/kg; ketamine IV 1–2 mg/kg.', 'NAP 421 · Applied Pharmacology II'),
(4, 44, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Propofol infusion syndrome is associated with:', '["A single induction dose given to a healthy adult", "Allergy to eggs, soya or peanuts in every case", "Long high-dose infusions, causing acidosis and heart failure", "Its use for short day-case operations under one hour"]'::jsonb, 2, 'It is more common in children and critically ill patients; features include rhabdomyolysis and arrhythmias.', 'NAP 421 · Applied Pharmacology II'),
(4, 45, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Etomidate is useful in haemodynamically unstable patients because it:', '["Has no side effects", "Provides excellent analgesia", "Causes minimal cardiovascular depression", "Increases blood pressure markedly"]'::jsonb, 2, 'It suppresses adrenal steroid synthesis and may cause myoclonus and PONV.', 'NAP 421 · Applied Pharmacology II'),
(4, 46, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Ketamine is relatively contraindicated in a patient with:', '["Severe hypertension or pre-eclampsia", "Burns needing dressing changes", "Hypovolaemic shock", "Asthma"]'::jsonb, 0, 'Ketamine raises blood pressure and heart rate; it is a bronchodilator and useful in shock and burns.', 'NAP 421 · Applied Pharmacology II'),
(4, 47, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Ketamine produces:', '["Dissociative anaesthesia with analgesia", "A spinal block below the waist", "Sedation without any analgesia", "Pure muscle relaxation without sleep"]'::jsonb, 0, 'Patients may have open eyes and nystagmus; airway reflexes are partly maintained.', 'NAP 421 · Applied Pharmacology II'),
(4, 48, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Neuroleptanalgesia combines:', '["Suxamethonium with atropine for rapid sequence induction", "Ketamine with propofol given in the same syringe", "A neuroleptic (droperidol) with a potent opioid (fentanyl)", "Lidocaine with adrenaline for local infiltration"]'::jsonb, 2, 'It gives calm detachment and analgesia; adding nitrous oxide gives neuroleptanaesthesia.', 'NAP 421 · Applied Pharmacology II'),
(4, 49, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Sevoflurane is popular for inhalational induction because it:', '["Is very pungent and irritating to the airway", "Has the slowest onset of the volatile agents", "Is non-irritant, pleasant-smelling and fast", "Requires a special heated vaporiser to work"]'::jsonb, 2, 'Isoflurane and desflurane are irritant and can cause coughing and laryngospasm.', 'NAP 421 · Applied Pharmacology II'),
(4, 50, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Desflurane requires a special heated, pressurised vaporiser because it:', '["Is flammable when it is mixed with air", "Has a boiling point near room temperature", "Decomposes when exposed to sunlight", "Is very insoluble in fat and in blood"]'::jsonb, 1, 'Its boiling point is about 23 °C.', 'NAP 421 · Applied Pharmacology II'),
(4, 51, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Halothane is associated with:', '["Nephrotoxicity from fluoride ions only", "Very rapid offset", "Bronchoconstriction", "Hepatitis and arrhythmias with adrenaline"]'::jsonb, 3, 'It sensitises the myocardium to catecholamines. Repeated exposure increases hepatitis risk.', 'NAP 421 · Applied Pharmacology II'),
(4, 52, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Nitrous oxide should be avoided in a patient with:', '["A simple, reducible inguinal hernia", "Day-case dental surgery in a child", "Mild, well-controlled hypertension", "Pneumothorax or bowel obstruction"]'::jsonb, 3, 'N₂O diffuses into air-filled spaces faster than nitrogen leaves, expanding them.', 'NAP 421 · Applied Pharmacology II'),
(4, 53, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Long exposure to nitrous oxide can cause:', '["Kidney stones from increased calcium excretion", "Hypercalcaemia from increased bone breakdown", "Megaloblastic anaemia from vitamin B12 inactivation", "Acute liver failure from toxic metabolites"]'::jsonb, 2, 'It oxidises cobalt in vitamin B12, affecting methionine synthase.', 'NAP 421 · Applied Pharmacology II'),
(4, 54, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'The blood:gas partition coefficient of a volatile agent determines:', '["The potency of the volatile agent", "The cost of the agent per hour", "The flammability of the vapour", "Speed of induction and recovery"]'::jsonb, 3, 'Low solubility (e.g. desflurane, sevoflurane) gives fast onset and offset. MAC indicates potency.', 'NAP 421 · Applied Pharmacology II'),
(4, 55, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Atracurium is particularly useful in renal and hepatic failure because:', '["It is excreted unchanged by the kidney only", "It causes no histamine release at any dose", "Hofmann degradation, independent of liver and kidney", "It is fully reversed by sugammadex"]'::jsonb, 2, 'Cisatracurium is similar with less histamine release.', 'NAP 421 · Applied Pharmacology II'),
(4, 56, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Rocuronium at 1–1.2 mg/kg is useful for rapid sequence induction because:', '["It lasts only 5 minutes after a single dose", "It causes fasciculations before paralysis", "It never needs reversal at the end of surgery", "It gives good intubating conditions in about 60 s"]'::jsonb, 3, 'Sugammadex can rapidly reverse it if needed.', 'NAP 421 · Applied Pharmacology II'),
(4, 57, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Suxamethonium may cause dangerous hyperkalaemia in:', '["Healthy young adults for elective surgery", "Burns, crush injury and denervation after 24–48 h", "Children having tonsillectomy", "Patients with simple closed fractures"]'::jsonb, 1, 'Upregulated acetylcholine receptors release more potassium.', 'NAP 421 · Applied Pharmacology II'),
(4, 58, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Side effects of suxamethonium include:', '["Prolonged paralysis for hours in all patients", "Bradycardia, myalgia, hyperkalaemia and raised IOP", "Hypoglycaemia, diarrhoea and abdominal cramps", "Hypotension from histamine release only"]'::jsonb, 1, 'Repeat doses increase bradycardia risk, especially in children.', 'NAP 421 · Applied Pharmacology II'),
(4, 59, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Neostigmine given without an anticholinergic can cause:', '["Tachycardia, dry mouth and urinary retention", "Bradycardia, salivation and bronchospasm", "Profound muscle paralysis and apnoea", "Hypertension, fever and muscle rigidity"]'::jsonb, 1, 'Glycopyrrolate or atropine is given to block muscarinic effects.', 'NAP 421 · Applied Pharmacology II'),
(4, 60, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Glycopyrrolate differs from atropine in that it:', '["Does not cross the blood-brain barrier", "Has no effect on secretions", "Causes confusion in elderly patients", "Has a shorter action"]'::jsonb, 0, 'It is a quaternary amine and causes less tachycardia and no central effects.', 'NAP 421 · Applied Pharmacology II'),
(4, 61, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Fentanyl is about how many times as potent as morphine?', '["10 times", "1000 times", "2 times", "100 times"]'::jsonb, 3, 'Typical IV doses are 1–2 micrograms/kg. Chest wall rigidity can occur with rapid large doses.', 'NAP 421 · Applied Pharmacology II'),
(4, 62, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Pethidine should be used with caution because:', '["It increases blood pressure markedly", "Its metabolite norpethidine can cause seizures", "It cannot be reversed by naloxone", "It has no analgesic effect"]'::jsonb, 1, 'Accumulation occurs with renal failure; it interacts dangerously with MAO inhibitors.', 'NAP 421 · Applied Pharmacology II'),
(4, 63, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Remifentanil is unique because it:', '["It is excreted unchanged by the kidney into the urine", "It causes no respiratory depression at any dose", "It is broken down by esterases, giving ultra-short action", "It lasts several hours after a single bolus dose"]'::jsonb, 2, 'Its effect ends minutes after stopping the infusion, so other analgesia must be planned.', 'NAP 421 · Applied Pharmacology II'),
(4, 64, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Lidocaine''s maximum safe dose without adrenaline is about:', '["15 mg/kg", "1 mg/kg", "3 mg/kg", "7 mg/kg"]'::jsonb, 2, 'With adrenaline it is about 7 mg/kg. Bupivacaine''s maximum is about 2 mg/kg.', 'NAP 421 · Applied Pharmacology II'),
(4, 65, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Bupivacaine is more cardiotoxic than lidocaine. Its toxicity is treated with:', '["IV flumazenil in small doses", "IV naloxone boluses", "IV neostigmine with glycopyrrolate", "IV 20% lipid emulsion"]'::jsonb, 3, 'Bupivacaine binds strongly to cardiac sodium channels; lipid emulsion acts as a ''sink''.', 'NAP 421 · Applied Pharmacology II'),
(4, 66, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Local anaesthetics work by:', '["Activating opioid receptors in the cord", "Increasing GABA activity in the brain", "Blocking sodium channels in nerves", "Blocking acetylcholine receptors"]'::jsonb, 2, 'Small, myelinated fibres (pain, temperature, autonomic) are blocked before large motor fibres.', 'NAP 421 · Applied Pharmacology II'),
(4, 67, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Hyperbaric bupivacaine (heavy) for spinal anaesthesia contains:', '["Sterile water, to make it lighter than CSF", "Dextrose, making it denser than CSF", "Sodium bicarbonate, to speed up the onset", "Adrenaline, to make the block last longer"]'::jsonb, 1, 'Patient position controls spread of hyperbaric solutions.', 'NAP 421 · Applied Pharmacology II'),
(4, 68, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Ester local anaesthetics such as procaine are more likely than amides to cause:', '["Blocks that last for several days", "Methaemoglobinaemia in every patient", "Allergy, via the PABA metabolite", "Liver toxicity from slow metabolism"]'::jsonb, 2, 'Amides include lidocaine, bupivacaine and ropivacaine; allergy to them is rare.', 'NAP 421 · Applied Pharmacology II'),
(4, 69, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Prilocaine in high doses can cause:', '["Malignant hyperthermia", "Methaemoglobinaemia", "Hypoglycaemia", "Hyperkalaemia"]'::jsonb, 1, 'It is treated with methylene blue.', 'NAP 421 · Applied Pharmacology II'),
(4, 70, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Midazolam is reversed by:', '["Flumazenil", "Neostigmine", "Naloxone", "Atropine"]'::jsonb, 0, 'Flumazenil''s effect is shorter than midazolam''s, so re-sedation can occur.', 'NAP 421 · Applied Pharmacology II'),
(4, 71, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Diazepam given IV may cause:', '["Hyperkalaemia and cardiac arrhythmias", "Bronchospasm and wheeze in all patients", "Severe hypertension and tachycardia", "Pain on injection and thrombophlebitis"]'::jsonb, 3, 'Lipid emulsion formulations reduce pain. Its long half-life causes prolonged sedation.', 'NAP 421 · Applied Pharmacology II'),
(4, 72, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Anticholinergic premedication was traditionally used to:', '["Produce muscle relaxation for intubation", "Lower the heart rate before induction", "Dry secretions and prevent vagal bradycardia", "Increase saliva to protect the airway"]'::jsonb, 2, 'It is still used in paediatric and some airway procedures.', 'NAP 421 · Applied Pharmacology II'),
(4, 73, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Ephedrine raises blood pressure mainly by:', '["Acting only on dopamine receptors in the kidney", "Inhibiting cholinesterase at the nerve endings", "Noradrenaline release plus direct alpha/beta effects", "Blocking beta-receptors in the heart and vessels"]'::jsonb, 2, 'It increases heart rate and contractility; phenylephrine is a pure alpha-agonist causing reflex bradycardia.', 'NAP 421 · Applied Pharmacology II'),
(4, 74, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Dantrolene acts by:', '["Increasing acetylcholine release at the NMJ", "Blocking beta-adrenergic receptors in the heart", "Blocking sodium channels in peripheral nerves", "Reducing calcium release in skeletal muscle"]'::jsonb, 3, 'It is the specific treatment for malignant hyperthermia.', 'NAP 421 · Applied Pharmacology II'),
(4, 75, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Ondansetron is a:', '["Dopamine receptor agonist", "H2 receptor antagonist", "5-HT3 receptor antagonist", "Muscarinic receptor agonist"]'::jsonb, 2, 'It is used to prevent and treat PONV. Dexamethasone and cyclizine are other options.', 'NAP 421 · Applied Pharmacology II'),
(4, 76, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The brain region that contains the respiratory and cardiovascular centres is the:', '["Thalamus", "Frontal lobe", "Medulla oblongata", "Cerebellum"]'::jsonb, 2, 'Depression of the medulla by drugs or raised ICP causes respiratory and cardiovascular failure.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 77, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The blood-brain barrier allows easy passage of:', '["Most antibiotics given by the IV route", "Lipid-soluble substances such as anaesthetic agents", "Large proteins such as albumin and globulins", "Highly ionised drugs such as muscle relaxants"]'::jsonb, 1, 'Neuromuscular blockers are ionised and do not cross it significantly.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 78, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Normal cerebral perfusion pressure (CPP) is calculated as:', '["Systolic pressure minus diastolic pressure", "Intracranial pressure minus venous pressure", "Mean arterial pressure minus intracranial pressure", "Mean arterial pressure plus ICP"]'::jsonb, 2, 'CPP is normally about 70–80 mmHg; hypotension or raised ICP reduce it.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 79, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Cerebral blood flow increases sharply when:', '["PaCO₂ falls", "Temperature falls", "PaO₂ is normal", "PaCO₂ rises"]'::jsonb, 3, 'Hypercapnia dilates cerebral vessels, raising ICP. Hyperventilation lowers CBF but may cause ischaemia.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 80, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Cerebral autoregulation maintains constant blood flow between mean arterial pressures of about:', '["50–150 mmHg", "10–30 mmHg", "150–250 mmHg", "0–50 mmHg"]'::jsonb, 0, 'It is impaired by head injury, high volatile agent concentrations and chronic hypertension (curve shifts right).', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 81, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The spinal cord in adults ends at about:', '["L4–L5", "T12", "S2", "L1–L2"]'::jsonb, 3, 'Spinal needles are inserted below L2 to avoid cord injury.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 82, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The dural sac in adults ends at about:', '["L3", "Coccyx", "L1", "S2"]'::jsonb, 3, 'Below S2, the caudal space is accessed for caudal blocks, especially in children.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 83, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The line joining the tops of the iliac crests (Tuffier''s line) crosses the:', '["The T12 spinous process", "The L4 spinous process or L4–L5 space", "The S1 spinous process", "The L1–L2 interspace"]'::jsonb, 1, 'It is used as a landmark for spinal and epidural injection.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 84, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'A sensory level at the umbilicus corresponds to the dermatome:', '["L1", "C7", "T10", "T4"]'::jsonb, 2, 'T4 is the nipple line, T6 the xiphoid, T10 the umbilicus, L1 the inguinal ligament.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 85, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'For caesarean section under spinal, the block must reach at least:', '["T4 (nipple level)", "S1", "T10 (umbilicus)", "L1 (groin)"]'::jsonb, 0, 'Peritoneal handling requires a high block; this increases the risk of hypotension.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 86, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The sympathetic nervous system outflow arises from the spinal cord at:', '["S2–S4", "L3–S5", "C1–C8", "T1–L2"]'::jsonb, 3, 'Spinal anaesthesia blocks sympathetic fibres, causing vasodilation; a block above T4 also blocks cardiac accelerators.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 87, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Parasympathetic outflow is craniosacral, arising from cranial nerves and:', '["C5–C8", "L1–L3", "T1–T12", "S2–S4"]'::jsonb, 3, 'The vagus nerve (X) carries most parasympathetic fibres to the chest and abdomen.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 88, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The adrenal medulla secretes catecholamines in response to:', '["Low blood glucose only", "Sympathetic stimulation", "Parasympathetic stimulation", "Insulin release"]'::jsonb, 1, 'Surgery and pain activate the sympathetic system and catecholamine release.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 89, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'A phaeochromocytoma under anaesthesia may cause:', '["Severe hypertensive crises", "Profound hypoglycaemia", "Bradycardia and hypotension only", "Hypothermia"]'::jsonb, 0, 'Pre-operative alpha-blockade (then beta-blockade) is essential.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 90, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Insulin is secreted by the:', '["Alpha cells of the pancreas", "Anterior pituitary", "Adrenal cortex", "Beta cells of the pancreatic islets"]'::jsonb, 3, 'Surgical stress increases counter-regulatory hormones, causing hyperglycaemia.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 91, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Thyroid hormone excess (thyrotoxicosis) under anaesthesia may cause:', '["Hypotension with a slow, weak pulse", "Bradycardia, hypothermia and slow recovery", "Hypoglycaemia, drowsiness and coma", "Tachycardia, arrhythmias and hyperthermia"]'::jsonb, 3, 'Patients should be made euthyroid before elective surgery.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 92, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Hypothyroid patients are at risk under anaesthesia of:', '["Hyperthermia and a high metabolic rate", "Tachyarrhythmias and high blood pressure", "Rapid metabolism of all anaesthetic drugs", "Drug sensitivity, hypothermia and slow recovery"]'::jsonb, 3, 'Metabolism is slowed, so doses are reduced.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 93, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The vomiting centre is located in the:', '["Frontal cortex, near the motor area", "Medulla, with input from the CTZ", "Cerebellum, near the balance centre", "Spinal cord, at the cervical level"]'::jsonb, 1, 'The CTZ lies outside the blood-brain barrier and detects drugs such as opioids.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 94, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Regurgitation differs from vomiting in that regurgitation is:', '["Always preceded by nausea", "Passive, without active muscle effort", "Only seen in conscious patients", "Active, with forceful contraction"]'::jsonb, 1, 'Silent regurgitation can occur in unconscious patients, so it is dangerous.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 95, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The lower oesophageal sphincter tone is reduced by:', '["Metoclopramide given before induction", "Suxamethonium given at induction", "Neostigmine at the end of surgery", "Pregnancy, opioids and atropine"]'::jsonb, 3, 'Reduced tone increases the risk of regurgitation and aspiration.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 96, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Aspiration pneumonitis (Mendelson''s syndrome) risk is highest with gastric content of:', '["pH below 2.5 and volume above 25 mL", "pH above 7 and small volume", "Clear water only", "Small solid particles only"]'::jsonb, 0, 'Acid damages the lungs; prevention includes fasting, antacids and rapid sequence induction.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 97, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Peripheral nerves are made of:', '["Bundles of axons in connective tissue sheaths", "Bone and cartilage covered by membrane", "Only muscle fibres joined end to end", "Blood vessels with a muscular wall"]'::jsonb, 0, 'Local anaesthetics diffuse through these layers to block conduction.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 98, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The brachial plexus is formed from nerve roots:', '["C5–T1", "L1–L4", "C1–C4", "T2–T6"]'::jsonb, 0, 'It is blocked for arm surgery (interscalene, supraclavicular, axillary approaches).', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 99, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The epidural space contains:', '["Fat, veins and nerve roots", "Air only, at negative pressure", "Cerebrospinal fluid and the cord", "The spinal cord and its arteries"]'::jsonb, 0, 'Epidural veins can be punctured, giving blood in the catheter.', 'NAP 430 · Applied Anatomy & Physiology II'),
(4, 100, 'Anaesthesia Nursing Mock — Day 2 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The ligament pierced last before entering the epidural space in the midline approach is the:', '["Ligamentum flavum", "Supraspinous ligament", "Posterior longitudinal ligament", "Interspinous ligament"]'::jsonb, 0, 'Loss of resistance indicates the needle has passed the ligamentum flavum.', 'NAP 430 · Applied Anatomy & Physiology II'),
(5, 1, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A person with blood group O is called a universal donor (for red cells) because:', '["Their red cells carry neither A nor B antigens", "Their plasma has no antibodies", "Their red cells carry both A and B antigens", "They can receive blood from anyone"]'::jsonb, 0, 'Group O red cells can be given in emergencies before cross-match (O negative for women of child-bearing age).', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 2, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A person with blood group AB plasma contains:', '["Both anti-A and anti-B antibodies", "Only anti-A antibodies", "Only anti-B antibodies", "No anti-A or anti-B antibodies"]'::jsonb, 3, 'AB individuals are universal recipients of red cells and universal plasma donors.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 3, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Before transfusion, the bedside check must confirm:', '["Only the patient''s bed number and the name on the trolley", "Only the volume of the unit and the time it was collected", "Identity, group, unit number and expiry against the prescription", "Only the colour of the blood in the bag and the label colour"]'::jsonb, 2, 'Most serious transfusion reactions are due to identification errors.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 4, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'An acute haemolytic transfusion reaction under anaesthesia may present as:', '["A rash only, with stable pulse and blood pressure", "Hypotension, haemoglobinuria, oozing and tachycardia", "Bradycardia and hypertension, with clear urine", "Hypoglycaemia and drowsiness without fever"]'::jsonb, 1, 'Symptoms such as loin pain are masked by anaesthesia. Stop the transfusion and treat shock.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 5, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Rhesus incompatibility in pregnancy occurs when:', '["An Rh-negative mother carries an Rh-positive fetus", "Both parents are Rh-negative", "An Rh-positive mother carries an Rh-negative fetus", "The mother is group AB"]'::jsonb, 0, 'Maternal antibodies can cross the placenta in later pregnancies and cause haemolytic disease of the newborn.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 6, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Packed red cells are preferred to whole blood when:', '["The patient has too much haemoglobin already", "Large volumes of clotting factors are needed", "Platelets are the only blood component needed", "Oxygen-carrying capacity is needed without overload"]'::jsonb, 3, 'One unit of packed cells raises Hb by about 1 g/dL in an adult.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 7, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Fresh frozen plasma is given mainly to:', '["Treat hypoglycaemia", "Raise platelet count", "Replace clotting factors", "Raise haemoglobin"]'::jsonb, 2, 'It is thawed at 37 °C and should be ABO-compatible.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 8, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Platelets are stored at:', '["37 °C in an incubator", "−30 °C in a freezer", "2–6 °C in a refrigerator", "20–24 °C with gentle agitation"]'::jsonb, 3, 'Room temperature storage increases the risk of bacterial contamination; shelf life is about 5 days.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 9, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Red cells are stored at:', '["2–6 °C", "37 °C", "−30 °C", "20–24 °C"]'::jsonb, 0, 'Blood should be transfused within 4 hours of leaving controlled storage.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 10, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Complications of massive blood transfusion include:', '["Hypoglycaemia alone, with no other changes", "Polycythaemia and a raised platelet count", "Hypercalcaemia and hypernatraemia with oedema", "Hypothermia, low calcium, high potassium, coagulopathy"]'::jsonb, 3, 'Warming blood, calcium replacement and balanced component therapy (e.g. 1:1:1) reduce complications.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 11, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Citrate toxicity during rapid transfusion causes:', '["Hypoglycaemia", "Hypernatraemia", "Hypocalcaemia", "Hypercalcaemia"]'::jsonb, 2, 'Citrate binds calcium; signs include hypotension and prolonged QT. Calcium is given IV.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 12, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Sickle cell disease (HbSS) patients undergoing anaesthesia should avoid:', '["Active warming throughout the operation", "Oxygen therapy during and after surgery", "IV fluids from the start of fasting", "Hypoxia, dehydration, cold and acidosis"]'::jsonb, 3, 'These factors promote sickling and vaso-occlusive crisis.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 13, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'The genotype that indicates sickle cell trait is:', '["AA", "SC", "AS", "SS"]'::jsonb, 2, 'Trait carriers rarely have problems but should avoid severe hypoxia.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 14, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Gelatin and starch solutions are examples of:', '["Blood products", "Albumin", "Crystalloids", "Synthetic colloids"]'::jsonb, 3, 'Colloids stay longer in the circulation but may cause allergy or coagulopathy.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 15, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Normal serum potassium is:', '["3.5–5.0 mmol/L", "135–145 mmol/L", "1.5–2.5 mmol/L", "5.5–7.0 mmol/L"]'::jsonb, 0, 'Both high and low potassium can cause dangerous arrhythmias under anaesthesia.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 16, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Normal serum sodium is:', '["95–105 mmol/L", "150–160 mmol/L", "3.5–5.0 mmol/L", "135–145 mmol/L"]'::jsonb, 3, 'Hyponatraemia can cause confusion and seizures; rapid correction risks osmotic demyelination.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 17, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'ECG changes of hyperkalaemia include:', '["Prominent U waves with flattened T waves", "Tall peaked T waves, wide QRS, loss of P waves", "ST elevation in all leads with chest pain", "A short PR interval with delta waves only"]'::jsonb, 1, 'U waves and flattened T waves suggest hypokalaemia.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 18, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Total body water in an adult male is about:', '["40% of body weight", "60% of body weight", "80% of body weight", "20% of body weight"]'::jsonb, 1, 'Two-thirds is intracellular and one-third extracellular. Neonates have a higher proportion.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 19, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Daily maintenance fluid for an adult is about:', '["100 mL/kg/day", "25–30 mL/kg/day", "5 mL/kg/day", "200 mL/kg/day"]'::jsonb, 1, 'Daily needs are about 1 mmol/kg each of sodium and potassium, and 50–100 g glucose.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 20, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Hartmann''s solution (Ringer''s lactate) contains:', '["Only sodium and chloride in water", "Sodium, potassium, calcium, chloride, lactate", "Albumin and globulins from plasma", "Glucose and water, with no salts"]'::jsonb, 1, 'It is a balanced crystalloid. Lactate is converted to bicarbonate by the liver.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 21, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Fluid overload during surgery is suggested by:', '["Tachycardia and hypotension only", "Low JVP with a dry tongue and mucosa", "Polyuria with thirst and dry skin", "Raised JVP, crackles, falling SpO₂, oedema"]'::jsonb, 3, 'Risk is higher in heart and renal failure, the elderly and with large irrigation volumes.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 22, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Body pH is maintained mainly by:', '["The skin and sweat glands", "The liver only", "Buffers, lungs and kidneys", "Red cells only"]'::jsonb, 2, 'Bicarbonate buffer is the major extracellular buffer.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 23, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A patient with lactic acidosis from shock will usually have:', '["Low pH, low bicarbonate, low PaCO₂", "High pH and high bicarbonate", "Low pH with a high PaCO₂ only", "Normal pH with a high bicarbonate"]'::jsonb, 0, 'Treatment is restoring perfusion and oxygen delivery, not bicarbonate alone.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 24, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A pre-operative haemoglobin of 7 g/dL in an elective patient should lead to:', '["Proceeding with no further action", "Investigation and correction before surgery if possible", "Giving oral iron on the morning of surgery only", "Cancelling surgery permanently"]'::jsonb, 1, 'Anaemia reduces oxygen delivery; causes should be found and treated.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 25, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Haemophilia A is a deficiency of clotting factor:', '["XII", "VIII", "VII", "IX"]'::jsonb, 1, 'Haemophilia B is factor IX deficiency. Factor replacement is needed before surgery.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 26, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'The INR is used to monitor:', '["Haemoglobin level", "Platelet function", "Heparin therapy", "Warfarin therapy"]'::jsonb, 3, 'APTT monitors unfractionated heparin; anti-Xa can monitor LMWH.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 27, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A platelet count below which major surgery is usually unsafe without transfusion is about:', '["10 × 10⁹/L", "150 × 10⁹/L", "50 × 10⁹/L", "400 × 10⁹/L"]'::jsonb, 2, 'For neuraxial blocks, many guidelines require at least 75–80 × 10⁹/L.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 28, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Albumin solution is a:', '["Starch-based synthetic colloid", "Packed red cell product", "Natural colloid from human plasma", "Synthetic balanced crystalloid"]'::jsonb, 2, 'It is used in hypoalbuminaemia, burns and some resuscitations.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 29, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Blood warmers are used during rapid transfusion mainly to prevent:', '["Allergic reactions", "Haemolysis from cold blood clumping only", "Hypothermia and cardiac arrhythmias", "Viral transmission"]'::jsonb, 2, 'Cold blood can cause hypothermia and ventricular arrhythmias.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 30, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Hazards of blood transfusion include:', '["Increased immunity to all diseases", "Reactions, infection and fluid overload", "Lower risk of any clotting problem", "A permanent cure for the anaemia"]'::jsonb, 1, 'TRALI, TACO, haemolysis and infections such as hepatitis and HIV are possible.', 'NAP 422 · Chemical Pathology & Haematology'),
(5, 31, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'In adult cardiac arrest, chest compressions should be delivered at:', '["100–120 per minute, 5–6 cm deep", "60–80 per minute, 2–3 cm deep", "140–160 per minute, 8 cm deep", "80 per minute, 1 cm deep"]'::jsonb, 0, 'Allow full recoil and minimise interruptions.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 32, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The compression-to-ventilation ratio for adult CPR without an advanced airway is:', '["5:1", "30:2", "15:2", "50:2"]'::jsonb, 1, 'Once intubated, give continuous compressions with ventilation at about 10 breaths per minute.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 33, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Shockable rhythms in cardiac arrest are:', '["Ventricular fibrillation and pulseless VT", "Asystole and pulseless electrical activity", "Sinus bradycardia and atrial fibrillation", "First-degree heart block and sinus rhythm"]'::jsonb, 0, 'Defibrillation is given for shockable rhythms; non-shockable rhythms need CPR and adrenaline.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 34, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'In a non-shockable cardiac arrest, adrenaline 1 mg IV is given:', '["Once only, at the very end of the arrest", "Never, because it is not a shockable rhythm", "As soon as possible, then every 3–5 min", "Only after the third defibrillator shock"]'::jsonb, 2, 'For shockable rhythms it is given after the third shock.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 35, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Amiodarone in shock-refractory VF is given at a dose of:', '["1 g IV before any shock", "50 mg orally", "30 mg IV after the first shock", "300 mg IV after the third shock"]'::jsonb, 3, 'A further 150 mg may be given after the fifth shock.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 36, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The reversible causes of cardiac arrest (4 Hs and 4 Ts) include:', '["Hypoxia, hypovolaemia, tension pneumothorax and tamponade", "Hypertension, hyperglycaemia, typhoid and tetanus", "Hypercalcaemia only", "Headache, haemorrhoids, tonsillitis and tinnitus"]'::jsonb, 0, 'The 4 Hs: hypoxia, hypovolaemia, hypo/hyperkalaemia (metabolic), hypothermia. The 4 Ts: thrombosis, tension pneumothorax, tamponade, toxins.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 37, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Capnography during CPR is useful because a sudden rise in end-tidal CO₂ suggests:', '["Oesophageal placement of the tube", "Worsening cardiac output during CPR", "Accidental extubation of the patient", "Return of spontaneous circulation"]'::jsonb, 3, 'It also confirms tube placement and assesses quality of compressions.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 38, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Open pneumothorax (''sucking chest wound'') is initially managed by:', '["Leaving the wound open to the air", "Packing the wound tightly with gauze", "A vented (three-sided) occlusive dressing", "Sealing the wound firmly on all four sides"]'::jsonb, 2, 'This prevents air entry while allowing escape; a chest drain is inserted later.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 39, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A patient with head injury and GCS 7 needs:', '["A soft collar only and nursing on the side", "Intubation and ventilation to protect the airway", "Sedation alone, without any airway support", "Oral fluids and hourly neurological observation"]'::jsonb, 1, 'GCS of 8 or less indicates inability to protect the airway; avoid hypoxia and hypotension.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 40, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Avoiding secondary brain injury after head trauma means preventing:', '["Hypoxia, hypotension, hypercapnia, hyperglycaemia", "A normal mean arterial blood pressure", "Normal arterial oxygen levels throughout", "A normal PaCO₂ on the blood gas"]'::jsonb, 0, 'These insults worsen outcome. Head-up tilt, normocapnia and adequate perfusion are key.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 41, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Tracheostomy is indicated for:', '["Prolonged ventilation, airway obstruction, secretions", "Short anaesthetics for day-case operations", "Mild asthma that responds to inhalers", "A simple closed fracture of the forearm"]'::jsonb, 0, 'Complications include bleeding, displacement, blockage, infection and stenosis.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 42, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A blocked tracheostomy tube in a ventilated patient is first managed by:', '["Increasing the ventilator pressure to force air through", "Removing the inner tube and passing a suction catheter", "Deflating the cuff and waiting for the patient to cough", "Giving a sedative to reduce the patient''s distress"]'::jsonb, 1, 'If still blocked, remove the tube and secure the airway via the stoma or orally.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 43, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The unconscious patient''s eyes need care because:', '["The eyes produce excess tears that need wiping", "Blinking is lost, risking corneal abrasion and ulcers", "The pupils become fixed and dilated in all cases", "The eyes cannot become infected while closed"]'::jsonb, 1, 'Lubricants and taping protect the cornea.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 44, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Pressure area care in the unconscious patient includes:', '["Turning 2-hourly and pressure-relieving mattresses", "Keeping the skin wet to prevent it from drying out", "Massaging reddened areas firmly to improve blood flow", "Turning the patient once a day in the morning"]'::jsonb, 0, 'Unconscious patients cannot shift their weight and are at high risk of pressure ulcers.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 45, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Respiratory obstruction in an unconscious patient is relieved first by:', '["Raising the legs to improve venous return", "Head tilt, chin lift or jaw thrust, and suction", "Giving IV fluids rapidly to raise blood pressure", "Giving an opioid to reduce the patient''s distress"]'::jsonb, 1, 'Airway adjuncts and positioning follow; definitive airway if needed.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 46, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'After thyroidectomy, a patient becomes breathless with a tense neck swelling. The first action is:', '["Give an oral analgesic and observe for 30 minutes", "Apply a tight pressure dressing around the neck", "Lie the patient flat with the neck extended", "Open the wound to release the haematoma and call for help"]'::jsonb, 3, 'Haematoma compresses the airway and causes venous congestion and laryngeal oedema.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 47, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Intensive care admission is indicated after surgery for a patient who:', '["Only needs oral analgesia and is eating and drinking", "Is fully alert with stable vital signs and good urine output", "Needs organ support such as ventilation or vasopressors", "Had uncomplicated minor surgery under local anaesthesia"]'::jsonb, 2, 'High-risk patients may also need high-dependency care.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 48, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The Nurse Anaesthetist''s role in resuscitation includes:', '["Only recording the times of events", "Leaving the scene to the doctors", "Performing emergency surgery", "Airway, ventilation, IV access and drugs"]'::jsonb, 3, 'Their airway skills are vital in arrest teams.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 49, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Cardio-pulmonary insufficiency means:', '["Heart and lungs cannot meet the body''s oxygen needs", "There is excess oxygen dissolved in the blood", "A normal, healthy response to hard exercise", "High blood pressure without any other problem"]'::jsonb, 0, 'It may progress to arrest without timely support.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 50, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Pulseless electrical activity (PEA) means:', '["Organised electrical activity without a pulse", "No electrical activity at all on the monitor", "Ventricular fibrillation on the monitor", "Normal sinus rhythm with a strong pulse"]'::jsonb, 0, 'It is treated with CPR, adrenaline and correcting reversible causes.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 51, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Atropine is used in bradycardia with adverse signs at a dose of:', '["500 micrograms IV, repeated to 3 mg", "50 micrograms IV once, not repeated", "1 mg IM, repeated every 30 minutes", "5 mg IV once as a single bolus"]'::jsonb, 0, 'Pacing or adrenaline infusion may be needed if atropine fails.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 52, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Defibrillation energy for an adult biphasic defibrillator is usually:', '["1000 J for every shock given", "10–20 J for the first shock", "150–200 J for the first shock", "500–600 J for the first shock"]'::jsonb, 2, 'Follow the manufacturer''s recommendations; children receive 4 J/kg.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 53, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Before delivering a shock, the operator must:', '["Leave the oxygen mask flowing over the chest during the shock", "Ensure no one touches the patient and oxygen is moved away", "Hold the patient''s hand to steady the arm during the shock", "Switch off the ECG monitor so that it is not damaged"]'::jsonb, 1, 'Safety checks prevent injury and fire.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 54, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Post-resuscitation care includes:', '["Controlling oxygen, BP, glucose and temperature", "Allowing fever to develop without treatment", "Extubating the patient immediately afterwards", "Stopping all monitoring once a pulse returns"]'::jsonb, 0, 'Targeted temperature management and treating the cause improve outcome.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 55, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Burns patients need early airway assessment because of:', '["An increased appetite after the burn", "Low fluid requirements in the first day", "Rapid loss of hair from the scalp", "Airway oedema from inhalation injury"]'::jsonb, 3, 'Singed nasal hair, hoarse voice and soot in sputum suggest inhalation injury; early intubation may be needed.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 56, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Flail chest leads to:', '["Paradoxical movement and poor ventilation", "A stronger and more effective cough", "No change at all in the breathing pattern", "Increased lung compliance and easy breathing"]'::jsonb, 0, 'Pain relief and ventilatory support may be needed.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 57, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Cardiac tamponade presents with Beck''s triad of:', '["Hypotension, raised JVP and muffled heart sounds", "Polyuria, polydipsia and weight loss", "Hypertension, bradycardia and irregular breathing", "Fever, rash and joint pain"]'::jsonb, 0, 'Treatment is urgent pericardiocentesis or surgical drainage.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 58, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Tension pneumothorax presents with:', '["Normal breath sounds with a low JVP and warm skin", "Fever and a productive cough with green sputum", "Bradycardia and high blood pressure with a clear chest", "Hypoxia, hypotension, tracheal shift, absent breath sounds"]'::jsonb, 3, 'Immediate needle decompression is life-saving.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 59, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A patient on a ventilator with sudden high airway pressure alarm should be checked for:', '["Disconnection of the circuit from the patient only", "A low tidal volume setting on the ventilator", "Failure of the ventilator battery or power only", "Tube blockage, kinking, bronchospasm or pneumothorax"]'::jsonb, 3, 'Use the DOPE mnemonic: Displacement, Obstruction, Pneumothorax, Equipment failure.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 60, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A low pressure alarm on a ventilator most often indicates:', '["Disconnection or leak", "Bronchospasm", "Blocked tube", "Coughing"]'::jsonb, 0, 'Check connections and cuff pressure first.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 61, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Polytrauma patients are assessed using the primary survey sequence:', '["History, examination, X-ray, treatment", "Exposure, Disability, Circulation, Breathing, Airway", "Circulation, Airway, Breathing, Disability, Exposure", "Airway with C-spine, Breathing, Circulation, Disability, Exposure"]'::jsonb, 3, 'ATLS principles prioritise life-threatening problems.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 62, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The unconscious patient''s nutrition is best provided by:', '["IV 5% dextrose alone for several weeks", "Enteral feeding by nasogastric tube", "Oral feeding while still unconscious", "No feeding for the first two weeks"]'::jsonb, 1, 'Enteral feeding maintains gut integrity; position is confirmed before use.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 63, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Hypothermia after trauma is dangerous because it:', '["Worsens coagulopathy and acidosis", "Raises the blood pressure helpfully", "Prevents wound infection completely", "Improves clotting and stops bleeding"]'::jsonb, 0, 'The ''lethal triad'' is hypothermia, acidosis and coagulopathy.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 64, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Oxygen therapy for a patient with COPD in respiratory failure should target SpO₂ of:', '["80–84%", "98–100%", "88–92%", "70–75%"]'::jsonb, 2, 'Excess oxygen may worsen hypercapnia in some COPD patients.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 65, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Care of a central venous line includes:', '["Using the line without flushing between drugs", "Opening the line frequently to the air to check it", "Asepsis, a secure dressing and checks for infection", "Leaving the insertion site without any dressing"]'::jsonb, 2, 'Central line infections are reduced by bundles of care.', 'NAP 424 · Resuscitation & Intensive Care'),
(5, 66, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'A patient with a full stomach for emergency laparotomy requires:', '["Rapid sequence induction with cricoid and a cuffed tube", "Inhalational induction with a face mask and sevoflurane", "A laryngeal mask airway without endotracheal intubation", "Awake induction without any pre-oxygenation"]'::jsonb, 0, 'Pre-oxygenation, suction ready, rapid-onset relaxant and no bag-mask ventilation (unless needed) reduce aspiration.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 67, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Gastric emptying is delayed by:', '["Fasting for 6 hours before surgery", "Lying in the left lateral position", "Metoclopramide given before induction", "Pain, opioids, labour, trauma, diabetes"]'::jsonb, 3, 'Such patients are treated as having a full stomach regardless of fasting time.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 68, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Day-case anaesthesia should aim for:', '["Avoidance of all local and regional anaesthesia", "Long-acting drugs to give deep sedation for hours", "Routine overnight admission for every patient", "Rapid recovery with little nausea and good analgesia"]'::jsonb, 3, 'Short-acting agents (propofol, remifentanil, sevoflurane) and regional techniques help.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 69, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'A day-case patient should be discharged with:', '["No follow-up plan or contact number at all", "A responsible adult, written advice and analgesia", "A supply of long-acting sedative tablets", "Instructions to drive themselves home safely"]'::jsonb, 1, 'Patients should not drive, operate machinery or sign legal documents for 24 hours.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 70, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Supine hypotensive syndrome in pregnancy is due to:', '["Excess circulating blood volume in pregnancy", "Compression of the spinal cord by the fetus", "Pulmonary embolism from the leg veins", "Uterine compression of the IVC and aorta"]'::jsonb, 3, 'Left lateral tilt or manual uterine displacement relieves it.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 71, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'The preferred anaesthetic technique for elective caesarean section is usually:', '["Local infiltration only", "General anaesthesia with thiopentone", "Spinal anaesthesia", "Inhalational induction"]'::jsonb, 2, 'Regional anaesthesia avoids airway risks and allows the mother to be awake.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 72, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Hypotension after spinal for caesarean section is treated with:', '["Stopping all IV fluids to avoid overload", "Lying flat on the back without any tilt", "Vasopressors, fluids and left uterine displacement", "Giving glyceryl trinitrate under the tongue"]'::jsonb, 2, 'Maternal hypotension reduces placental perfusion.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 73, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'General anaesthesia in obstetrics carries a higher risk of:', '["Hypothermia only, nothing else", "Faster recovery than regional", "Lower blood loss at delivery", "Failed intubation and aspiration"]'::jsonb, 3, 'Airway oedema, breast enlargement and full stomach make intubation more difficult.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 74, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Emergency surgery carries higher anaesthetic risk mainly because:', '["Surgeons always operate faster at night", "Less time to assess and optimise the patient", "Emergency drugs are much stronger than usual", "Emergency patients are always younger"]'::jsonb, 1, 'Hypovolaemia, full stomach and unstable physiology are common.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 75, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Elderly patients under anaesthesia are at risk of:', '["Increased tolerance to most drugs", "A lower risk of falls after surgery", "Delirium, hypothermia and drug sensitivity", "Much faster recovery than the young"]'::jsonb, 2, 'Doses are reduced and careful monitoring is essential.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 76, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Hypothermia during anaesthesia occurs mainly because:', '["Anaesthesia impairs thermoregulation and dilates vessels", "Patients shiver strongly throughout general anaesthesia", "Theatre lights cause heat loss by radiation from the skin", "IV fluids are always warmed, so the body cannot cool"]'::jsonb, 0, 'Redistribution of heat from core to periphery occurs in the first hour.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 77, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Heat loss in theatre is reduced by:', '["Lowering the theatre temperature to 16 °C", "Using cold irrigation fluid in the cavity", "Forced-air warming, warm fluids, covering the patient", "Removing all blankets once the patient is asleep"]'::jsonb, 2, 'Normothermia reduces infection, bleeding and cardiac complications.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 78, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Pain relief in labour by epidural analgesia uses:', '["General anaesthesia", "High concentrations of local anaesthetic only", "Low concentrations of local anaesthetic with opioid", "Intramuscular morphine only"]'::jsonb, 2, 'Low doses preserve motor function and the mother''s ability to push.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 79, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Entonox, used for labour analgesia, is:', '["50% nitrous oxide and 50% oxygen", "100% nitrous oxide", "Air and carbon dioxide", "25% oxygen and 75% nitrogen"]'::jsonb, 0, 'It is self-administered via a demand valve; it should not be stored below −6 °C (separation).', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 80, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Pethidine for labour analgesia may cause in the newborn:', '["Hyperthermia", "Hypertension", "Hyperglycaemia", "Respiratory depression"]'::jsonb, 3, 'Naloxone can be given to the newborn if needed.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 81, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'After abdominal surgery, epidural analgesia helps by:', '["Increasing the total opioid requirement", "Giving good pain relief and improving breathing", "Increasing nausea and vomiting after surgery", "Delaying mobilisation for several days"]'::jsonb, 1, 'It reduces respiratory complications and improves bowel recovery.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 82, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'After thoracic surgery, good analgesia is essential to:', '["Reduce the urine output", "Allow deep breathing and coughing", "Improve sleep, nothing else", "Increase the blood pressure"]'::jsonb, 1, 'Thoracic epidural or paravertebral blocks are common.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 83, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Pain relief after neurosurgery should avoid:', '["Regular assessment of pain and conscious level", "Regular paracetamol given intravenously", "Local anaesthetic scalp blocks at the end", "Heavy sedation that masks neurological decline"]'::jsonb, 3, 'Neurological observations must be possible.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 84, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Pain in chronic arthritis is commonly managed with:', '["Repeated general anaesthesia for pain", "Long-term high-dose IV opioids at home", "No treatment, as nothing helps arthritis", "NSAIDs, physiotherapy and joint injections"]'::jsonb, 3, 'These patients may have difficult airways or positioning due to joint disease.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 85, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Patients with rheumatoid arthritis may have which airway problem?', '["Atlanto-axial instability of the cervical spine", "No airway problems in any rheumatoid patient", "A large mouth opening and a small tongue", "Very easy neck extension at laryngoscopy"]'::jsonb, 0, 'Neck manipulation during intubation can cause cord compression.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 86, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Surgery for endocrine disorders such as phaeochromocytoma requires:', '["Fluid restriction alone before surgery", "No preparation, as BP settles itself", "Beta-blockade alone, started first", "BP control with alpha-blockade first, then beta"]'::jsonb, 3, 'Unopposed alpha stimulation can cause a hypertensive crisis if beta-blockade comes first.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 87, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Diabetic patients having emergency surgery need:', '["Glucose monitoring with insulin/dextrose as needed", "Their usual oral drugs only, with no checks", "Strict fluid restriction from admission", "No glucose checks until the next morning"]'::jsonb, 0, 'Stress and fasting disrupt glucose control.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 88, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'A pregnant woman having non-obstetric surgery should, where possible:', '["First trimester, as early as possible", "Second trimester, with fetal monitoring as needed", "No anaesthesia at all until after delivery", "Flat on the back without any uterine tilt"]'::jsonb, 1, 'The first trimester has teratogenic risks; the third has preterm labour risks.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 89, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Amniotic fluid embolism presents with:', '["A slowly rising blood pressure", "Fever and a rash only", "Sudden hypoxia, collapse and DIC", "A headache with no other signs"]'::jsonb, 2, 'It is rare and catastrophic; treatment is supportive with resuscitation.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 90, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Pre-eclampsia increases anaesthetic risk mainly due to:', '["Hypotension and polyuria with thirst", "Low intracranial pressure and headache", "Hypertension, airway oedema and low platelets", "A raised platelet count and clotting"]'::jsonb, 2, 'Platelets must be checked before neuraxial block.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 91, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'For a patient with a full stomach, after rapid sequence induction, cricoid pressure is released:', '["Immediately after the induction drug", "When the patient starts to breathe", "After cuff inflation and tube confirmation", "Before the muscle relaxant is given"]'::jsonb, 2, 'Release only on the anaesthetist''s instruction.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 92, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Post-operative shivering increases oxygen consumption by up to:', '["5%", "200–400%", "20%", "50% at most"]'::jsonb, 1, 'This can be dangerous in patients with heart disease; warming and oxygen are given.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 93, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'In outpatients (day cases), spinal anaesthesia may delay discharge because of:', '["Faster mobilisation than general", "Rapid recovery and early walking", "Residual motor block and urinary retention", "Having no side effects at all"]'::jsonb, 2, 'Short-acting spinal drugs may reduce these problems.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 94, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'An elderly patient''s induction dose of propofol should be:', '["Given as a rapid bolus", "Reduced and given slowly", "Doubled", "The same as a young adult''s"]'::jsonb, 1, 'Reduced cardiac output and drug sensitivity increase the risk of hypotension.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 95, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'A patient for emergency surgery with shock should be:', '["Sent to the ward first", "Induced with full doses immediately", "Resuscitated before and during induction", "Given no fluids"]'::jsonb, 2, 'Reduced doses of induction agents and vasopressors are prepared.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 96, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Malignant hyperthermia risk should be considered in patients with:', '["Asthma controlled with a salbutamol inhaler only", "A family history of death or fever under anaesthesia", "A known allergy to penicillin or cephalosporins", "Normal previous anaesthetics in all relatives"]'::jsonb, 1, 'A trigger-free anaesthetic is used for susceptible patients.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 97, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Temperature monitoring during anaesthesia is essential in:', '["Only theatres in hot climates", "Only cases under local anaesthesia", "Children, long cases and the elderly", "Only short cases under 30 minutes"]'::jsonb, 2, 'It detects hypothermia and malignant hyperthermia.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 98, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'The anaesthetic concern in obesity is:', '["Difficult airway, fast desaturation, aspiration", "Easy intubation because of a wide neck", "A better oxygen reserve during apnoea", "Lower drug doses needed in every case"]'::jsonb, 0, 'Ramped positioning and pre-oxygenation help.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 99, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Abdominal surgery pain relief by transversus abdominis plane (TAP) block works by:', '["Blocking the spinal cord directly", "Blocking nerves in the abdominal wall", "Acting on opioid receptors in the gut", "Blocking the brachial plexus nerves"]'::jsonb, 1, 'It reduces opioid requirements after abdominal surgery.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(5, 100, 'Anaesthesia Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Anaesthesia for the elderly should consider:', '["Faster clearance of most drugs", "Reduced reserve, many drugs, cognition", "No need for routine monitoring", "Increased organ reserve with age"]'::jsonb, 1, 'Careful assessment and planning reduce complications.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(6, 1, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'One-lung ventilation during thoracic surgery is usually achieved with:', '["A standard single-lumen tube in the trachea", "A laryngeal mask airway", "A nasopharyngeal airway", "A double-lumen endobronchial tube"]'::jsonb, 3, 'Bronchial blockers are an alternative. Correct position is confirmed by auscultation or fibreoptic bronchoscopy.', 'NAP 432 · General Anaesthesia II'),
(6, 2, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The main problem during one-lung ventilation is:', '["Excess urine output from the lateral position", "Hypercapnia only, with normal oxygen saturation", "Hypoxaemia from shunt through the unventilated lung", "Severe hypertension from lung manipulation"]'::jsonb, 2, 'Increasing FiO₂, CPAP to the non-ventilated lung and PEEP to the ventilated lung help.', 'NAP 432 · General Anaesthesia II'),
(6, 3, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The lateral decubitus position for thoracotomy requires attention to:', '["Prone pillows under the chest and pelvis", "An axillary roll, padding and neck alignment", "Lithotomy stirrups for both of the legs", "A head-down tilt of about 45 degrees"]'::jsonb, 1, 'The roll under the upper chest protects the dependent brachial plexus.', 'NAP 432 · General Anaesthesia II'),
(6, 4, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'TURP syndrome under anaesthesia presents with:', '["Bronchospasm and an urticarial rash on the chest", "Confusion, bradycardia, unstable BP and hyponatraemia", "Hypernatraemia and polyuria with great thirst", "Hyperkalaemia and fever only, with clear urine"]'::jsonb, 1, 'Spinal anaesthesia allows early detection by monitoring the patient''s mental state.', 'NAP 432 · General Anaesthesia II'),
(6, 5, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Anaesthesia outside the operating theatre (e.g. in the MRI or radiology suite) requires:', '["No monitoring, because these procedures are short", "No trained assistant, as the radiographer can help", "The same monitoring and equipment standards as theatre", "Only a pulse oximeter, with no oxygen supply at all"]'::jsonb, 2, 'Remote locations have limited help, so preparation and communication are vital.', 'NAP 432 · General Anaesthesia II'),
(6, 6, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'In the MRI suite, anaesthetic equipment must be:', '["Identical to theatre equipment", "Made of steel for strength", "MRI-compatible (non-ferromagnetic)", "Battery-powered only"]'::jsonb, 2, 'Ferromagnetic objects become dangerous projectiles.', 'NAP 432 · General Anaesthesia II'),
(6, 7, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'For a patient with a head injury, the anaesthetist aims to keep:', '["PaCO₂ high to increase cerebral blood flow", "Normal PaCO₂, adequate CPP and avoid hypoxia", "Blood pressure very low", "The head flat and turned to one side"]'::jsonb, 1, 'Head-up tilt and avoiding venous obstruction reduce ICP.', 'NAP 432 · General Anaesthesia II'),
(6, 8, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Ketamine was traditionally avoided in head injury because of concern about:', '["Severe hypotension at induction", "Raised intracranial pressure", "Hypoglycaemia after injury", "Bronchospasm in head injury"]'::jsonb, 1, 'Recent evidence suggests it may be acceptable when ventilation is controlled.', 'NAP 432 · General Anaesthesia II'),
(6, 9, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Chest injury with rib fractures should be considered before using nitrous oxide because of:', '["Better analgesia", "Decreased oxygen need", "Increased cardiac output", "Possible pneumothorax expansion"]'::jsonb, 3, 'Nitrous oxide expands closed air spaces.', 'NAP 432 · General Anaesthesia II'),
(6, 10, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Burns patients needing repeated dressings are often anaesthetised with:', '["Ketamine", "Suxamethonium after 48 hours", "Pure local infiltration only", "Halothane repeatedly"]'::jsonb, 0, 'Ketamine provides analgesia and preserves airway reflexes; suxamethonium is avoided after 24–48 hours.', 'NAP 432 · General Anaesthesia II'),
(6, 11, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Fluid requirements in burns are calculated from:', '["The haemoglobin level only, on admission", "The patient''s age only, in years", "Body weight and % body surface area burnt", "The patient''s height only, in centimetres"]'::jsonb, 2, 'The Parkland formula gives 4 mL × kg × %TBSA in 24 hours, half in the first 8 hours.', 'NAP 432 · General Anaesthesia II'),
(6, 12, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'In polytrauma patients, the cervical spine during intubation is protected by:', '["Turning the head to the side", "Full neck extension", "Manual in-line stabilisation", "Removing the collar and flexing the neck"]'::jsonb, 2, 'The front of the collar may be opened to allow laryngoscopy while in-line stabilisation is maintained.', 'NAP 432 · General Anaesthesia II'),
(6, 13, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Spinal anaesthesia is contraindicated in:', '["A simple fracture of the lower leg in a fit adult", "A caesarean section in a stable, healthy mother", "Refusal, coagulopathy, local infection, severe hypovolaemia", "An elective inguinal hernia repair in an older man"]'::jsonb, 2, 'Raised intracranial pressure is also a contraindication.', 'NAP 432 · General Anaesthesia II'),
(6, 14, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The level of spinal anaesthesia depends mainly on:', '["Time of day", "Baricity, dose and patient position", "The colour of the solution", "The size of the syringe only"]'::jsonb, 1, 'Hyperbaric solutions move with gravity.', 'NAP 432 · General Anaesthesia II'),
(6, 15, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Epidural anaesthesia differs from spinal in that it:', '["Uses a much smaller volume of drug", "Has a slower onset and needs a larger dose", "Always gives a denser motor block", "Is injected directly into the CSF"]'::jsonb, 1, 'An epidural catheter allows top-ups and prolonged analgesia.', 'NAP 432 · General Anaesthesia II'),
(6, 16, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A test dose through an epidural catheter is given to detect:', '["Intravascular or intrathecal placement", "The patient''s blood group and type", "How fast the stomach is emptying", "An allergy to the antibiotics given"]'::jsonb, 0, 'Adrenaline-containing solutions may cause tachycardia if intravascular.', 'NAP 432 · General Anaesthesia II'),
(6, 17, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Total spinal after an epidural top-up presents with:', '["Severe hypotension, bradycardia, apnoea and coma", "Hypertension and seizures without any hypotension", "Leg weakness only, with normal breathing", "No change in breathing or in consciousness"]'::jsonb, 0, 'Treatment is airway support, ventilation, fluids and vasopressors.', 'NAP 432 · General Anaesthesia II'),
(6, 18, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Epidural haematoma after neuraxial block presents with:', '["Urinary frequency only, without any back pain", "A headache that is relieved by lying down flat", "Itching only, starting soon after the injection", "Back pain with worsening leg weakness and numbness"]'::jsonb, 3, 'Urgent MRI and surgical decompression are needed within hours.', 'NAP 432 · General Anaesthesia II'),
(6, 19, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A caudal block is commonly used in:', '["Adults, for thoracic surgery and lung resection", "Children, for lower abdominal and perineal surgery", "Neck surgery such as thyroidectomy", "Upper limb surgery on the hand and forearm"]'::jsonb, 1, 'It is given via the sacral hiatus into the epidural space.', 'NAP 432 · General Anaesthesia II'),
(6, 20, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Neurolept anaesthesia is useful for:', '["Deep paralysis for a long laparotomy", "Rapid sequence induction with cricoid", "Procedures needing a calm, cooperative patient", "Long-term sedation in intensive care"]'::jsonb, 2, 'It combines a neuroleptic with an opioid, often with nitrous oxide.', 'NAP 432 · General Anaesthesia II'),
(6, 21, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Dissociative anaesthesia is produced by:', '["Ketamine", "Propofol", "Midazolam", "Thiopentone"]'::jsonb, 0, 'Patients appear awake but are disconnected from surroundings.', 'NAP 432 · General Anaesthesia II'),
(6, 22, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Post-dural puncture headache is reduced by using:', '["Small-gauge, pencil-point spinal needles", "Large-gauge cutting (Quincke) needles", "Several repeated punctures at one level", "High-dose opioids added to the spinal"]'::jsonb, 0, 'Epidural blood patch treats persistent headache.', 'NAP 432 · General Anaesthesia II'),
(6, 23, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Urological surgery in the lithotomy position may cause:', '["Raised intracranial pressure from the leg position", "Improved breathing from the raised position of legs", "Nerve injury and BP changes as the legs are moved", "Brachial plexus injury only, from the arm boards"]'::jsonb, 2, 'Legs are raised and lowered together and slowly.', 'NAP 432 · General Anaesthesia II'),
(6, 24, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Venous air embolism is suspected in theatre when there is:', '["A rising oxygen saturation with tachycardia", "A sudden rise in end-tidal CO₂ with fever", "Bradycardia with hypertension and no other sign", "A sudden fall in end-tidal CO₂ with hypotension"]'::jsonb, 3, 'Flood the field with saline, lower the head, give 100% oxygen and support circulation.', 'NAP 432 · General Anaesthesia II'),
(6, 25, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Before regional anaesthesia, the nurse anaesthetist must ensure:', '["No monitoring is attached, to keep things simple", "The patient has eaten a full meal beforehand", "Resuscitation equipment and lipid emulsion are ready", "No IV access is needed for a small nerve block"]'::jsonb, 2, 'Any regional block can lead to toxicity or high block.', 'NAP 432 · General Anaesthesia II'),
(6, 26, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Hypotension after induction in a trauma patient is treated by:', '["Fluids, blood products and vasopressors", "Diuretics to protect the kidneys", "A head-up tilt to improve the view", "More induction agent to deepen sleep"]'::jsonb, 0, 'Doses of induction agents should be reduced in hypovolaemia.', 'NAP 432 · General Anaesthesia II'),
(6, 27, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Thoracic surgery patients are at risk post-operatively of:', '["Excess urine output and dehydration", "Hypoglycaemia and confusion", "Atelectasis, pneumonia and air leaks", "Raised intracranial pressure"]'::jsonb, 2, 'Chest physiotherapy and good analgesia are needed.', 'NAP 432 · General Anaesthesia II'),
(6, 28, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A chest drain after thoracotomy should be:', '["Below chest level with an underwater seal", "Clamped at all times", "Above chest level", "Removed immediately after surgery"]'::jsonb, 0, 'Swinging confirms patency; bubbling indicates air leak.', 'NAP 432 · General Anaesthesia II'),
(6, 29, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Spinal anaesthesia causes hypotension mainly through:', '["Fluid overload from the injected volume", "Release of adrenaline from the adrenals", "Increased cardiac output from the block", "Sympathetic blockade and vasodilation"]'::jsonb, 3, 'Preloading or coloading with fluids and vasopressors reduces it.', 'NAP 432 · General Anaesthesia II'),
(6, 30, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'In a crush injury, the anaesthetist should anticipate:', '["Hyperkalaemia and acute kidney injury", "Hypokalaemia and polyuria with thirst", "Hypercalcaemia with kidney stones", "Hypernatraemia with oedema of the legs"]'::jsonb, 0, 'Myoglobin from damaged muscle damages kidneys.', 'NAP 432 · General Anaesthesia II'),
(6, 31, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient with severe head injury and hypotension most likely has:', '["Hypotension caused by the head injury itself", "Normal findings after trauma", "Hypertension", "Another source of bleeding elsewhere"]'::jsonb, 3, 'Isolated head injury rarely causes hypotension except in infants or terminal stages.', 'NAP 432 · General Anaesthesia II'),
(6, 32, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Regional anaesthesia advantages include:', '["It is always faster than a general anaesthetic", "It carries no risk of any complication at all", "No airway manipulation, plus post-operative analgesia", "It removes the need for any patient monitoring"]'::jsonb, 2, 'Patient cooperation and contraindications must be considered.', 'NAP 432 · General Anaesthesia II'),
(6, 33, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Anaesthesia for laparoscopic surgery must consider:', '["Increased venous return in every patient position", "No change in physiology from the pneumoperitoneum", "CO₂ absorption, raised abdominal pressure, positioning", "Lower ventilation needs because CO₂ is not absorbed"]'::jsonb, 2, 'Pneumoperitoneum reduces lung compliance and may cause arrhythmias.', 'NAP 432 · General Anaesthesia II'),
(6, 34, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Interscalene brachial plexus block commonly causes:', '["Bilateral leg weakness", "Ipsilateral phrenic nerve block", "Total spinal in every case", "Facial nerve palsy"]'::jsonb, 1, 'It may cause breathlessness in patients with poor respiratory reserve.', 'NAP 432 · General Anaesthesia II'),
(6, 35, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A Bier''s block (IV regional anaesthesia) requires:', '["Bupivacaine as the local anaesthetic of choice", "No tourniquet, so the drug can spread freely", "A double tourniquet kept inflated for at least 20 minutes", "A general anaesthetic first, before the injection"]'::jsonb, 2, 'Early tourniquet release can cause local anaesthetic toxicity. Prilocaine or lidocaine is used.', 'NAP 432 · General Anaesthesia II'),
(6, 36, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'In ophthalmic surgery, the oculocardiac reflex causes:', '["Hypothermia from the cold eye drops", "Raised blood glucose from stress", "Bradycardia when the eye or its muscles are pulled", "Tachycardia and hypertension from pain"]'::jsonb, 2, 'Stop the stimulus; atropine or glycopyrrolate may be needed. It is common in squint surgery in children.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 37, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Suxamethonium may be undesirable in open eye injury because it:', '["Causes immediate blindness", "Has no effect on the eye", "Lowers intraocular pressure", "Raises intraocular pressure"]'::jsonb, 3, 'Rocuronium is often used for RSI in open globe injuries.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 38, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'In ENT surgery with a shared airway, the main concern is:', '["Excess urine output during the procedure", "Hidden obstruction or disconnection under the drapes", "Nerve injury to the legs from positioning", "Low blood glucose only during long surgery"]'::jsonb, 1, 'Secure tube fixation and good communication with the surgeon are essential.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 39, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Bleeding after tonsillectomy requiring re-operation is dangerous because the child:', '["Has swallowed blood and is hypovolaemic", "Needs no fluid resuscitation at all", "Has a reduced risk of aspiration", "Is always fully fasted and empty"]'::jsonb, 0, 'RSI with suction ready and fluid resuscitation are needed.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 40, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A throat pack placed during ENT or dental surgery must be:', '["Left in place until the next day", "Not counted", "Recorded and removed before extubation", "Removed by the recovery nurse"]'::jsonb, 2, 'Retained packs cause airway obstruction.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 41, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Dental anaesthesia in children often uses:', '["Long-acting opioids only, given IM", "Inhalational induction and a nasal mask or tube", "Spinal anaesthesia with a fine needle", "No monitoring, because cases are short"]'::jsonb, 1, 'The surgeon and anaesthetist share access to the mouth.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 42, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'For maxillofacial fractures, nasal intubation is avoided when there is:', '["Normal nasal anatomy", "A fractured mandible only", "Suspected base of skull fracture", "A simple tooth extraction"]'::jsonb, 2, 'Submental intubation or tracheostomy may be used.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 43, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'After surgery with intermaxillary fixation, the recovery room must have:', '["Wire cutters at the bedside", "A urinary catheter", "A sterile dressing pack only", "A plaster saw"]'::jsonb, 0, 'If vomiting or airway obstruction occurs, wires must be cut immediately.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 44, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Neonates are at risk under anaesthesia because of:', '["Large oxygen reserves in the lungs", "Mature liver and kidney function", "A low metabolic rate and oxygen need", "Small FRC, high O₂ consumption, poor heat control"]'::jsonb, 3, 'They desaturate quickly and lose heat easily.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 45, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'The neonate''s airway differs from the adult''s because of:', '["Large tongue, high larynx and floppy epiglottis", "Small tongue and low larynx", "Wide narrowest point at the vocal cords", "Rigid epiglottis"]'::jsonb, 0, 'A straight blade is often used in neonates.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 46, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Fasting time for breast milk before elective anaesthesia in infants is usually:', '["4 hours (some guidelines 3)", "30 minutes before induction", "8 hours before induction", "12 hours before induction"]'::jsonb, 0, 'Clear fluids are allowed until 1 hour in children in many current guidelines.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 47, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A suitable maintenance fluid for children is calculated using:', '["The 4-2-1 rule (mL/kg/hour)", "The rule of nines for burns", "The Glasgow Coma Scale", "The Parkland burns formula"]'::jsonb, 0, '4 mL/kg/hr for the first 10 kg, 2 for the next 10 kg, 1 for each kg above 20.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 48, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Orthopaedic procedures using bone cement may cause:', '["Cement implantation syndrome: hypotension and hypoxia", "Hyperglycaemia from the cement chemicals", "Bradycardia alone without any fall in pressure", "Hypertension and hyperthermia from the cement heat"]'::jsonb, 0, 'Monitor closely when cement is inserted, especially in elderly hip fractures.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 49, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A tourniquet in orthopaedic surgery should be:', '["Inflated without any record of time or pressure", "Left inflated as long as the surgeon needs it", "Used on the neck to reduce bleeding from the face", "Recorded with time and pressure, usually under 2 hours"]'::jsonb, 3, 'Prolonged inflation causes nerve and muscle injury; release causes metabolic changes.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 50, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Anaemic patients undergoing surgery need careful anaesthesia because:', '["They tolerate hypoxia better than other patients", "They have a raised blood viscosity and clot easily", "They need less oxygen because of fewer red cells", "Oxygen delivery is low and relies on cardiac output"]'::jsonb, 3, 'Avoid hypotension and hypoxia; transfusion is considered if needed.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 51, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Patients with hypertension should continue most antihypertensives on the morning of surgery, except often:', '["Calcium channel blockers such as amlodipine", "All drugs, which must always be stopped", "Beta-blockers such as atenolol", "ACE inhibitors/ARBs (per local policy)"]'::jsonb, 3, 'Stopping beta-blockers causes rebound tachycardia; ACE inhibitors may cause hypotension under anaesthesia.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 52, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Elective surgery may be postponed if blood pressure is:', '["130/80 mmHg", "180/110 mmHg or higher", "120/70 mmHg", "140/90 mmHg"]'::jsonb, 1, 'Severe uncontrolled hypertension increases the risk of stroke and myocardial ischaemia.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 53, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'For a diabetic patient on insulin having surgery, the main danger to watch for under anaesthesia is:', '["Malignant hyperthermia", "Severe hypercalcaemia", "Secondary polycythaemia", "Unrecognised hypoglycaemia"]'::jsonb, 3, 'Signs of hypoglycaemia are masked by anaesthesia; frequent glucose checks are needed.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 54, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Asthmatic patients should receive before anaesthesia:', '["A beta-blocker to steady the heart", "Their usual inhalers, avoiding triggers", "No inhalers on the day of surgery", "Drugs that release histamine"]'::jsonb, 1, 'Propofol, ketamine and volatile agents are bronchodilators; avoid light anaesthesia during intubation.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 55, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Bronchospasm during anaesthesia is treated with:', '["Deeper anaesthesia, 100% oxygen, bronchodilators", "IV neostigmine to reverse the block", "IV morphine to relax the airways", "Lowering the FiO₂ to 21%"]'::jsonb, 0, 'Salbutamol, ipratropium, IV magnesium or adrenaline may be needed.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 56, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'In patients with HIV/AIDS, anaesthetic staff should:', '["Use special precautions only for these patients", "Apply standard precautions as for all patients", "Refuse to give anaesthesia", "Avoid regional anaesthesia always"]'::jsonb, 1, 'Standard precautions apply universally.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 57, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Obese patients should be positioned for intubation:', '["Ramped, ear level with the sternum", "Head-down tilt of 20 degrees", "Prone, with the face turned", "Flat, with no pillow at all"]'::jsonb, 0, 'This improves laryngoscopy view and oxygenation.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 58, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Drug doses in obesity such as suxamethonium are based on:', '["Ideal body weight always", "Age only", "Lean body weight always", "Total body weight"]'::jsonb, 3, 'Some drugs (e.g. propofol induction) use lean body weight; suxamethonium uses total body weight.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 59, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Children with an upper respiratory tract infection are at increased risk of:', '["Acute kidney failure", "Hyperthermia only", "Severe hypertension", "Laryngospasm and bronchospasm"]'::jsonb, 3, 'Elective surgery may be postponed for 2–4 weeks in significant infections.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 60, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Sickle cell patients for surgery may be prepared with:', '["Hydration, oxygen, warmth and possibly transfusion", "A cold theatre to slow the metabolism", "Avoiding oxygen to prevent toxicity", "Fluid restriction from the night before"]'::jsonb, 0, 'Preventing crisis is key.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 61, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Laryngeal mask use in ENT/dental surgery is acceptable when:', '["There is massive bleeding into the mouth", "The airway is shared carefully and protected from blood", "A laser is to be used close to the airway", "The patient has a full stomach and needs surgery"]'::jsonb, 1, 'Flexible LMAs are often used in tonsillectomy and dental surgery.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 62, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Anaesthesia for cataract surgery is commonly:', '["Spinal anaesthesia at the L3 level", "Local (peribulbar, sub-Tenon''s or topical)", "Epidural anaesthesia via a catheter", "General anaesthesia in every case"]'::jsonb, 1, 'Elderly patients with comorbidities benefit from local techniques.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 63, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'In paediatric anaesthesia, parental presence at induction can:', '["Cause the child to stop breathing", "Reduce the child''s anxiety", "Replace premedication always", "Increase all complications"]'::jsonb, 1, 'Parents are prepared and escorted out after induction.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 64, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Emergence delirium in children is more common after:', '["Local anaesthesia", "Sevoflurane anaesthesia", "No anaesthesia", "Spinal anaesthesia"]'::jsonb, 1, 'Adequate analgesia and calm recovery reduce it.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 65, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Positioning for orthopaedic shoulder surgery in the ''beach chair'' position risks:', '["Dislocation of the hip on the same side", "Cerebral hypoperfusion if the BP falls", "Aortocaval compression by the abdomen", "Lithotomy-type peroneal nerve injury"]'::jsonb, 1, 'Blood pressure measured at the arm may overestimate cerebral perfusion.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 66, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A patient on long-term steroids having major surgery needs:', '["Steroids stopped a week before", "No special care", "Steroid cover to prevent adrenal crisis", "Double insulin"]'::jsonb, 2, 'Hydrocortisone is given at induction and continued as needed.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 67, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Patients with cardiac disease are at risk under anaesthesia of:', '["Kidney stones from fluid restriction", "Ischaemia, arrhythmias and heart failure", "Hypoglycaemia only, with no cardiac events", "Hyperthermia from increased metabolism"]'::jsonb, 1, 'Avoid tachycardia, hypotension and hypoxia.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 68, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A nasal intubation for dental surgery is usually placed via:', '["The ear canal, through the eardrum", "The tracheostomy stoma in the neck", "The nostril, after vasoconstrictor and lubricant", "The mouth only, beside the surgeon''s hands"]'::jsonb, 2, 'Nasal tubes give the surgeon free access to the mouth.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 69, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Strabismus surgery in children is associated with high rates of:', '["Acute kidney failure", "Hyperglycaemia and ketosis", "Post-operative nausea and vomiting", "Acute liver failure"]'::jsonb, 2, 'Prophylactic antiemetics are given.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 70, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Orthopaedic patients with hip fracture benefit from:', '["Early surgery and a fascia iliaca block", "No analgesia, to avoid confusion", "Delaying surgery for several weeks", "Only oral analgesics, given as needed"]'::jsonb, 0, 'Early surgery reduces mortality and complications.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(6, 71, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Beta-blockers before surgery are generally:', '["Continued if the patient takes them regularly", "Stopped abruptly on the morning of surgery", "Replaced by diuretics", "Started in all patients the day before surgery"]'::jsonb, 0, 'Abrupt withdrawal causes rebound tachycardia and ischaemia.', 'NAP 431 · Applied Pharmacology III'),
(6, 72, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Furosemide acts on the:', '["Collecting duct only", "Glomerulus", "Proximal tubule", "Loop of Henle"]'::jsonb, 3, 'It causes hypokalaemia, hyponatraemia and ototoxicity at high doses.', 'NAP 431 · Applied Pharmacology III'),
(6, 73, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Spironolactone can cause:', '["Hyperkalaemia", "Hypercalcaemia", "Hypokalaemia", "Hypernatraemia"]'::jsonb, 0, 'It is a potassium-sparing aldosterone antagonist.', 'NAP 431 · Applied Pharmacology III'),
(6, 74, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Oxytocin given rapidly at caesarean section can cause:', '["Hypoglycaemia", "Hypertension and bradycardia", "Bronchospasm", "Hypotension and tachycardia"]'::jsonb, 3, 'It is given slowly or as an infusion.', 'NAP 431 · Applied Pharmacology III'),
(6, 75, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Ergometrine is avoided in patients with:', '["Postpartum haemorrhage", "Pre-eclampsia or hypertension", "Mild iron-deficiency anaemia", "Normal blood pressure"]'::jsonb, 1, 'It causes vasoconstriction and severe hypertension.', 'NAP 431 · Applied Pharmacology III'),
(6, 76, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Misoprostol is used in obstetrics to:', '["Stop lactation after a stillbirth", "Relax the uterus in preterm labour", "Prevent or treat PPH and ripen the cervix", "Lower blood pressure in pre-eclampsia"]'::jsonb, 2, 'It is a prostaglandin E1 analogue; side effects include fever and shivering.', 'NAP 431 · Applied Pharmacology III'),
(6, 77, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Heparin is reversed by:', '["Flumazenil", "Protamine sulphate", "Naloxone", "Vitamin K"]'::jsonb, 1, 'Protamine may cause hypotension and anaphylactoid reactions.', 'NAP 431 · Applied Pharmacology III'),
(6, 78, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Warfarin''s effect is reversed urgently with:', '["Aspirin given orally at once", "Protamine sulphate given slowly", "Tranexamic acid alone, IV", "Vitamin K with prothrombin complex"]'::jsonb, 3, 'Fresh frozen plasma is used if PCC is unavailable.', 'NAP 431 · Applied Pharmacology III'),
(6, 79, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Low molecular weight heparin should be stopped before neuraxial block for about:', '["1 hour before the block, for any dose", "12 h (prophylactic) or 24 h (treatment dose)", "No need to stop it before any block", "1 week before the block, for any dose"]'::jsonb, 1, 'This reduces the risk of spinal/epidural haematoma.', 'NAP 431 · Applied Pharmacology III'),
(6, 80, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Aspirin works as an anti-platelet agent by:', '["Irreversibly inhibiting cyclo-oxygenase", "Blocking the action of vitamin K", "Activating antithrombin in plasma", "Dissolving existing clots directly"]'::jsonb, 0, 'Its effect lasts the life of the platelet (7–10 days).', 'NAP 431 · Applied Pharmacology III'),
(6, 81, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Prophylactic antibiotics before surgery are given within:', '["After skin closure", "Only if infection occurs", "24 hours before admission", "60 minutes before incision"]'::jsonb, 3, 'Repeat doses are given in long operations or major blood loss.', 'NAP 431 · Applied Pharmacology III'),
(6, 82, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Gentamicin and neuromuscular blockers together may:', '["Cause hypertension", "Prevent nausea", "Prolong neuromuscular blockade", "Shorten neuromuscular blockade"]'::jsonb, 2, 'Aminoglycosides reduce acetylcholine release.', 'NAP 431 · Applied Pharmacology III'),
(6, 83, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Dexamethasone is given in anaesthesia for:', '["Preventing PONV and reducing airway oedema", "Inducing sleep at the start of anaesthesia", "Treating hypoglycaemia in diabetic patients", "Reversing non-depolarising muscle relaxants"]'::jsonb, 0, 'It may raise blood glucose.', 'NAP 431 · Applied Pharmacology III'),
(6, 84, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Hydrocortisone is used in anaesthesia for:', '["Steroid cover and adrenal insufficiency", "Pain relief after major surgery", "Muscle relaxation for intubation", "Anticoagulation after surgery"]'::jsonb, 0, 'It is also used as an adjunct in anaphylaxis.', 'NAP 431 · Applied Pharmacology III'),
(6, 85, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Insulin and dextrose are given in hyperkalaemia to:', '["Shift potassium into cells", "Stabilise the heart membrane", "Remove potassium from the body", "Increase potassium levels"]'::jsonb, 0, 'Calcium stabilises the myocardium; resins or dialysis remove potassium.', 'NAP 431 · Applied Pharmacology III'),
(6, 86, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Magnesium sulphate toxicity is first detected by:', '["Rising blood pressure", "Polyuria and thirst", "Marked tachycardia", "Loss of patellar reflexes"]'::jsonb, 3, 'Respiratory depression follows at higher levels; calcium gluconate is the antidote.', 'NAP 431 · Applied Pharmacology III'),
(6, 87, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Salbutamol is a:', '["Inhaled corticosteroid", "Beta-blocking antihypertensive", "H1 receptor antihistamine", "Beta-2 agonist bronchodilator"]'::jsonb, 3, 'It can cause tachycardia, tremor and hypokalaemia.', 'NAP 431 · Applied Pharmacology III'),
(6, 88, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'The nurse''s role in drug acquisition includes:', '["Using any drug available without checking it first", "Accepting damaged packs to avoid delaying supplies", "Ordering the right stock and checking delivery and expiry", "Ordering stock from memory without a stock list"]'::jsonb, 2, 'Proper acquisition prevents stock-outs and errors.', 'NAP 431 · Applied Pharmacology III'),
(6, 89, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Drug storage in the anaesthetic room requires:', '["Right temperature, security, and separating look-alikes", "Mixing different drugs in the same box", "Keeping all drugs together in an open tray", "Storing drugs in direct sunlight by the window"]'::jsonb, 0, 'Controlled drugs are kept locked; some need refrigeration.', 'NAP 431 · Applied Pharmacology III'),
(6, 90, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Patient education about anticoagulants should include:', '["Taking aspirin freely for any pain", "No need for any follow-up or blood tests", "Stopping the drug as soon as they feel well", "Bleeding signs, regular tests and drug interactions"]'::jsonb, 3, 'Patients should inform all health workers that they take anticoagulants.', 'NAP 431 · Applied Pharmacology III'),
(6, 91, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'The four main functions of management are:', '["Buying, selling, storing and counting", "Planning, organising, directing and controlling", "Teaching, learning, testing and grading", "Hiring, firing, paying and promoting"]'::jsonb, 1, 'Staffing is sometimes added as a separate function.', 'GST 420 · Principles of Management & Teaching'),
(6, 92, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'A strategic plan in a hospital department is:', '["A one-off plan for an emergency", "A single shift duty roster", "A daily list of tasks for the staff", "Long-term, setting direction for years"]'::jsonb, 3, 'Operational plans are short-term and detailed.', 'GST 420 · Principles of Management & Teaching'),
(6, 93, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'The decision-making process begins with:', '["Evaluating results", "Implementing the solution", "Choosing the cheapest option", "Identifying the problem"]'::jsonb, 3, 'Steps: identify, gather information, generate options, choose, implement and evaluate.', 'GST 420 · Principles of Management & Teaching'),
(6, 94, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'Delegation of responsibility means the nurse leader:', '["Does everything personally", "Avoids decision-making", "Assigns tasks but remains accountable", "Gives away accountability completely"]'::jsonb, 2, 'Delegation must match the competence of the person.', 'GST 420 · Principles of Management & Teaching'),
(6, 95, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'Democratic leadership involves:', '["Avoiding leadership", "Involving staff in decisions", "Punishing staff for mistakes", "Making decisions alone"]'::jsonb, 1, 'It improves morale but may be slow in emergencies.', 'GST 420 · Principles of Management & Teaching'),
(6, 96, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'An organisational chart shows:', '["The doses of drugs used in theatre", "The diagnoses of patients on the list", "The theatre schedules for the week", "Lines of authority and communication"]'::jsonb, 3, 'It clarifies roles and reporting relationships.', 'GST 420 · Principles of Management & Teaching'),
(6, 97, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'Staffing in a theatre department involves:', '["Only buying the equipment for theatre", "Recruiting, assigning and developing staff", "Only scheduling the surgeons'' lists", "Only cleaning the theatres each day"]'::jsonb, 1, 'Adequate staffing improves safety.', 'GST 420 · Principles of Management & Teaching'),
(6, 98, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'The principle of teaching that says learning is easier from simple to complex means:', '["Teach topics in a random order", "Avoid practical teaching completely", "Teach basic concepts before advanced ones", "Start with the hardest topics first"]'::jsonb, 2, 'Other principles include known to unknown and active learner involvement.', 'GST 420 · Principles of Management & Teaching'),
(6, 99, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'Directing in management includes:', '["Planning the yearly budget only", "Writing policies and nothing else", "Leading, motivating and communicating", "Ordering equipment for the unit"]'::jsonb, 2, 'Effective direction improves performance and morale.', 'GST 420 · Principles of Management & Teaching'),
(6, 100, 'Anaesthesia Nursing Mock — Day 2 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'Controlling in management means:', '["Setting goals without checking them", "Avoiding any feedback to the staff", "Restricting the freedom of the staff", "Measuring performance and correcting deviations"]'::jsonb, 3, 'Audit and supervision are controlling tools.', 'GST 420 · Principles of Management & Teaching');
