-- Anaesthesia Nursing (Nurse Anaesthetist) mock exams — Day 1 and Day 2 (600 questions: 6 papers of 100).
-- Day 1  Morning: NAP 411 Fundamentals (35), NAP 410 A&P I (35), NAP 412 Physics, Chemistry & Radiology (30)
--        Afternoon: NAP 413 Pharmacology I (35), NAP 414 Nursing Anaesthesia Practice (35), GSM 410 Microbiology (30)
--        Night: GSB 410 Behavioural Science 20, GSR 410 Research 25, GSE 410 Ethico-Legal 25, GSC 410 ICT 15,
--               English 8, Entrepreneurship 7
-- Day 2  Morning: NAP 423 General Anaesthesia I (40), NAP 421 Pharmacology II (35), NAP 430 A&P II (25)
--        Afternoon: NAP 422 Chemical Pathology & Haematology (30), NAP 424 Resuscitation & ICU (35),
--                   NAP 425 Special Surgery I (35)
--        Night: NAP 432 General Anaesthesia II (35), NAP 433 Special Surgery II (35), NAP 431 Pharmacology III (20),
--               GST 420 Management & Teaching (10)
-- The questions are added as hidden exam-only questions (not shown in the practice app). The 6 exams are
-- created for the ANAESTHESIA NURSING section only (specialty = 'anaes'); other sections never see them.
-- Times (Nigeria time) can be changed later on the admin page.
-- If an exam already exists, only its questions are updated. Safe to run more than once.
set lock_timeout = '5s';
begin;
alter table public.exam_exams add column if not exists specialty text not null default 'ccn';
create temporary table annew (paper int, n int, source text, topic text, q text, opts jsonb, ans_idx int, exp text, category text, primary key (paper, n)) on commit drop;
select (select coalesce(max(id), 0) from public.questions) + row_number() over (order by d.paper, d.n), d.topic, d.source, d.q, d.opts, d.ans_idx, d.exp, d.category, '💉', false
from annew d
where not exists (select 1 from public.questions x where x.source = d.source and x.q = d.q);
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from annew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 1), instructions = 'Anaesthesia Nursing — Day 1 Morning. 100 questions: NAP 411 · Fundamentals of Nursing Anaesthesia, NAP 410 · Applied Anatomy & Physiology I, NAP 412 · Applied Physics, Chemistry & Radiology. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.', specialty = 'anaes'
 where title = 'Anaesthesia Nursing Mock — Day 1 Morning (100 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Anaesthesia Nursing Mock — Day 1 Morning (100 Questions)', 'Anaesthesia Nursing — Day 1 Morning. 100 questions: NAP 411 · Fundamentals of Nursing Anaesthesia, NAP 410 · Applied Anatomy & Physiology I, NAP 412 · Applied Physics, Chemistry & Radiology. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.',
       timestamptz '2026-11-04 08:00:00+01', timestamptz '2026-11-04 10:00:00+01', 100, (select array_agg(x.id order by d.n) from annew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 1),
       true, true, 100, true, true, 1, 'relaxed', 'anaes'
where not exists (select 1 from public.exam_exams where title = 'Anaesthesia Nursing Mock — Day 1 Morning (100 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from annew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 2), instructions = 'Anaesthesia Nursing — Day 1 Afternoon. 100 questions: NAP 413 · Applied Pharmacology I, NAP 414 · Nursing Anaesthesia Practice, GSM 410 · Applied Microbiology. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.', specialty = 'anaes'
 where title = 'Anaesthesia Nursing Mock — Day 1 Afternoon (100 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Anaesthesia Nursing Mock — Day 1 Afternoon (100 Questions)', 'Anaesthesia Nursing — Day 1 Afternoon. 100 questions: NAP 413 · Applied Pharmacology I, NAP 414 · Nursing Anaesthesia Practice, GSM 410 · Applied Microbiology. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.',
       timestamptz '2026-11-04 12:00:00+01', timestamptz '2026-11-04 14:00:00+01', 100, (select array_agg(x.id order by d.n) from annew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 2),
       true, true, 100, true, true, 1, 'relaxed', 'anaes'
where not exists (select 1 from public.exam_exams where title = 'Anaesthesia Nursing Mock — Day 1 Afternoon (100 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from annew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 3), instructions = 'Anaesthesia Nursing — Day 1 Night. 100 questions: GSB 410 · Applied Behavioural Science, GSR 410 · Research Methodology & Statistics, GSE 410 · Ethico-Legal Issues, GSC 410 · ICT & Nursing Informatics, Use of English & Communication, Entrepreneurship. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.', specialty = 'anaes'
 where title = 'Anaesthesia Nursing Mock — Day 1 Night (100 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Anaesthesia Nursing Mock — Day 1 Night (100 Questions)', 'Anaesthesia Nursing — Day 1 Night. 100 questions: GSB 410 · Applied Behavioural Science, GSR 410 · Research Methodology & Statistics, GSE 410 · Ethico-Legal Issues, GSC 410 · ICT & Nursing Informatics, Use of English & Communication, Entrepreneurship. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.',
       timestamptz '2026-11-04 19:00:00+01', timestamptz '2026-11-04 21:00:00+01', 100, (select array_agg(x.id order by d.n) from annew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 3),
       true, true, 100, true, true, 1, 'relaxed', 'anaes'
where not exists (select 1 from public.exam_exams where title = 'Anaesthesia Nursing Mock — Day 1 Night (100 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from annew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 4), instructions = 'Anaesthesia Nursing — Day 2 Morning. 100 questions: NAP 423 · General Anaesthesia I, NAP 421 · Applied Pharmacology II, NAP 430 · Applied Anatomy & Physiology II. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.', specialty = 'anaes'
 where title = 'Anaesthesia Nursing Mock — Day 2 Morning (100 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Anaesthesia Nursing Mock — Day 2 Morning (100 Questions)', 'Anaesthesia Nursing — Day 2 Morning. 100 questions: NAP 423 · General Anaesthesia I, NAP 421 · Applied Pharmacology II, NAP 430 · Applied Anatomy & Physiology II. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.',
       timestamptz '2026-11-05 08:00:00+01', timestamptz '2026-11-05 10:00:00+01', 100, (select array_agg(x.id order by d.n) from annew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 4),
       true, true, 100, true, true, 1, 'relaxed', 'anaes'
where not exists (select 1 from public.exam_exams where title = 'Anaesthesia Nursing Mock — Day 2 Morning (100 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from annew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 5), instructions = 'Anaesthesia Nursing — Day 2 Afternoon. 100 questions: NAP 422 · Chemical Pathology & Haematology, NAP 424 · Resuscitation & Intensive Care, NAP 425 · Anaesthesia for Special Surgery I. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.', specialty = 'anaes'
 where title = 'Anaesthesia Nursing Mock — Day 2 Afternoon (100 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Anaesthesia Nursing Mock — Day 2 Afternoon (100 Questions)', 'Anaesthesia Nursing — Day 2 Afternoon. 100 questions: NAP 422 · Chemical Pathology & Haematology, NAP 424 · Resuscitation & Intensive Care, NAP 425 · Anaesthesia for Special Surgery I. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.',
       timestamptz '2026-11-05 12:00:00+01', timestamptz '2026-11-05 14:00:00+01', 100, (select array_agg(x.id order by d.n) from annew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 5),
       true, true, 100, true, true, 1, 'relaxed', 'anaes'
where not exists (select 1 from public.exam_exams where title = 'Anaesthesia Nursing Mock — Day 2 Afternoon (100 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from annew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 6), instructions = 'Anaesthesia Nursing — Day 2 Night. 100 questions: NAP 432 · General Anaesthesia II, NAP 433 · Anaesthesia for Special Surgery II, NAP 431 · Applied Pharmacology III, GST 420 · Principles of Management & Teaching. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.', specialty = 'anaes'
 where title = 'Anaesthesia Nursing Mock — Day 2 Night (100 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Anaesthesia Nursing Mock — Day 2 Night (100 Questions)', 'Anaesthesia Nursing — Day 2 Night. 100 questions: NAP 432 · General Anaesthesia II, NAP 433 · Anaesthesia for Special Surgery II, NAP 431 · Applied Pharmacology III, GST 420 · Principles of Management & Teaching. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.',
       timestamptz '2026-11-05 19:00:00+01', timestamptz '2026-11-05 21:00:00+01', 100, (select array_agg(x.id order by d.n) from annew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 6),
       true, true, 100, true, true, 1, 'relaxed', 'anaes'
where not exists (select 1 from public.exam_exams where title = 'Anaesthesia Nursing Mock — Day 2 Night (100 Questions)');
select title, specialty, cardinality(question_ids) as questions, starts_at, ends_at
  from public.exam_exams where title like 'Anaesthesia Nursing Mock — Day %' order by starts_at;
commit;
